window.__D("text/likkut-maanot-kodesh/c014",{"p":[[9200220038,"38\nמענות קודש – ה ' תשמ \" ג\n[4 למכתבם צירפו מכתב להמזכיר רחי \" ק .]\nכ \" ק אדמו \" ר שליט \" א סימן בחץ ובעיגול את שם נמען - מכתבם \" לכבוד\nהרה \" ג יהודה קרינסקי שליט \" א .\"\nמח\nועש \" ק ויחי , ט \" ו טבת ][\nמענה לר ' שניאור זלמן גורארי ' ור ' משה פנחס הכהן כ \" ץ שכתבו : \" היות\nשהפלענער הראשונים להרחיב בית הכנסת ובית המדרש דליובאוויטש\nשבליובאוויטש שהגשנו לפנים להוד כבוד קדושת אדמו \" ר שליט \" א לא\nנתאשרו מפני גודש הסכום . . הנה הוכן ע \" י הארכיטקט פלענער חדשים\nשלא יעלו לסכו ם עצום . . והננו מבקשים חוות דעתו הקדושה וברכתו\nהקדושה על זה \" ( ס ' \" בכל ביתי נאמן הוא \" ע ' 360 . \" בית משיח \" גליון\n270 והעתקה :).\nנת ' כל ההבטחות דלהלן וכו ' –\nידוע הפס \" ד שמותר וכדאי למכור בהכנ \" ס לצורך מקוה .\nהבטיחוני שתהי ' המקוה גמורה באמצע הקייץ , ואח \" כ – לפני ר \" ה ,\nואח \" כ – לחה \" ס , ואח \" כ – במשך ב - ג שבועות . יד טבת – הייתי בבנין\nהמקוה – ובעוד ג ' שבועות ג \" כ לא יהי ' גמור . באם באמת מעונינים\nבטובת ביהמ \" ד –\nטובתו שימכרוהו וימסרו הכסף לאיש שאינו מליובאוויטש – ויתנו לו\nעשרת אלפים שכר טרחתו , ובלבד שיגמור המקוה במשך ג ' שבועות ,\nואיש מליובאוויטש לא יתן לו עצות כלל .\nמט\nי \" ז טבת ][\nממענה לא ' ששאל אם צריך להמתין עד חצות לקיום מצות עונה , כשיש\nלו קביעות ללמוד בהשכמה ( לקו \" ש חכ \" א ע ' 455 :)\n.[ ]. 2 ) צע \" ג אם חל בדורותינו שמביא שבמשך כו \" כ שעות המחשבה\nשקוע מתי כבר וכו ' וכו ,'\n3 חילוקים מנהגים ויברר מנהג אבותיו וכו .')"],[9200220039,"39\nמענות קודש – ה ' תשמ \" ג\nנ\nח \" י טבת ][\nמענה לאחת מנשות אנ \" ש שכתבה ע \" ד אביזרים מיוחדים שרוצה לייצר\nעבור \" צבאות השם \" (\" התקשרות \" גליון עב :)\n1 ) בכלל טוב ונכון כהנ \" ל במאוד , ומקום לומר שיהיו הרבה , כו \" כ\nאירגונים וגם יחידים , שישתמשו בו וגם יקנוהו .\n2 ) ביחד עם זה מובן שנוגע במאוד – שיעשו הפרטים ( דהשעון , הגלגל\nוכו ' ) כמתאים לגיל זה – ולכן צ \" ל התייעצות עם מומחים בזה , ועוד –\nלהתחיל בב ' - ג ' דוגמאות ( בכמות לא גדולה ) וע \" פ תגובת הציבור –\nיחליטו איזה העיקר ואיזו טפלים וכו ', אזכיר עה \" צ ותבש \" ט .\nנא\nכ \" א טבת ][\nמענה לחברי ה \" ועד להפצת שיחות \" שכתבו : \" בלילה אור לכ \" א טבת\nהיתה שריפה בחדרי בית הדפוס שלנו ונשרף לגמרי החדר עם כל מכונות\nהדפוס והקיפול וכו '. בכל שאר החדרים כולל גם הסטאק של כרכי\nהלקו \" ש , לא הגיעה השריפה ב \" ה , ולא נגרם שם נזק . . ומבקשים ברכת\nכ \" ק אדמו \" ר שליט \" א שההיזק יוחזר בשלימותו ולא יחסר ח \" ו כלל וכלל\nבעבודה של הלקו \" ש , ושנצליח ובזריזות בבנית ושכלול הועד \" ( מצילום\nכתי \" ק – \" בית משיח \" גליון 270 :)\nויה \" ר שיקויים בהם מאמר קדו \" ע המפורסם וכו ' ויבש \" ט בטוב\nהנרוהנ \" ג ובפרט מהצלחם רבה בהפצת המעינות חוצה וכו '\nקבלה . אזכיר עה \" צ . להחזיר .\nנב\nכ \" א טבת ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א להרב זלמן שמעון\nדווארקין – בהמשך להשריפה שפרצה במשרדי ה \" ועד להפצת שיחות \"\nאשר בבנין 770 ( מצילום כתי \" ק – תשורה לוין י \" ט אד \" ר תשס \" ה :)"],[9200220040,"40\nמענות קודש – ה ' תשמ \" ג\nב \" ה .\nבודאי נודע ע \" ד השריפה , ל \" ע ול \" ע , היום בוקר , והגיעו המים וכו '\nוהזיק להביהכ \" ס , ובנס לא נגע בהס \" ת וכו '\n– אף שאין לדבר עד \" ז , ופשיטא לא לפרסום ( שלא להפחיד וכו ' )\n– ולטובת הביהכנ \" ס ( ככתבי מאז – ולצערי לא נעשה ממשית בזה ע \" ע .\nוד \" ל ) – מוסג \" ב – תמורת הנ \" ל – מאיש שאינו דר בשכונה זו , ופשיטא\nשאין לו דעה לא בועד המקוה , ולא דהשכונה , ולא דהרבני דהשכונה :\nעשרת אלפים דולר ( ע \" פ כתבי אז ), אלף להביהכנ \" ס ואלף – נדבתו\nלהמקוה .\nוהקונה לא יפרסם עדכ \" ז ( מפני כבוד ליובאוויטש וכבודי ) – ולא יתערב\nבהנהלת ביהכנ \" ס כלל ,\nאבל אין כל רשות להקטין הבנין או להרחיבו , או לעשות בו שינוי חשוב\n– נגד רצונו – וכל כיו \" ב\n___\nוה ' יגדור פרצות עמו בכלל ובפרט וכו ' – ויקויים מאמר קדו \" ע\nהמפורסם , ויבנו במקום הנ \" ל – כהוראות ( ונתינת כח ) באגה \" ק דאדה \" ז\nוהצ \" צ .\nואך טוב הנרונ \" ג יהי ' כאן ובכ \" מ בנ \" י שליט \" א .\nנג\nועש \" ק שמות , כ \" ב טבת ][\nמענה לר ' לוי גאלדשטיין שביקש ברכה עבור א ' שמניח עמו תפלין מדי\nיום ועש \" ק זה כו \" כ שנים , שאינו בקו הבריאות ( מהעתקה . המענה\nמתפרסם בזה לראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\nאזכיר עה \" צ"],[9200220041,"41\nמענות קודש – ה ' תשמ \" ג\nנד\nשלהי טבת ][\nמענה כללי - פרטי דימים אלו [ בין השאר – להרב דוד ראסקין על דו \" ח\nמההשתדלות בהדפסת קובצי חידושי תורה בכמה מקומות ( מהעתקה ,\nבאדיבות מערכת הספר \" ועבדי דוד :])\"\nנת ' ות \" ח .\nודבר בעתו –\nבסמיכות לר \" ח שבט – עשתי עשר חדש באחד לחדש\nאזכיר עה \" צ\nנה\nי \" ג שבט ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א להרב מנשה קליין ( אב \" ד\nאונגוואר ) – בהמשך להמדובר ב \" יחידות \" שלו אור לי \" ג שבט , שבה דובר\nבין השאר ע \" ד עריכת \" ספר יוחסין \" לכלל ישראל , בקשר עם הגזירה\nד \" מיהו יהודי \" ( מצילום כתי \" ק – תשורה זאנדהויז ר \" ח שבט תשס \" ח :)\nבהמשך להמדובר אמש בנוגע לספר יוחסין וגודל האחריות שבדבר , כיון\nשמעולם לא הייתה כזאת –\nהתבוננתי עוה \" פ בזה ולפענ \" ד :\nא ) בנוגע לפועל – ע \" פ מצב היחסים בין ארגוני הרבנים האורטודוקסים\nכאן ( ובכ \" מ ) – לא יעשה הספר בפועל ( מי הנאמן , האחראי , היושב\nבראש וכו ,)'\nב ) הדיבור יחריף היחסים ביניהם וכו ,'\nג ) הקונסרווא טיווים וגם מהנ \" ל )( ירעישו שהקנאים רוצים לפ לג עם\nישראל בכ \" מ , ואפילו באמצעים שהקנאים באונגארן מאז לא נקטו בזה\nד ) ירעישו באה \" ק נגד הכנס האחרון דמיהו יהודי , \" שנגלתה כוונה\nהאמתית \" וכו ' וכו ' – ז . א ."],[9200220042,"42\nמענות קודש – ה ' תשמ \" ג\nכיון שברור שעתה ובעתיד הקרוב לא יבוא הספר בפועל , ומאידך – עלול\nאפילו רק הדיבור עד \" ז למחלוקת גדולה וביותר – לדעתי אין מתאים\nכלל וכלל להעלות השאלה אפילו בדיבור בעלמא – לע \" ע ובעתיד הקרוב\nכי המחלוקת וכו ' – בגדר ודאי\nוהתועלת – גם בגדר שמא אינה ( וחוזרני ממה שאמרתי בזה אמש .)\nואת כת \" ר הסליחה \" ודברים שאמרתי וכו '\nמהיר\nח\n[ כ \" ק אדמו \" ר שליט \" א הורה ע \" י המזכירות לא לפרסם את המדובר\nבר \" ד מהביקור ( הר \" ד – בס ' \" בצל החכמה \" ע ' 171 ואילך . חלק הר \" ד\nהמדובר – ב \" בית משיח \" גליון 486 .])\nנו\n[ לאחר ש \" פ בשלח , ט \" ו בשבט ( 1 ])\nמענה ל \" ועד הנחות בלה \" ק \" על שאלותיהם בהמבואר בהתועדות ש \" פ\nבשלח ( מצילום כתי \" ק – יחי המלך \" גליון תקד :)\"\nא . במכתבם כתבו :\nנתבאר בפרש \" י שבכל מקום יש ללמוד בפשש \" מ כפי המופיע בפסוק זה ,\"\nולכן : כאשר לומדים לראשונה אודות \" עמוד הענן \", הרי הפירוש בזה\nהוא שה \" ענן \" הי ' בצורת \" עמוד \" בלבד , וכאשר לומדים שהענן הגין\nמהחצים ובליסטראות – בהכרח לומר ( בפשש \" מ ) שהענן הי ' לכל רוחב\nהמחנה , וגם מצידי המחנה ( מפני הצורך לקבל חצים כו ' מכל הכיוונים ,)\nובסיום הפרשה – \" צא מן הענן \", בהכרח לפרש שהענן הקיף את כל\nהמחנה מכל צדדיו ( שלכן אין אפשרות אחרת אלא לצאת מן הענן ,\nכלומר , לעבור דרך הענן , ולא להקיפו מצדו .)\nולכאורה , הכוונה בזה שבתחילה הי ' אמנם עמוד הענן רק לפני המחנה\n(\" לנחותם הדרך \"), ובצורת \" עמוד \" בלבד , ואח \" כ , כאשר הי ' צורך להגן\nעל בנ \" י מפני החצים כו ' – אזי \" ויסע עמוד הענן מפניהם ויעמוד\nמאחריהם ( ולא רק מאחריהם , אלא גם מצידי המחנה כו '). דלכאורה ,\""],[9200220043,"43\nמענות קודש – ה ' תשמ \" ג\nאא \" ל שמפסוק זה למדים שכבר בתחילה הי ' הענן גם מאחורי המחנה –\nשהרי מפורש בקרא \" ויסע עמוד הענן מפניהם ויעמוד מאחריהם \" ( מכיון\nשמקודם לכן לא הי ' מאחריהם .)\nועפ \" ז – לא תפסנו מהי הקושיא ( מעיקרא ) כיצד ראו בנ \" י ש \" מצרים נוסע\nאחריהם \" למרות שהענן הי ' מפסיק בינם לבין מצרים – הרי מסדר\nהכתובים משמע , לכאורה , שבתחילה ראו בנ \" י את מצרים , ורק אח \" כ\n( כאשר המצרים התקרבו יותר למחנה ישראל , באופן שיכלו לפגוע בהם\nח \" ו ע \" י החצים כו )' – אזי \" ויסע עמוד הענן מפניהם ויעמוד מאחריהם \"\nכדי להגן על בנ \" י . וא \" כ , לכאורה , מה שראו את המצרים – הי ' זה לפני\nשהענן הפסיק בין ב ' המחנות ( שהרי \" ויסע עמוד הענן גו '\" נאמר בפסוק\nי \" ט , לאחרי אמירת הקב \" ה למשה \" מה תצעק אלי גו \"' ולאחרי צעקת\nבנ \" י כתוצאה מראייתם ש \" מצרים נוסע אחריהם .\"?)\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n[1 ] על מה שכתבו : \" נתבאר בפרש \" י שבכל מקום יש ללמוד בפשש \" מ כפי\nהמופיע בפסוק זה \", כתב :\nנתבאר בפרש \" י שבכל מקום יש ללמוד בפשש \" מ כפי המו ][ בן מהענין\nבפסוק זה ][\n[2 על מה שכתבו : \" הרי הפירוש בזה הוא שה \" ענן \" הי ' בצורת \" עמוד \"]\nבלבד \" – מחק תיבת \" בלבד \", וכתב :\nהרי הפירוש בזה הוא שה \" ענן \" הי ' בצורת \" עמוד ]\"[ דמספיק \" לנחותם\nהדרך \"\n[3 על כללות השאלה , כתב :]\nאין הכרח ונוגע לאיזה צד שיהי ' בפפש \" מ ( ואם יש – ה \" ז שלא הי '\nשינוי ) ולכן אין רש \" י \" מתעסק \" בזה .\nב . במכתבם כתבו :\n\" בנוגע לקושיא איך ראו בנ \" י את מצרים למרות הענן שביניהם – נתבאר ,\nשאין כל הכרח לומר שהענן הי ' עב עד כדי כך שלא יכלו לראות דרכו ,\nובפרט ראיית מחנה עצום של רכב ופרשים כו ' ( כשם שראו דרך הענן את\nאור השמש כו '), ומה שהענן הי ' צריך לעצור בעד החצים כו ' – הרי זה\nיכול להיות ע \" ד ובדוגמת חומר הזכוכית וכיו \" ב , שיכולים לראות דרכו ,\nעם היותו מפסיק בעד חצים כו .'"],[9200220044,"44\nמענות קודש – ה ' תשמ \" ג\nולא תפסנו : רש \" י מבאר שפעולת הענן ( מלבד קבלת החצים ) היתה גם\nכדי \" להחשיך למצרים \". ולכאורה , מוכח מכאן שלא היתה אפשרות\nלראות דרך הענן , שהרי הענן החשיך למצרים . ומה גם שמאורע זה הי '\nבלילה , כפי שמפרש רש \" י : \" ויסע עמוד הענן – כשחשכה . . לא נסתלק\nכמו שהי ' רגיל להסתלק ערבית , אלא נסע והלך לו מאחריהם להחשיך\nלמצרים \". כלומר : אפילו אם אור השמש הי ' יכול לחדור דרך עמוד הענן ,\nהרי בלילה החשיך הענן לגמרי . וא \" כ , לכאורה , כשם שהענן החשיך\nוהסתיר למצרים ( שלא יהי ' להם את אורו של \" עמוד האש \"), כך לא יכלו\nבנ \" י לראות את המצרים דרך הענן ( שהרי הקב \" ה לא יעשה נס – שבנ \" י\nיוכלו לראות דרך ענן המסתיר – כדי להפחיד את בנ \" י ). ועפ \" ז , לכאורה ,\nמה שבנ \" י ראו את מצרים – הי ' זה ( לכאורה ) לפני שהענן נסע כדי\nלהפסיק בין ב ' המחנות ( בעוד יום .\")\nמענה כ \" ק אדמו \" ר שליט \" א :\n[4 ] על מה שכתבו : \" ולכאורה , מוכח מכאן שלא היתה אפשרות לראות\nדרך הענן \" – סימן בעיגול תיבת \" ולכאורה \", וכתב :\nישאלו בן ה ' ויסבירם אשר [ להחשיך ] הוא ע \" י כיסוי אור ( השמש\nובנדו \" ד ) הלבנה היינו מלמעלה\n[5 ] על מה שכתבו : \" כלומר : אפילו אם אור השמש הי ' יכול לחדור דרך\nעמוד הענן \", כתב :\nלשיטתם – בלילה מנין אור השמש ][\nבן ה ' אומר שמפורש : המאור הקטן – בלילה\n[6 ] על מה שכתבו : \" הרי בלילה החשיך הענן לגמרי \" – סימן בעיגול תיבת\nלגמרי \", וכתב :\"\nלשיטתם ( בכדי שיוקשה ממש \" נ \" ויראו גו )\"'\nלשיטת בן ה ' – \" לנחותם הדרך \" מספיק ענן הכי קל ."],[9200220045,"45\nמענות קודש – ה ' תשמ \" ג\nנז\n[ לאחר ש \" פ בשלח , ט \" ו בשבט ( 2 ])\nמענה ל \" ועד הנחות בלה \" ק \" על מכתבם בהמשך להמענה שקיבלו על\nשאלתם בהמדובר בהתועדות ש \" פ בשלח , ששאלו מהי הקושיא איך ראו\nבנ \" י דרך הענן המסתיר שמצרים נוסע אחריהם , והרי לכאורה מסדר\nהכתובים משמע שהענן הי ' כל הזמן מלפניהם ורק כשהמצרים התקרבו\nעבר לאחריהם . במכתבם כתבו : \" לאחרי המענה עדיין לא תפסנו . \".\nופירטו את שלא הבינו ( מצילום כתי \" ק – יחי המלך \" גליון תק :)\"\nמה זה שייך להמענה ה \" ז קלאץ קושיא מעיקרא !?\nובכ \" ז התפלפלו בזה , וגם מהועד !! ( 1)\nוסו \" ס האט מען זיך געחא פט ותודה עכ \" פ ע \" ז !\nאלא שגם בזה ( מתוך חריפתא וכו )' – בפשש \" מ פרש \" י שהענן הגין\nמהחצים וכו ', שעפ \" ז פשוט שכשהייתה התחלת החצים הייתה כבר\nההגנה . וא \" צ להדגיש עוה \" פ שאין מונחים כמדובר לאחרונה\nנח\n[ לאחר ש \" פ בשלח , ט \" ו בשבט ( 3 ])\nמענה ל \" ועד הנחות בלה \" ק \" על מכתבם – בהמשך להמענות שקיבלו על\nשאלותיהם בהתועדות ש \" פ בשלח :\nאודות הקושיא בשיחה כיצד ראו בנ \" י את מצרים דרך הענן , שאלנו ,\"\nשלכאורה , \" ויסע גו ' ויעמוד מאחריהם \" הי ' לאח \" ז . ועל זה ענה כ \" ק\nאדמו \" ר שליט \" א : דמכיון שפרש \" י שהענן הגין מהחצים כו ' פשוט\nשכשהיתה התחלת החצים היתה כבר ההגנה .\nהאם הכוונה היא ש \" ויסע גו '\" הי ' מיד כאשר \" פרעה הקריב \" ( שאז היתה\nאפשרות לזרוק חצים ), לפני ש \" וישאו בנ \" י את עיניהם והנה מצרים נוסע\nכו '\", והכתובים הם שלא כסדר המאורעות .\n[ בפרש \" י – ויסע עמוד הענן \"\" – \" כשחשכה \". ולכאורה , \" וישאו בנ \" י את\nעיניהם גו '\" הי ' ביום ( לפנ \" ז .])"],[9200220046,"46\nמענות קודש – ה ' תשמ \" ג\nב ) במשנ \" ת בהשיחה שהענן הי ' ע \" ד חומר של זכוכית שאינו מסתיר –\nאיך זה מתאים עם פרש \" י ד \" ה ויסע : \" להחשיך למצרים \". ומ \" ש כ \" ק\nאדמו \" ר שליט \" א שהענן החשיך \" ע \" י כיסוי אור הלבנה היינו מלמעלה \"\n– לא תפסנו , כי באם הי ' כמו חומר של זכוכית אינו מסתיר גם מלמעלה .\n[ אחדים רצו לומר שלמעלה הי ' הענן חומר שמכסה ומסתיר \"( להחשיך\nלמצרים ,)\" ובאמצע ( בין ישראל למצרים , כדי לקבל החצים ) הי ' כמו\nזכוכית , ולכן יכלו ישראל לראות את מצרים . אבל בפשטות , הרי זה דוחק\nגדול לחלק כן , ונוסף לזה : כדי שמצרים לא יהנו מאורו של עמוד האש\n( שהלך לפני מחנה ישראל ), הי ' צורך שיהי ' ענן המחשיך גם בי ן המחנות .]\nג ) בנוגע למשנ \" ת שהענן הי ' מקבל החצים – בפרש \" י יתרו יט , ד : \" והענן\nמקבלם \". אבל בפרש \" י בשלח ( יד , יט ) משמע שהם ב ' ענינים שונים :\nהמלאך – לקבל חצים , והענן – להחשיך למצרים ( כמצויין גם בלקו \" ש\nחי \" ח ע ' 256 הע ' 32 .\")\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תקה :)\"\n[1 על כללות השאלות , כתב :]\nבכל השקו \" ט – חסר תירוץ עקרי ע \" פ המפורש בפרש \" י לפנ \" ז יג , כב\nשעד שלא שקעה כו ' – היינו שהענן בא לאחריהם לא משחשכה ממש\n[2 ] על מה שכתבו : \" במשנ \" ת בהשיחה שהענן הי ' ע \" ד חומר של זכוכית\nשאינו מסתיר \", כתב :\nפשיטא שלא כוונתי שהענן הי ' של זכוכית !!\nאלא שהי ' ענן קל , שגם הוא מחשיך , אבל לא עד כ \" כ שאין רואין\nמציאות דמחנה רב וכו .'\n[3 ] על מה שכתבו : \" ומ \" ש כ \" ק אדמו \" ר שליט \" א שהענן החשיך \" ע \" י\nכיסוי אור הלבנה היינו מלמעלה כתב :\"\",\nזהו הוספתי להדגיש א ז מ ' שפא לט א האר ואין שמים לב להר ! מפורש\nמאחריהם ופשוט שהאור בלילה הוא מהלבנה שבשמים ולא מהארץ\n[4 על מה שכתבו : \" אבל בפשטות , הרי זה דוחק גדול לחלק כן \"] – סימן\nקו תחת תיבת \" בפשטות \", ומחק את התיבות \" דוחק גדול \", וכתב :\nהרי זה ][ היפך הפשטות לחלק כן ]["],[9200220047,"47\nמענות קודש – ה ' תשמ \" ג\n[5 ] על מה שכתבו : \" בנוגע למשנ \" ת שהענן הי ' מקבל החצים – בפרש \" י\nיתרו יט , ד : \" והענן מקבלם \". אבל בפרש \" י בשלח ( יד , יט ) משמע שהם ב '\nענינים שונים : המלאך – לקבל חצים , והענן – להחשיך למצרים \", כתב :\nקושיא בכל אופן מרש \" י לרש \" י\nנט\nשבט ][\nמענה לא ' שהודיע ע \" ד גניבה שאירעה אצלו ( לקו \" ש חכ \" ג ע ' 363 :)\n.[ ]. בדיקת המזוזות טלית קטן כשר ויה \" ר שיקוים בו מאמר קדוש \" ע\nהמפורסם אזכיר עה \" צ .\nס\nשבט ][\nמענה לר ' שלום דובער לוין שכתב – בקשר לגליונות הכוללים חידושים\nוביאורים לפורים ולתהלים שכתב הרה \" ג הרה \" ח הרב לוי יצחק ז \" ל\nאביו של כ \" ק אדמו \" ר שליט \" א , שהיו בין השאר בחבילת עלים נפרדים\nשמסר כ \" ק אדמו \" ר שליט \" א :\n\" המצו \" ב הי ' בין הדברים שנמסרו לאחרונה מחדר קדשו . האם למסרו\nלהדפיס לכבוד הפורים .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( קובץ \" עבודת הקודש אצל הרבי \" ע ' צג :)\nמהיר .\nלהוסיף בשולים מ \" מ וכו .'"],[9200220048,"48\nמענות קודש – ה ' תשמ \" ג\nסא\nשבט ][\nמענה להשליח ר ' יוסף דוד ווייטמאן ששאל בנוגע לארגון \" תפלה קצרה \"\nבבתי הספר הנכרים בפאלו ברזיל , לאור קריאת כ \" ק אדמו \" ר שליט \" א\nבהתועדות יו \" ד שבט ע \" ד ייסוד \" רגע של שתיקה \" – רגע של התבוננות\nותפלה לבורא העולם ומנהיגו – בבתי הספר הממשלתיים ( תשורה\nווייטמאן י \" א אלול תשס \" ו :)\nהם קטולים קנאים ויש חשש שיכריחו ח \" ו אותו האיש וד \" ל .\nבקשר ל \" רגע של שתיקה \"[ – ראה גם לקמן מענות : קכ ג , קכ ד , קל ט .]\nסב\nשבט ][\nמענה להשליח ר ' יוסף שמואל יהושע גערליצקי שכתב – בהמשך לדברי\nכ \" ק אדמו \" ר שליט \" א לאחרונה ע \" ד הוצאת קובצי חידושי תורה –\nשעומד להתחיל לעסוק בהוצאה לאור דקובץ תורני מרבני ודייני עירו\nתל - אביב , וכתב שישנם שני אפשרויות : ( 1 להו \" ל מיד ע \" י הבית חב \" ד ,)\nאו ( 2) לעשות זאת ע \" י המועצה הדתית של תל - אביב , אף שכך מטבע\nהדברים יקח יותר זמן ( תשורה אלטיין ט \" ו סיון תשע \" ח :)\nכדאי לחכות קצת ושיו \" ל ע \" י המועצ \" ד\nאזכיר עה \" צ\nסג\nכ \" ף שבט ][\nמענה לתלמידים השלוחים לישיבה גדולה ליובאוויטש קסבלנקה מרוקו\nשביקשו הסכמה וברכה לנסוע להיות אצל כ \" ק אדמו \" ר שליט \" א ליום\nהבהיר י \" א ניסן ולחזור כמה ימים לאחר חג הפסח ( תשורה מאצקין כ \" ב\nאד \" ר תשע \" ט :)\nוכל זה כעצת הרבא \" ג שליט \" א שיבקר עתה אצלם אזכיר על הציון"],[9200220049,"49\nמענות קודש – ה ' תשמ \" ג\nסד\nכ \" ה שבט ][\nמענה לר ' הלל דוד קרינסקי שכתב :\nאבי שי ' התדבר עם ידידנו מר יוסף שי '\" פאַפפ ואמר פאַפפ שבכל יום ב '\nבשבוע הטיאטער שלו ( שנק ' בשם \" פאבליק טיאטער \" במנהטן ) פנוי ,\nויכולים להשתמש בו כרצוננו בלי מחיר .\nאשר לכן עלה בדעתי אולי כדאי לנצל הנ \" ל לעשות נשף חב \" די קונצרט\nוכדומה עם סעודה בשתי ' וכו ' בהיום ב ' שלפני י \" א ניסן הבעל \" ט ( ז ' ניסן .)\nהחדר היותר גדול בבנינו הנ \" ל מכיל 300 מקומות ישיבה . ונשתמש\nבהחדר הנ \" ל לנשף כנ \" ל , ולמכור המקומות בדמי כניסה לבערך $200\nלכ \" א , והה כנסה מזה יהי ' להוצאות השידורים . מר פאַפפ שי ' הסכים לזה\nוהבטיח לסייע \" עד כמה שביכולתו \" שיהי ' ה \" פראדוסער \" וכו .'\nוהנני שואל אם לעשות כנ \" ל .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה קרינסקי ב '\nמרחשון תשס \" ח . ליקוט כתי \" ק יום הבהיר י \" א ניסן ע ' 46 :)\nמחק את התיבות \" והנני שואל \" וסימן בחץ את המשך הדברים , וכתב :\nב אם ][ רוצה לעשות כנ \" ל ][ בקשר לי \" א ניסן – לא , כי כפשוט – אין\nלחב \" ד עסק בטיאטר\nוכן לא בפרסומת אנשים מי שיהי '\nכ \" א בהפצת היהדות והתומ \" צ\nמהיר\nח\nסה\nשלהי שבט ][\nמענה בקשר להדפסת ענין היתר עבודת המקדש בשבת בכתב - עת אנגלי\nלילדים מכל החוגים ( לקו \" ש חכ \" א ע ' 502 :)\nהת ' הרעים יפרשוהו כהיתר לההנהגה בהטעמּפלס בש \" ק ."],[9200220050,"50\nמענות קודש – ה ' תשמ \" ג\nסו\nלאחר ש \" פ משפטים , ער \" ח אדר ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בהמדובר בהתועדות ש \" פ\nמשפטים :\n\" בהמשך להמבואר בהשיחה ע \" ד מ \" ש בסנהדרין ( קיא , א ) בנוגע לאוה \" ע\nלע \" ל – נזכר שכ \" ט שבט ( קביעות בימי החודש דשבת פ ' שקלים ) קשור\nעם אוה \" ע כו ', כנזכר בתנ \" ך ( וזה ענין יחידי שנזכר בתנ \" ך אודות יום\nכ \" ט שבט .)\nלא מצאנו לע \" ע לאיזה ענין היתה הכוונה ( בספר \" דבר יום ביומו \" לא\nהובא מתנ \" ך איזה ענין שקרה ביום זה הקשור עם אוה \" ע . וכן לא מצאנו\nבקורק ' ( ב \" עשתי עשר חודש \" וכיו \" ב .\"))\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תקו :)\"\nשכ \" ט שבט ][ לאחר חצות שמתחיל ר \" ח אדר\nיחזקאל לב\nסז\nבדר \" ח אדר ][\nמענה להרב דוד ראסקין על מכתבו – בהמשך לזה שבהתועדות ש \" פ\nמשפטים נתן לו כ \" ק אדמו \" ר שליט \" א קנקן משקה עבור ההכנות\nל \" מבצע פורים \" – בו כתב דו \" ח מהאסיפה ומהפעולות שהחלו לעשות\nבנידון ( תדפיס מספר \" ועבדי דוד \" – עניני חג הפורים – ע ' 31 :)\nהדו \" ח נת ' ות \" ח ות \" ח\nסח\nבדר \" ח אדר ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" המרכזית על מכתבם בקשר להצעה\nלמנות שליח קבוע לפעול מטעם צאגו \" ח באוניברסיטאות במנהטן\nובשכונות הסמוכות ( מהעתקת המזכיר . המענה מתפרסם בזה לראשונה\nבאדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)"],[9200220051,"51\nמענות קודש – ה ' תשמ \" ג\nזה מזמן – שהרר \" י שי ' קרינסקי עוסק בנוגע למנהאטאן .\nוישאלוהו הבטוח שאין כל סתירה כלל בזה .\nלהחזיר המצו \" ב\nסט\nלאחר ש \" פ תרומה , ו ' אדר ][\nמענה ל \" ועד הנחות בלה \" ק \" על שאלתם בהמדובר בהתועדות ש \" פ\nתרומה :\n\" בענין מ \" ש רש \" י ( כה , מ ) \" שנתקשה משה במעשה המנורה , עד שהראה\nלו הקב \" ה מנורה של אש \", אף שמפורש לעיל ( כה , ט ) שהקב \" ה הראה\nלמשה \" את תבנית כל כליו \" ( לא רק המנורה ) – נתבאר בשיחה , שהדיוק\nברש \" י הוא \" שנתקשה משה במעשה המנורה \", ועל זה לא הועיל מה\nשהראה לו תבנית ( כל כלי המשכן , כולל תבנית ) המנורה – כי עדיין\nהתקשה איך לעשותה מחתיכה אחת ע \" י הקשה בקורנס ( פרש \" י כה , לא )\nבתבנית כזה עם קנים גביעים כפתורים ופרחים וכו .'\nלכאורה : מכיון שמשה נתקשה במעשה המנורה – מה הועיל על זה\nשהראהו מנורה של אש ? ומכיון שבהתחלת הענין ( כה , לא ) פירש רש \" י\nשהמנורה נעשתה מאלי ' , \" לפי שהי ' משה מתקשה בה , אמר לו הקב \" ה\nהשלך את הככר לאור והיא נעשית מאלי '\", א \" כ , לאיזה צורך הראה לו\nמנורה של אש , וממ \" נ : בנוגע לתבנית המנורה – הרי הראה לו את תבנית\nכל כלי המשכן , ובנוגע לעשייתה – הרי כשהראה לו מנורה של אש לא\nהועיל הדבר לעשייתה , והוצרך שתהי ' \" נעשית מאלי ' .\"?\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה פלדמן כ \" ח אדר\nתשס \" ט :)\n[1 ] על מה שכתבו : \" לכאורה : מכיון שמשה נתקשה במעשה המנורה –\nמה הועיל על זה שהראהו מנורה של אש ?\", כתב :\nרש \" י כותב בפשטות שזה מועיל , והוא כותב בפשטות שזה אי אפשר\nשיועיל !? ( 1)\nלדוגמא : בן ה ' רואה באור ( אש ) הנר נהורא אוכמא , לבן וכו ' – באם ת \" ל\nדבהמנורה של אש הי ' הגביעים וכו ' כאו \" א בגוון משונה ה \" ז מקיל\nבהבנת עשייתה ( מעשה רב : בחוטי מכשיר הרדיא וכיו \" ב – כשצ \" ל\nחוטים רבים משנים צבעיהם )"],[9200220052,"52\nמענות קודש – ה ' תשמ \" ג\n[2 ] על מה שכתבו : \" ומכיון שבהתחלת הענין ( כה , לא ) פירש רש \" י\nשהמנורה נעשתה מאלי ' , \" לפי שהי ' משה מתקשה בה , אמר לו הקב \" ה\nהשלך את הככר לאור והיא נעשית מאלי '\", א \" כ , לאיזה צורך הראה לו\nמנורה של אש \", כתב :\nה \" ז בכל אופן קושיא בפ \" ע ואין לזה שייכות כלל להשיחה ( וכמש \" כ כל\nמפרשי רש \" י ) וכבר דובר בזה בהתועדות בשנים שעברו ( 2 )\n[3 ] על מה שכתבו : \" וממ \" נ : בנוגע לתבנית המנורה – הרי הראה לו את\nתבנית כל כלי המשכן , ובנוגע לעשייתה – הרי כשהראה לו מנורה של אש\nלא הועיל הדבר לעשייתה , והוצרך שתהי ' \" נעשית מאלי ' \"?\" – מחק את\nהתיבות \" לא הועיל הדבר \", וכתב :\nכשהראה לו מנורה של אש ][ הבין יותר אבל לא עד כ \" כ שיוכל לעשייתה ][\nבכל פרטי '\nישאלו בן ה ' ויודיעם אשר רבות פעמים המלמד מתרץ קושיא , ובפעם\nהא ' אינו תופס , ואז המלמד מוסיף ביאור ולפעמים זה מספיק .\nולפעמים גם ההוספה ועוד הוספה ועוד הוספה כו ' – אינו תופס ונשאר\nבקושיא\nלשיטתו – קלאץ קושיא הו \" ל להקשות : כיון שנעשית מאלי ' – הרי\nדוקא תבנית המנורה לא הו \" ל להראות כלל ומעיקרא מאי קא סבר !?\n[ חלק זה דהשיחה כפי שנערכה ע \" פ המענה – הוגה ע \" י כ \" ק אדמו \" ר\nשליט \" א ( צילום כתי \" ק – תשורה פלדמן שם ), ונדפס בהתועדויות תשמ \" ג\nח \" ב ע ' 1022 .]\nשבעים\n[ לאחר ש \" פ תצוה , י \" ג אדר ( 1 ])\nמענה ל \" ועד הנחות בלה \" ק \" על שאלתם בהמדובר בהתועדות ש \" פ\nתצוה :\n\" נתבאר בפרש \" י ד \" ה רמוני , שמלשון רש \" י \" כמין רמונים העשויים\nכביצת התרנגולת \" מוכח שישנם כמה סוגי רמונים , ועל זה מפרש רש \" י\nשרמונים אלו היו בסוג הרמונים העשויים כביצת תרנגולת ( מכיון שכך\nקיבל מרבו , ורבו מרבו וכו ', עד משה רבינו .)"],[9200220053,"53\nמענות קודש – ה ' תשמ \" ג\nאולי יש מקום לומר ( גם ) שהחילוק בין רימון לביצה ( מלבד החילוק\nשהרימון הוא עגול לגמרי , משא \" כ ביצה ) הוא – שרימון יש לו פה (\" כמין\nרמונים שלא פתחו פיהם \" – זבחים פח , ב . רמב \" ם פ \" ט מהל ' כלי המקדש\nה \" ד ), משא \" כ ביצה אין לה פה (\" ביצים . . אין להם פה \" – פרש \" י תולדות\nכה , ל ). וכפי שרואה הבן חמש למקרא חילוק זה .\nועפ \" ז אולי אפשר לומר שרש \" י מפרש שרמוני המעיל היו דומין לרמונים\nרק בפרט שהם עגולים , אבל לא הי ' להם פה – כביצת תרנגולת שאין לה\nפה . וזהו מ \" ש רש \" י \" עגולים . . היו \" – כרמונים , אבל לא בצורת רמון\nממש שיש לו פה , כי אם \" כמין רמונים העשויים כביצת תרנגולת \" שאין\nלה פה .\nועפ \" ז – אין צורך לומר שישנם כמה סוגי רמונים ( כמה סוגים בפרי\nהרמון ), כי אם שהקשוטים ( שנקראו רמונים ) שבמעיל היו כמו כמין )\"(\"\nרמונים ( שהם עגולים ), אבל לא ממש מכיון שרמונים אלו ( שבמעיל ),\nנעשו (\" העשויים )\" – בידי אדם – כביצת תרנגולת שאין לה פה .\n[ ואולי אפשר לומר שהכרחו של רש \" י ( מפשטות הכתובים , מלבד מה\nשקיבל מרבו כו ') לפרש כן הוא – כי בפסוק שלפנ \" ז נאמרו כמה פרטים\nאודות פיו של המעיל (\" והי ' פי ראשו בתוכו שפה יהי ' לפיו גו '\"), ומכיון\nשלא נאמר מאומה אודות פיהם של הרמונים , מוכח , שרמונים אלו לא\nהי ' להם פה .]\nהאם יש מקום לכל הנ \" ל .\"?\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תפה :)\"\nסימו קו תחת התיבות \" ביצה אין לה \" והתיבות \" הבן חמש למקרא\nחילוק זה \", וכתב :\nהראו חילוק זה ?! אכלתי רמון בר \" ה ( ובעבר ) ולא ראיתי כל פה כלל .\nכמדומני שגם פרש \" י שם לא ראו )("],[9200220054,"54\nמענות קודש – ה ' תשמ \" ג\nעא\n[ לאחר ש \" פ תצוה , י \" ג אדר ( 2 ])\nמענה ל \" ועד הנחות בלה \" ק \" על מכתבם – בהמשך להמענה שקיבלו על\nשאלתם בהמדובר בהתועדות ש \" פ תצוה :\n\" בהמשך למה ששאלנו בפרש \" י ד \" ה רמוני – הנה לכאורה הרי רואים\nשבראש הרמון יש כמין פרח ( כבציור המצורף ) [ שנקרא במשנה ( ערלה\nפ \" א מ \" ח ) בשם \" נץ \", וברע \" ב : פרח שעל גבי הפטמא ], משא \" כ בביצה .\n[ חשבנו שזה נקרא בשם \" פה \". וממענה כ \" ק אדמו \" ר שליט \" א נראה\nשאינו כן . אבל , לכאורה אין זה נוגע לעצם הענין , אם אפשר לפרש ברש \" י\nכדלקמן ]. ושאלתנו היא :\nאם אפשר לומר שכוונת רש \" י במ \" ש \" עגולים . . כמין רמונים העשויים\nכביצת תרנגולת \" היא – שהקשוטים שבמעיל נקראו בחומש בשם\nרמונים רק מפני שהיו \" עגולים \" כרמונים , אבל לא היו כרמונים ממש ,\nגם ביחס לפרח , כי בנוגע לפרט זה היו \" עשויים כביצת תרנגולת .\"\nדלכאורה , אם נפרש כן – יומתק : ( א ) שאין צריך לחדש שישנם כמה סוגי\nרמונים – מהם עגולים ממש , ומהם כביצת תרנגולת , ( ב ) להפירוש\nשבשיחה שישנם רמונים ( פרי ) שהם כביצת תרנגולת – לא מובן כל כך\nתיבת \" העשויים \" שבפרש \" י , דלכאורה הול \" ל \" כמין רמונים שהם כביצת\nתרנגולת \", משא \" כ ע \" פ הנ \" ל שברמונים ( פרי ) ישנו רק סוג א ' בלבד , מובן\nשפיר תיבת \" העשויים \", היינו , שהרמונים שבמעיל היו עשויים כביצת\nתרנגולת ( ולא כרמון ממש , עיגול עם פרח .\")\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תפה :)\"\n[1 ] על מה שכתבו : \" בהמשך למה ששאלנו בפרש \" י ד \" ה רמוני – הנה\nלכאורה הרי רואים שבראש הרמון יש כמין פרח . . משא \" כ בביצה ,\"\nכתב :\nציינתי לרש \" י בגמרא שמפרש שנפתח ואיך זה שייך לפרח\nבר ל ינר ג \" כ מקשר פרש \" י כאן – לפרש \" י בש \" ס !\n[2 ] על מה שכתבו : \" אם אפשר לומר שכוונת רש \" י במ \" ש \" עגולים . . כמין\nרמונים העשויים כביצת תרנגולת \" היא – שהקשוטים שבמעיל נקראו\nבחומש בשם רמונים רק מפני שהיו \" עגולים \" כרמונים , אבל לא היו\nכרמונים ממש , גם ביחס לפרח , כי בנוגע לפרט זה היו \" עשויים כביצת\nתרנגולת \"\", כתב :"],[9200220055,"55\nמענות קודש – ה ' תשמ \" ג\n– היפך דעגולים !\n[3 על מה שכתבו : \" משא \" כ ע \" פ הנ \" ל שברמונים ( פרי ) ישנו רק סוג א ']\nבלבד , מובן שפיר תיבת \" העשויים \", היינו , שהרמונים שבמעיל היו\nעשויים כביצת תרנגולת ( ולא כרמון ממש , עיגול עם פרח )\", כתב :\n[ היינו , שהרמונים שבמעיל ] הם היפך דעגולים\n[4 על כללות המכתב , כתב :]\nכדרכם – השמיטו ה קלאץ קשיא :\nכביצת – ה \" ה היפך דעגולים ( דזהו כל פירושו דרש \" י )!\n\" ומפרשים \" שרש \" י רק עוסק בפה , פרח ולמה לא ב זנב שבקצה השני\n[5 בשולי הגליון , כתב :]\nהעירוני ז \" ע – שנדבר עד \" ז תצוה תשל \" ה\nובהרשימה דברים תמוהים\n[6 ] על תצלום ציור של רימון שצירפו – סימן חץ לעבר הבליטה של\nהרימון , וכתב :\nזנב ?\nעב\nט \" ז אדר ][\nמענה להרב דוד ראסקין על דו \" ח מאסיפת הנהלת ישיבת תו \" ת\nהמרכזית בקשר לסיום ספר תורה הכללי החמישי שלהם , שהוחלט\nשיתקיים ביום כ \" ד סיון בבוסטון , וכתב : \" והננו שואלים אם ישנם\nהערות עכהנ \" ל וברכתו הק ' שתהי ' בהצלחה רבה וכו '\" ( תדפיס מספר\nועבדי דוד \"\" – ס \" ת הכלליים שע \" י תו \" ת המרכזית – ע ' 86 :)\nאזכיר עה \" צ שתהי ' בהצלחה רבה וכו ]'["],[9200220056,"56\nמענות קודש – ה ' תשמ \" ג\nעג\nאדר ][\nמענה לר ' פסח צבי לזרוב על מכתבו בנושא מסויים ( מהעתקת המזכיר .\nהמענה מתפרסם בזה לראשונה באדיבות הנמען שי ' וזכות הרבים תלוי '\nבו :)\nבכל זה כעצת ידידים מבינים\nאזכיר על הציון\nעד\nאדר ][\nמענה להרב זלמן שמעון דווארקין שכתב : \" אתמול בלילה קרא הרב ר '\nשמרי ' גורארי ' יחי ' לאיזה חברים מהח \" ק לאסיפה להתייעץ ע \" ד שינוי\nהמצב דהח \" ק אחר פטירת הרה \" ח רי \" ד אושפאל ע \" ה , כי מעולם הי '\nבהח \" ק ג ' גבאים . היינו הרש \" ג יחי ', הרב ש \" א קזרנובסקי ע \" ה , והרי \" ד\nאושפאל . ובועד המועצה הי ' הרא \" נ שקלאר יחי ', ר ' לוי \" צ שפירא , ור '\nשד \" ב ליפסקר יחי ', רואה חשבון הרש \" ז גו \" א יחי ', ובעת האחרון חתם\nהר \" י קרינסקי יחי ' הסערטיפיקטן עראי . מובן שעתה מוכרח לעשות\nאיזה שינויים בזה , ע \" כ טרם כל ולפני שנחליט איזה דבר , רצונינו לשמוע\nבזה חוות דעתו הקדושה בזה \" ( מהעתקת המזכיר . המענה מתפרסם בזה\nלראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\nשייך להנהלת הח \" ק , כפשוט .\nכמובן , לא לערב המזכ ', ולא חברי המזכ ' בתור פרטים\nעה\nועש \" ק תשא , י \" ט אדר ][\nמענה להרב זלמן שמעון דווארקין שכתב : \" ע \" פ מענה כ \" ק שליט \" א שכל\nהשינויים הצריכים להעשות בהח \" ק שייך להנהלת החברה , אנו מודיעים\nשהוחלט . . כל הנ \" ל הוא בתנאי אם כ \" ק שליט \" א מסכים על זה \"\n( מהעתקת המזכיר . המענה מתפרסם בזה לראשונה באדיבות א ' מאנ \" ש\nשי ' וזכות הרבים תלוי בו :)'"],[9200220057,"57\nמענות קודש – ה ' תשמ \" ג\nכ \" ק אדמו \" ר שליט \" א סימן בחץ ובעיגול את התיבות \" מסכים על זה ,\"\nוכתב :\nאזכיר עה \" צ\nושבקרוב ממש והקיצו ורננו גו '\nעו\nועש \" ק תשא , י \" ט אדר ][\nמענה לחתן שביקש ברכת כ \" ק אדמו \" ר שליט \" א לנסיעתו לאה \" ק\nלקראת חתונתו , וכן ביקש בקבוק משקה לחלק ביום החתונה ( תשורה\nרסקין אדר \" ח טבת תשנ \" ח :)\nמצו \" ב ( הוספה ) לצדקה באה \" ק . הרי מפורסם שלא נהוג לשלוח בקבוק\nמשקה בכדי לחלק ביום החתונה .\nעז\nכ \" א אדר ][\nמענה לר ' אהרן חיטריק בקשר לליקוט פירושים וכו ' לס ' התניא\nשבעריכתו ( תשורה גראס ט \" ז אלול תש \" ס , והעתקה :)\n(1 הלזה יקרא קצב ההוצאה ?)\n(2 ) עפמש \" כ בתניא – פשוט שההתעסקות בליקוט עצה למנוה \" נ וכו '\nעח\nכ \" ב אדר ][\nמענה להנהלת \" צבאות השם \" על חוברת י \" ב פסוקים ומאמרי חז \" ל\nבאנגלית שהכניסו (\" התקשרות \" גליון עב :)\nאזכיר עה \" צ להצלחה רבה כו .'"],[9200220058,"58\nמענות קודש – ה ' תשמ \" ג\nעט\nלאחר ש \" פ ויק \" פ , כ \" ז אדר ][\nמענה ל \" ועד הנחות בלה \" ק \" על שאלתם בהמדובר בהתועדות ש \" פ\nויק \" פ :\n\" נתבאר בהשיחה , שהטעם על מ \" ש \" אלה פקודי המשכן גו '\" לפני עשיית\nבגדי כהונה הוא – כי עשיית הבגדי כהונה היתה לאחרי מלאכת המשכן\n( פרש \" י תצוה כח , א ), ולכן , מיד לאחרי השלמת מלאכת המשכן וכליו\nשהיו עשויים מכסף ונחושת – נתן משה ( מיד ) חשבון על הכסף ונחושת\nבכדי להוציא עצמו מחשד כו '. ומכיון שנתן חשבון על הכסף ונחושת –\nהוצרך להזכיר גם על הזהב ( כי באם לא יזכיר מאומה על הזהב , בה\nבשעה שמדבר על הכסף ונחושת , הרי זה גופא יעורר חשד ). ומכיון שעדיין\nלא הי ' יכול לתת חשבון מכל הזהב , כי עדיין היו צריכים להשתמש בזהב\nעבור עשיית בגדי כהונה – לכן נאמר \" העשוי למלאכה בכל מלאכת\nהקודש \", מבלי להכנס לפרט פרטים בזה ( ועד \" ז הוא בכלי יקר ר \" פ\nפקודי .)\nלא תפסנו : למה לא נתן חשבון מהזהב לאחרי גמר עשיית בגדי כהונה\nכקושיית הכי \" ק שם ?)(\nהאם אפ \" ל ( ע \" פ דרך הפשט ) שאח \" כ נתן אמנם חשבון מפורט על הזהב ,\nולא הוצרך הכתוב להודיענו זאת , מכיון שזה מובן מעצמו , במכ \" ש מזה\nשנתן חשבון אפילו על הנחושת . האם נכון ?\nגם : הרי בנדבת המשכן היו הרבה דברים ( לבד מזהב וכסף ונחושת ,)\nומפורש בויקהל ( לה , כא ואילך ) שבנ \" י הביאו את כל הדברים . ולמה לא\nנתן משה חשבון על כל דברים אלו ? – בנוגע לאבני שהם ואבני מילואים\n– יש לומר בפשטות , שהי ' מספר מסויים ( י \" ב אבני מילואים , וב ' אבני\nשהם ), ובמילא ראו אותם על האפוד והחושן ( ולכן לא צריך לתת חשבון .)\nאבל מה עם שאר כל הדברים ? ואפילו אם נאמר ששאר הדברים אינם\nיקרים כל כך – הרי הענין דלהוציא את עצמו מהחשד שייך לכאורה גם\nעל דבר מועט .\nוהנה , מהמשך הכתוב \" ומן התכלת והארגמן ותולעת השני עשו בגדי שרד\nגו '\" משמע לכאורה שכוונת הכתוב היא ( לא לומר ממה היו עשויים בגדי\nשרד , כי אם ) לומר מה עשו עם התכלת והארגמן ותולעת השני ( שמהם\nנעשו \" בגדי השרד \" ו \" בגדי הקודש \"). אבל : ( א ) הרי ג ' דברים אלו היו\n( בכמות מרובה ) גם עבור היריעות , ( ב ) לפ \" ז יוקשה יותר , מה שג ' דברים\nאלו הוזכרו בכללות עכ \" פ , ואילו שאר הדברים לא הוזכרו כאן כלל ?"],[9200220059,"59\nמענות קודש – ה ' תשמ \" ג\nבהשיחה הקשה מדוע בחשבון דנחושת לא מוזכר הכיור וכנו . ולכאורה ,\nכבר פירש זאת רש \" י בס \" פ ויקהל ( לח , ח ). וכבר שאל זה הר \" י שיחי '\nוואלדמן .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תקי :)\"\n[1 ] על מה שכתבו : \" ולכן , מיד לאחרי השלמת מלאכת המשכן וכליו שהיו\nעשויים מכסף ונחושת \", כתב :\nשהיו עשויים מ ][ זהב כסף ונחושת ][\n[2 ] על מה שכתבו : \" לא תפסנו : למה לא נתן חשבון מהזהב לאחרי גמר\nעשיית בגדי כהונה \", כתב :\nוראה ראב \" ע ר \" פ פקודי\n[3 ] על מה שכתבו ( בנוגע לשאלה דלעיל 2 \" כקושיית הכי \" ק שם \", כתב :):\nקושיא שאינה שייכת כלל להמדובר בהתועדות\n[4 ] על מה שכתבו : \" בנוגע לאבני שהם ואבני מילואים – יש לומר\nבפשטות , שהי ' מספר מסויים ( י \" ב אבני מילואים , וב ' אבני שהם ,)\nובמילא ראו אותם על האפוד והחושן ( ולכן לא צריך לתת חשבון \") –\nסימן בעיגול תיבת \" ראו \", וכתב :\n?\nהרי עשיית האפוד והחושן ][ הי ' אחרי חשבון זה !!\n[5 ] על מה שכתבו : \" בהשיחה הקשה מדוע בחשבון דנחושת לא מוזכר\nהכיור וכנו . ולכאורה , כבר פירש זאת רש \" י בס \" פ ויקהל ( לח , ח )\", כתב :\nלא פירש ][ כ \" א הודיע זאת רש \" י בס \" פ ויקהל ( לח , ח ])[ המגדלת הקושיא\nלמה לא נכלל בנחושת התנופה בפרט לפרש \" י שם שהי ' חביב ביותר\nפ\nשלהי אדר ][\nמענה על פתק שכתב המזכיר ריל \" ג , בו כתב : \" עפ \" י הנדפס במפתח\nמאמרי כ \" ק אדמו \" ר מהוריי \" צ – זהו [ מאמר ד \" ה ראשית גויים עמלק\nתר \" פ ] מאמר הראשון של כ \" ק אדמו \" ר מהוריי \" צ , האם כדאי להדפיס\nהמאמר בקשר לב ' ניסן \" ( מצילום כתי \" ק – \" בית משיח \" גליון 31 :)"],[9200220060,"60\nמענות קודש – ה ' תשמ \" ג\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" האם \" וסימן בחץ ובעיגול את\nהתיבות \" כדאי כו '\", וכתב :\nכדאי להדפיס בקשר ][ וקודם לב ' ניסן ][\nבהוספת מ \" מ ( בצירוף הערותי שבסה \" מ תר \" ף )\nלציין למרז \" ל מה דסיים כו ' פתח כו '\nשהוא כנראה מאמר דסיים ראשית גוים כו '\nבאם כבר נדפס לציין שזוהי הוצאה כו '\nפא\nחורף ][\nמענה להרב מרדכי שמואל אשכנזי שהכניס את ספרו \" הלכות תלמוד\nתורה עם הערות וציונים \" פרק א ( מצילום כתי \" ק – ריש ס ' \" הלכות\nתלמוד תורה עם הערות וציונים \" ( הוצאת קה \" ת , תש \" ס ) כרך א . ס '\nהרב אשכנזי \" ע '\" 535 :)\nבסוף הספר ציין כ \" ק אדמו \" ר שליט \" א בכתי \" ק :\nנת '\nפב\nחורף ][\nמענה לא ' מאנ \" ש שרצה להדפיס את ס ' התניא בשינויים והוספות –\nתיקונים , מורה - שיעור וכו ' על הגליון ( לקו \" ש חל \" ו ע ' 222 :)\nוישנה ? כפשוט שאין לשנות מכמו שהדפיסו רבותינו משנת תר \" ס ."],[9200220061,"61\nמענות קודש – ה ' תשמ \" ג\nפג\nחורף ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א לר ' שלום דובער לוין –\nבצירוף למכתב שכתב הרב עזריאל הילדסהיימר , בקשר לאגרות שקיבל\nאביו הרב ד \" ר מאיר הילדסהיימר המופיעים באגרות - קודש אדמו \" ר\nמהריי \" ץ ח \" ב . במכתבו כתב איזה תיקונים וצירף את תצלום האגרות ,\nוביקש לקבל את הספר ( קובץ \" עבודת הקודש אצל הרבי \" ע ' מה :)\nלהררשד \" ב שי ' לוין\nלאשר וכו '. לשלוח .\nלהחזיר לי אח \" כ את המכ ' והמצו \" ב .\nהס ' לשלוח בפ \" ע כענין דדפוס באוירון .\nפשוט שצ \" ל נ . ב . שבאם אין אצלו ח \" א ישלחו לו .\nפד\nחורף ][\nמענה להשליח ר ' ארי ' ליב קפלן על מכתבו – בהמשך לספר שהו \" ל ( תחת\nשם בדוי ) בו מפריך את \" חידושי \" אישיות מסויימת . במכתבו כתב הצעה\nלהו \" ל ספר נוסף בענין אחר (\" כפר חב \" ד \" גליון 815 :)\nמי יודע ע \" ד מציאות הספר ? תגובות במשך כה \" ז כולו ?\nפה\nחורף ][\nמענה להשליח ר ' ארי ' ליב קפלן על ההודעה שהספר שערך אמור לצאת\nבאחד הימים (\" כפר חב \" ד \" גליון 815 :)\nנו ?!"],[9200220062,"62\nמענות קודש – ה ' תשמ \" ג\nפו\nחורף ][\nמענה לר ' ישראל לייבוב שהכניס את העתק מכתב הנהלת \" צעירי אגודת\nחב \" ד \" באה \" ק למחלקת המטבע ב \" בנק ישראל \" בקשר לרעיון הנפקת\nמטבע מיוחד בקשר עם חנוכה , אותו יחלקו לחיילי צה \" ל . במכתבם\nכתבו :\n\" להלן מספר הצעות : א . על המטבע אפשר להטביע את המנורה , כמו זו\nשהיתה בבית המקדש ( רצו \" ב צילום ). ב . לוחות הברית ( שהיו מרובעות\nכפי שמובא בספרים ). ג . אפשר לציין על המטבע \" דמי חנוכה \" או\nחנוכה .\"\"\nכדי שאנו נוכל להשתמש במטבע , ומפאת מגבלות תקציביות , אנו\nמבקשים להנפיק מטבע שערכו לא יהיה גבוה מדי . לכן אנו מציעים\nלהנפיק סידרה של מטבעות בערכים של שקל אחד , חמשה שקלים\nועשרה שקלים . על כל אחד מהמטבעות אפשר לעשות ציור אחר .\nאת השינויים שעל המטבע אפשר לעשות בצד שמופיע עליו הציור ובצד\nשכתוב הערך לא לשנות או להוסיף רק את המילה \" חנוכה \". זאת כדי\nלמנוע מהציבור בלבול מיותר .\"\nמענה כ \" ק אדמו \" ר שליט \" א (\" התקשרות \" גליון חי :)\n[1 ] סימן קו תחת התיבות \" דמי חנוכה \", \" סידרה של מטבעות \", \" אפשר\nלעשות ציור אחר \", \" את השינויים שעל המטבע אפשר לעשות בצד\nשמופיע עליו הציור ובצד שכתוב הערך \", וכתב :\nבנוגע להפרטים שאין שייכים לדין – למה להם להתערב ?! ( אמרו\nחנוכה \"\" – מציע ( גם ) \" דמי חנוכה \" באיזה צד הציור וכו ' וכו .)'\n[2 סימן את התיבות \" לוחות הברית \", וכתב :]\nהבטוח שיעשה מרובעות – באם לא בטוח לא לדבר ע \" ד ציור זה ( שלא\nלהכנס למחלוקת וכו ' שאין לוותר בזה , כיון שזה היפך הש \" ס .)\nבנוגע לציור המנורה לנסות שיהי ' כדרמב \" ם . אבל כיון שכמה מגדולי\nישראל ( עוד בימיו ) חלקו ע \" ז – לוותר בזה ."],[9200220063,"63\nמענות קודש – ה ' תשמ \" ג\nפז\nחורף ][\nמענה לר ' אהרן חיטריק שכתב :\n\" נגמר בדפוס מאמרים מכ \" ק אדה \" ז – שהתחלתם אינו על תנ \" ך או\nמאמרי רז \" ל , ברובם הם על ענינים – כמבואר בהמפתח – המצורף .\nשאלתי היא אם השם של הספר יהי ' \" מאמרי אדה \" ז – ענינים .\"\nכרך נוסף על מארז \" ל לפי סדר הש \" ס זהר ותפלה – מכינים לדפוס .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה גראס ט \" ז אלול\nתש \" ס :)\nמחק את התיבות \" שאלתי היא אם \" וסימן בחץ ובעיגול את התיבות\n\" השם של הספר יהי ' \" מאמרי אדה \" ז – ענינים .\"\"\nפח\nחורף ][\nמענה להשלוחה מרת חיענא זלצמן שכתבה שקיבלה רשיון נהיגה ושאלה\nהאם לנהוג ( תשורה יוזביץ כ \" ה מרחשון תשע \" ח :)\nכעצת רב דאנ \" ש , אעה \" צ .\nפט\nלפני חודש ניסן ][\nמענה למערכת עיתון \" משיח טיימס \" היו \" ל ע \" י \" צבאות השם \" שהכניסו\nאת שער העיתון דחודש ניסן בו בין השאר הופיעו ארבעת הקושיות ד \" מה\nנשתנה \" (\" התקשרות \" גליון עב :)\nסדר הקושיות צ \" ל כדעת אדה \" ז ."],[9200220064,"64\nמענות קודש – ה ' תשמ \" ג\nצ\nער \" ח ניסן ][\nמענה לר ' הלל דוד קרינסקי שכתב : \" הננו להודיע שהיום נגמור אי \" ה\nקנית הבית שלנו ב 585 מאנטגאמערי סט . בקראון הייטס , ומקוים\nלהעתיק לשם עוד לפני חג הפסח הבע \" ל . ומבקשים אנו ברכה בכל בגו \" ר \"\n( מצילום כתי \" ק – תשורה קרינסקי ט \" ו אלול תש \" ע :)\nויהא בשטומו \" צ בכל\nמצו \" ב להשקעה להצלחה מקרן כ \" ק מו \" ח אדמו \" ר נ ' דולר\nצא\nער \" ח ניסן ][\nמענה לא ' ששאל ע \" ד ההשתדלות ב \" מבצע תפלין \" כאשר יש בכמה\nמקומות ענינים שלא דקדושה כו ' ( ס ' \" היכל מנחם \" ח \" ב ע ' קפט :)\nהאומנם צ \" ל השאלה בהל ' תפלין שכותב לעבר לים ?\nוה \" ה מצאצאי אדה \" ז ובטח למד פ ' לב בתניא .\nצב\nר \" ח ניסן ][\nמענה לא ' המקורבים לא ' מבתי - חב \" ד על מכתבו בקשר לענין בריאותי\nמהעתקה . המענה מתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי '(\nוזכות הרבים תלוי ' בו :)\nכעצת רופא ידיד בעירו\nאזכיר עה \" צ"],[9200220065,"65\nמענות קודש – ה ' תשמ \" ג\nצג\nד ' ניסן ][\nמענה לא ' השלוחים שכתב שהמצב הכלכלי שלו אינו כשורה , והוא\nבחובות וכו ' ( תשורה שוחאט ד ' תמוז תשע \" ז :)\nידועה שיטתי מאז , שאינה עצה כלל – לברוח , כי אם במקומם דוקא\nלעשות התלוי בהם בדרך הטבע לפרנסה וכו .' ולהוסיף בצדקה ובתורה\nומצוות בכלל .\nאזכיר על הציון .\nצד\nתחלת ניסן ][\nמענה כללי - פרטי דימים אלו [ בין השאר – להרב דוד ראסקין על דו \" ח\nמאסיפה שנערכה – בהמשך לזה שבהתועדות ש \" פ ויק \" פ נתן לו כ \" ק\nאדמו \" ר שליט \" א קנקן משקה עבור ההכנות ל \" מבצע פ סח \" מהעתקה ,(\nבאדיבות מערכת הספר \" ועבדי דוד :])\"\nנת ' ות \" ח\nודבר בעתו –\nבחודש הגאולה בגו \" ר\nובסמיכות לימי חה \" פ זמן חרותנו\nאזכיר עה \" צ\nצה\nו ' ניסן ][\nמענה להסופר ר ' ישעי ' הכהן מטלין שכתב : \" נא לטרוח ולהשיב לי אם\nצריך לקרות בשבת הגדול פרשה צו בס \" ת של משיח \" ( מצילום כתי \" ק –\nתשורה נפרסטק ד ' אלול תשס \" ט :)\nכדאשתקד"],[9200220066,"66\nמענות קודש – ה ' תשמ \" ג\nצו\nיו \" ד ניסן ][\nמענה להת ' מנחם מענדל ראסקין – מתלמידים השלוחים לישיבה גדולה\nליובאוויטש קסבלנקה מרוקו – שהכניס דו \" ח מכמה ילדי \" צבאות\nהשם \" במרוקו שקיבלו על עצמם החלטות טובות בקשר עם יום הבהיר\nי \" א ניסן . במכתבו ציין אשר – שלא כשאר חברי הקבוצה , החוזרים\nלמרוקו אחר חג הפסח – הוא חוזר למרוקו לפני חג הפסח ( תשורה\nראסקין כ \" ט טבת תשנ \" ט . \" תחיינו \" גליון 7 ע ' 50 :)\nנת ' ות \" ח על הבשו \" ט כן יבש \" ט תכה \" י .\nלצדקה שם\nאזכיר עה \" צ\nכ \" ק אדמו \" ר שליט \" א צירף שני דולר .][\nצז\nלקראת יום הבהיר י \" א ניסן ][\nמענה למארגני שידור וידיאו חי מהתועדות כ \" ק אדמו \" ר שליט \" א אור\nליום הבהיר י \" א ניסן לאה \" ק – באולם \" בניני האומה \" בירושלים\nעיה \" ק , ובבית הכנסת \" בית מנחם \" והיכל ישיבת תו \" ת בכפר חב \" ד – על\nבקשת ברכה להצלחה (\" כפר חב \" ד \" גליון 93 :)\nלהצלחה רבה\nצח\nלאחר י \" ג ניסן ][\nמענה להשליח ר ' ברוך שלמה אליהו קונין על מכתבו – בהמשך להמדובר\nבהתועדות אור לי \" ג ניסן ( כנראה – בהתייחסות ברמז להנמען ) שגם\n\" לכתחילה אריבער \" צ \" ל באופן ד \" כלים דתיקון \" ( חלק מהמענה נדפס\nבס ' \" שליחות כהלכתה \" ע ' 407 , 427 . המענה בשלימותו מתפרסם בזה\nלראשונה באדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)"],[9200220067,"67\nמענות קודש – ה ' תשמ \" ג\n[1 ] במכתבו כתב ע \" ד דיונים רבים שערכו בקשר למצבם הכספי , במיוחד\nלאור שיחת כ \" ק אדמו \" ר שליט \" א , ואשר מוכנים להשתמש בכל אמצעי\nכ \" כלי \" שברכת כ \" ק אדמו \" ר שליט \" א תבוא לפועל .\nמענה כ \" ק אדמו \" ר שליט \" א :\nפשוט שמטרת שיחתי היתה להכניס תיקון בתהו – ובמילא שביעת רצון\nובמילא שמחה . וכ \" ז מלכתחילה אריבער – ולא עצב ר \" ל ונפילת רוח\nוכו .'\n[2 במכתבו כתב כמה הצעות שעלו בקשר לגיוס כספים באופן דחוף .]\nאחת ההצעות – להודיע להבעלי - בתים ע \" ד חומרת המצב .\nמענה כ \" ק אדמו \" ר שליט \" א :\nרק ליחידי סגולה\n[3] במכתבו כתב שבאמצעות הבעלי - בתים ( כנ \" ל 2 ) רוצים ליזום קמפיין\nהתרמה של מצב חירום . וציין שמחד גיסא המצב עוד לא נודע לציבור\nובמילא הפרסום עלול להרתיע בעלי - בתים , אך מאידך יש שנענים דוקא\nבמצבי חירום . כמו \" כ ציין שיש חשש שלאחר התרמה של מצב חירום\nתוגבל חופש הפעו לה .\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" Crises וכתב :\",\nאיך כותב קריזוז כשהנכסים שלהם שוויים יותר מהחובות ובהרבה !\n[4 ] במכתבו כתב שהצעה נוספת שעלתה הוא ללכת באופן ד \" לכתחילה\nאריבער \", וליזום קמפיין התרמה ( לא בהדגשה על מצב חירום , אלא )\nלציון מלאת ח \" י שנה בחג הפסח שנה זו לחב \" ד בקליפורניא , אשר\nהוכיחה את עצמה ביכולותי ', ועכשיו ניתנת ההזדמנות לגאול אותה\nמהחובות ולייצב את קיום המוסדות .\nמענה כ \" ק אדמו \" ר שליט \" א :\nזה ועוד סברות שכותבים בכולן בהתייעצות בידידים מבינים\n[5 ] במכתבו כתב הצעה שעלתה – לגייס כספים באמצעות משחקי\n\" בינגו \". וכתב שלא עשו זאת עד עתה , הגם שהדבר מקובל אצל שאר\nהחוגים האורטודוקסיים בעיר , וציין שדיבר על כך עם הרב זלמן שמעון\nדווארקין ואמר לו שע \" פ הלכה הדבר מותר ."],[9200220068,"68\nמענות קודש – ה ' תשמ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א :\nמופרך\nוראה ליקוט מענות קודש תשד \" מ מענה כ .][\n[6 ] במכתבו כתב הצעה שעלתה – למכור קרקעות הנמצאים בבעלות\nחב \" ד בקליפורניא , ביניהם שטח שערכו בין 2,050,000 ל - 2,250,000\nדולר .\nמענה כ \" ק אדמו \" ר שליט \" א :\nאפי ' בעולם התהו – תקציב כזה לישיבה כזו – תהו הוא אפי ' כשיהי '\nאצלם ממון מזומן רב מונח בבאנק .\nואם ייעצו להם למכור א ' מהנכסים הנ \" ל – הרי זה רק במחיר טוב עכ \" פ\nבמחיר ממוצע .\n[7 בסיום המכתב כתב כ \" ק אדמו \" ר שליט \" א :]\nבטח יערכו התוועדות בלאס אנדלעס באור ליום ו ' עש \" ק ( לאחרי ספירת\nהעומר של ) תפארת שבתפארת יום הולדת של המגלה ומפרסם של\nמלכתחילה אריבער .\nאזכיר עה \" צ ויבשר טוב\nצט\nלאחר אחרון של פסח ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א להמניחים בקשר\nלהמדובר בהתועדות אחש \" פ – (1 ) בביאור דברי הרמב \" ם \" וכן צוה משה\nרבינו מפי הגבורה לכוף את כל באי העולם לקבל עליהם מצות שנצטוו\nבני נח ;\" ( 2) מראי - מקומות למאמר ד \" ה כימי צאתך גו ' שנאמר\nבהתועדות ( מצילום כתי \" ק – תשורה טענענבוים י \" ג מרחשון תשע \" א :)\nמשמע בכ \" מ ( וגם בהל ' דעות להרמב \" ם ) דמצות הוכחה רק בחברו\nישראל ולא באו \" ה ובכ \" ז כופין\nועד \" ז בעיר שהשלימה ועבד כנעני וצ \" ע בגר תושב .\nלהמאמר – עיין מאמרי אחש \" פ תרפו תשח תשט"],[9200220069,"69\nמענות קודש – ה ' תשמ \" ג\nק\nכ \" ד ניסן ][\nמענה להשליח ר ' אברהם קארף על מכתבו בקשר לה \" קעמפ \" דמיאמי\nמהעתקה . המענה מתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי '(\nוזכות הרבים תלוי ' בו :)\nבהתייעצות בידידים מבינים אזכיר עה \" צ\nלהחזיר המצו \" ב\nקא\nאור לכ \" ה ניסן ][\nמענה לר ' ישראל צבי הלוי הבר המשמש כשו \" ב במדינת רומניא\nבשליחות כ \" ק אדמו \" ר שליט \" א (\" כפר חב \" ד \" גליון 94 . תשורה למברג\nכ \" ף אלול תשנ \" ט :)\n[1 ] על שאלתו – האם להיענות לבקשת הרב הראשי הרב דוד משה רוזן ,\nלנסוע לפולין לשבועיים לשחוט שם שחיטה כשרה עבור הבאים מכל\nהעולם לציון ארבעים שנה למרד גטו ווארשא , כתב :\nלא כדאי\n[2 ] על שאלתו – בקשר לבקשת הרב דוד משה רוזן להאריך את החוזה\nלתקופה נוספת – האם להסכים לכך , כתב :\nלהסכים\n[3 על בקשת רשות לנסוע לכ \" ק אדמו \" ר שליט \" א לכ \" ף מנ \" א , כתב :]\nהסכמה על זה , באם לא יפריע לעניניו ברומניא , אזכיר עה \" צ .\nקב\nשלהי ניסן ][\nמענה לר ' ישראל צבי הלוי הבר על ההודעה – בהמשך להמענה שקיבל –\nאשר עלולה להיות בעי ' כיון שאין שוחט אחר שישחוט (\" כפר חב \" ד \"\nגליון 94 תשורה למברג כ \" ף אלול תשנ \" ט :).\nא \" כ יעשה כל זה אבל לא ישתתף בהפגנות וכיו \" ב"],[9200220070,"70\nמענות קודש – ה ' תשמ \" ג\nקג\nלאחר כ \" ה ניסן ][\nמענה על פתק בשם קבוצת חתנים וכלות , בו כתבו : \" מצו \" ב לשון הברכה\nלקבוצת חתנים וכלות שיחיו שזכינו לקבל באור ליום ו ' ערש \" ק , כ \" ה\nניסן ה ' תשמ \" ג . ומתכוננים לחלק א \" ז בשעת החתונה \" ( מצילום כתי \" ק\n– תשורה קניבסקי ז ' תמוז תשס \" ח :)\nכמענתי מאז – ישנו נוסח עם ממ ומוגה\nוהוא שווה לכל נפש\nואותו לחלק א \" ז בשעת החתונה ][ כי אין הזמ \" ג להגה בכל פעם וכו )'(\nקד\nאביב ][\nמענה להאחים ר ' זלמן יהודה דייטש ור ' יוסף יצחק דייטש המתעסקים\nב \" כולל תפארת זקנים לוי יצחק \" שכתבו ע \" ד מינוי ר ' מנחם נחום\nגערליצקי לניהול הארגון , וכתבו ע \" ד תכניתם לייחד כמה חדרים בבית\nהכנסת ובית המדרש \" 770 \" שבהם ילמדו הזקנים מדי יום ביומו (\" א\nחסידישער דערהער \" מנ \" א תשע \" ח :)\nכפשוט שייך להגבאים שיחיו\nקה\nער \" ח אייר ][\nמענה לר ' לוי גאלדשטיין ( תשורה פרידמן ר \" ח סיון תשס \" ח . והעתקה ,\nבאדיבות הנמען שי :)'\n[1 במכתבו כתב :]\n\" ביום ל \" ג בעומר הבעל \" ט , תהי ' האפשערעניש של בנינו התאומים יחיאל\nאלטער יהושע ומנחם מענדל שיחיו , בעזה \" י ( יום הולדתם – ח \" י ניסן .)\nוהננו לשאול עצת כ \" ק אדמו \" ר שליט \" א בנוגע להכנסתם לחדר\n( אריינפירעניש ), דהנה , הרב רז \" ש שליט \" א דווארקין אמר לי שאין בזה\nדבר ברור , דבפולין היו עושים ההכנסה לחדר בהמשך להאפשערניש ,"],[9200220071,"71\nמענות קודש – ה ' תשמ \" ג\nמשא \" כ ברוסי ' היו מכניסים לחדר בגיל 5 ( או 4 ). בס ' השיחות קיץ\nה ' ש \" ת ע ' 67 מסופר אשר במחרת יו \" כ תקנ \" ג הכניסו את כ \" ק אדמו \" ר\nהצ \" צ נ \" ע לחדר . ( ואולי זוהי הוראה פרטית לבית רבי .)\nעוד , בכאן נהוג ( ברובם ככולם ) שמכניסים הילדים לגן ילדים וכיו \" ב בגיל\n3 בערך , ( בעיקר לשחק וכו .)'\nועפי \" ז הננו לבקש עצת כ \" ק אדמו \" ר שליט \" א בזה : א ) האם כדאי\nלהכניס התאומים שיחיו לגן ילדים כעת ; ב ) מתי לעשות חגיגת ההכנסה\nלחדר וכו .\"'\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" עוד \" \" לשחק וכו '\", וסימן בחץ\nובקו את התיבות \" בכאן כו '\", וכתב :\nבכאן נהוג ( ברובם ככולם ) שמכניסים הילדים לגן ילדים ][ היינו חדר )(\n[ וכיו \" ב בגיל 3 בערך , ( בעיקר ] לומר ברכות וכיו \" ב – וא \" כ מהי השאלה !?\n[2 במכתבו כתב :]\nבההתועדות דש \" פ שמיני ביאר כ \" ק אדמו \" ר שליט \" א ( בקשר להרש \" י )\"\nשמש \" כ בפ ' בראשית ( ג , א ) והנחש הי ' ערום מכל חית השדה גו ', ואינו\nכותב דגים ועופות , מפני שמובן מעצמו , מה דאך שהנחש הי ' ערום\nמבהמה וחי ' עאכו \" כ שהי ' ערום גם משאר כל הברואים . ולא הבנתי :\nמבואר במ \" א שדגים ועופות נעלים מבהמה וחי ', בלקו \" ש ח \" ד ע ' 1294\nבנוגע להכשרת בע \" ח לאכילה ע \" י שחיטה וכו ': בהמה נבראת מן העפר\nואינה יכולה להגבי ' א \" ע כלל מן הארץ . . ובעבודה : הגוף ונה \" ב ; עוף\nנברא מן הרקק – מים ועפר – ופורח באויר מזמל \" ז . . ובעבודה : נפש\nהשכלית . .; דגים נמצאים תמיד במקום חיותם . . ובעבודה : נפש\nהאלקית . . – ובדקות יותר י \" ל : עוף – נר \" נ פנימיים , דג – חי ' יחידה ,\nמקיפים . . עכלה \" ק .\nולהעיר מהדיעה בפרדר \" א פכ \" ג . . מדור כל בהמה וחי ' ביציע התחתון ,\nמדור לכל העופות ביציע השני ', מדור שקצים ורמשים ובני אדם ביציע\nהשלישית . . עכ \" ל .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nעל התיבות \" ביאר כ \" ק אדמו \" ר שליט \" א \", כתב :\nע \" פ מרז \" ל דשועל פקח שבחיות ( ברכות סא , ב ) ובקידושין ( פא א - ב )\nרשב \" א אומר כו ' חי ' ועוף כו ' ( ובברייתא ) ושועל חנוני"],[9200220072,"72\nמענות קודש – ה ' תשמ \" ג\nעל התיבות \" מבואר במ \" א שדגים ועופות נעלים כתב :\",\n( פחות גשמיים ) ומה זה שייך לערום\n[3 על כללות המכתב , כתב :]\nאזכיר עה \" צ\nק ו\nר \" ח אייר ][\nמענה לר ' יעקב יוסף ראסקין ( מצילום כתי \" ק – קונטרס ועד הנחות\nבלה \" ק ש \" פ נשא תשע \" ח :)\n[1] במכתבו כתב : \" תודה רבה עבור אגרת הק ו דש שהואיל כ \" ק לנחמנו\nבעת שנפרדה אשת נעוריי דרויזא בת גיטל ע \" ה .\"\nעל התיבות \" דרויזא בת \", כתב :\nשם האב\n[2 ] במכתבו כתב : \" הנה כבר עברו יותר מחדשיים , ועודני איני יכול\nלהתנחם מהאבדה הגדולה שנלקחה ממנו , שהיתה אשה צנועה בעלת\nמדות טובות , מזג טוב ועדינת רוח , ודורשת שלום לכאו \" א , ולא הרגישה\nבעצמה שום גדלות מזה . בכל בוקר כשאני קם משנתי , ורואה שאיננה\nבבית , איני יכול מל התאפק לבכות .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול תיבת \" לבכות \", וכתב :\n?! ה \" ז צער לנשמתה וכו ' וק \" ל ..\nויחליף זה באמירת ( בל \" נ ) מזמור תהלים ומשנה א ' – ומתוך שמחה\nדוקא וק \" ל ( 2)\n[3 ] במכתבו כתב : \" אנא כ \" ק לעורר נא רחמים רבים עלי , שהשי \" ת ברוב\nרחמיו יחזק נא את בריאותי לאריכות ימים ושנים , שלא יהי ' ח \" ו שום\nמניעות לתורה ולתפלה . ונזכה לראות בקרוב ממש בגילוי משיח צדקנו ,\nשנוכל לבשר בשורות טובות ישועות ונחמות .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nאזכיר עה \" צ לכהנ \" ל ויבש \" ט ( 3 )"],[9200220073,"73\nמענות קודש – ה ' תשמ \" ג\nק ז\nלאחר ד ' אייר ][\nמענה להמניחים על שאלתם בהמדובר בר \" ד ד ' אייר ביחידות הרב פנחס\nמנחם אלתר ( לימים האדמו \" ר דגור ) שהוגה ע \" י כ \" ק אדמו \" ר שליט \" א\n( מצילום כתי \" ק – נדפס לעיל . חלק מהמענה נדפס – \" בית משיח \" גליון\n79 ; \" יחי המלך \" גליון תשכז . המענה במלואו מתפרסם בזה לראשונה\nבאדיבות ר ' שלום יעקב שי ' חזן וזכות הרבים תלוי ' בו :)\n[1 במכתבם כתבו :]\n\" בהר \" ד דיום א ' להרפמ \" א שליט \" א נרשם , שלדעת הרמב \" ם שפסח שני\nהוא תשלומין לפסח ראשון מ \" מ פוסק המנ \" ח ( מצוה שפ , לדעת\nהרמב \" ם ) שאם יבנה הבית בין הפסחים – חייבים להקריב פסח שני ,\nאעפ \" י שלא היו מחוייבים ( בשנה זו ) בפסח ראשון .\nואולי הכוונה , עפ \" י המבואר בלקו \" ש חי \" ח ע ' 129 ואילך , שגם לדעת\nהרמב \" ם ( הל ' קר \" פ פ \" ה ה \" ב ) שפסח שני \" רגל בפני עצמו \" [ ולכן \" גר\nשנתגייר בין שני פסחים וכן קטן שהגדיל בין שני פסחים חייב לעשות\nפסח שני \" ( שם ה \" ז ) – הוא רק לדעת הרמב \" ם , משא \" כ להדיעות שפסח\nשני הוא תשלומין או תקנתא ( פסחים צג , א )], מ \" מ גם לדעת הרמב \" ם\nהוא תשלומין ( מלשון שלימות ), ולכן \" אם הזיד בראשון ה \" ז מקריב\nבשני \" ופטור מכרת ( שם ה \" ב ), האם נכון .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\nיעירו עד \" ז בקיצור בהערה\n[2 במכתבם כתבו :]\n\" אבל לכאורה שאלה זו , אם חייבים להקריב פסח שני באם יבנה הבית\nבין שני הפסחים , לכאורה אינו תלוי במחלוקת הגמרא הנ \" ל ( האם פסח\nשני הוא ( א ) רגל בפ \" ע ( ב ) תשלומין ( ג ) תקנתא ), אלא כמפורש במנ \" ח\n( שם ) \" ועיין בר \" מ ( שם ) פ \" ז ה \" ו דמשערינן בהנכנסין בעזרה אם הם רוב\nטהורים או טמאים , חזינן אם הם רוב טהורים נדחו המיעוט אף דיש\nרבים מישראל שהם טמאים וכן להיפך . . . הכלל עיקר ד \" ז דמיעוט ורוב\nגזה \" כ הוא רק בעומדים כאן ( בעזרה ) ויכולים לעשות הפסח , א \" כ נראה\nברור אם יבנה הבית ב \" ב בין ב ' הפסחים . . . אין חילוק בין רוב למיעוט ,\nא \" כ כל ישראל חייבין לעשות פסח שני \". ובלקו \" ש חי \" ב ע ' 218 ואילך\nמבואר , שגדר הענין שאין ציבור מקריבין פסח שני , אינו דין בההקרבה\nובפסח שני , אלא – דין בפסח ראשון ובדחי ', היינו שהתורה אינה דוחה"],[9200220074,"74\nמענות קודש – ה ' תשמ \" ג\nציבור מפסח ראשון לפסח שני , ועפ \" ז אם לא עשו פסח ראשון ( לא מחמת\nטומאה אלא ) מסיבה אחרת ( כגון מפני יד האומות ) חייבים הציבור\nבהקרבת פסח שני ( תוכן קצר מהמבואר שם .)\nועפ \" י הנ \" ל לכאורה אפילו לדעת האומרים שפסח שני הוא תשלומין ,\nבאם יבנה הבית בין שני הפסחים יהיו חייבים לעשות פסח שני ( לדעת\nר \" ח דפריש , דמקריבין קרבנות בזמה \" ז ), שהרי מה שלא הקריבו פסח\nראשון – הוא מסיבה שאינה תלוי ' בנו .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\nב ' ענינים שאינם תלוים זב \" ז בפסח ב ': אם הוא רק תשלומין , ואינו\nכשמעיקרא אין מה להשלים , אם אפשרי בצבור\nולחייב בנבנה ביהמ \" ק בין זמן דפ \" ר ופ \" ש – צ \" ל ב ' הנ \" ל בחיוב .\nקח\nלאחר ד ' אייר ][\nמענה להמניחים על שאלתם בהמדובר בר \" ד ד ' אייר ביחידות הרב פנחס\nמנחם אלתר ( לימים האדמו \" ר דגור ) שהוגה ע \" י כ \" ק אדמו \" ר שליט \" א :\n\" בהר \" ד דיום א ' להרפמ \" א שליט \" א נרשם , שהרפ \" מ שאל : כשיבוא ב \" ד\nויפסוק באופן אחר מהב \" ד שלפניו – אם הפסק שלהם חל רק מכאן\nולהבא [ כי בכל דור צריך לעשות כפסק \" השופט אשר יהי ' בימים ההם ,\"\nרמב \" ם הל ' ממרים רפ \" ב ], או שהפס \" ד של ב \" ד השני מברר שכן הי ' גם\nלמפרע . והרפ \" מ הוסיף בזה גמרא ( יומא פ , א ) \" האוכל חלב בזמן הזה\nצריך שיכתוב לו שיעור שמא יבוא ב \" ד אחר וירבה בשי עורין \", מוכח\nלכאורה שזה בירור גם על למפרע . דבאם נימא שהפס \" ד חל רק מכאן\nולהבא הרי גם כשיבוא ב \" ד ויפסקו שהשיעור הוא כזית קטן – למה\nיתחייב קרבן , מכיוון שהפס \" ד שלהם חל רק מכאן ולהבא , ועכשיו , בעת\nאכילתו , הי ' זה אליבא דאמת פחות מכזית . ומזה הביא ראי ' שהפס \" ד\nדב \" ד שלאח \" ז מברר גם על למפרע .\n[ והגם דמסקנת הגמרא שם שגם כשיבוא ב \" ד ויקטין השיעורים לא\nיצטרך להביא קרבן – הרי הטעם לזה הוא מפני ש \" האידנא לאו שב\nמידיעתו הוא , דאי נמי הוה ידע דחלב הוא הוה אכיל לי ', דהא השתא\nקים לן . . כזית בינוני \" ( רש \" י שם ), ומכיוון שהטעם על מה שיהי ' פטור\nלהביא קרבן הוא רק מפני שלא שב מידיעתו – מוכח מזה , שאז יתברר"],[9200220075,"75\nמענות קודש – ה ' תשמ \" ג\nשלמפרע הי ' איסור . כי באם זה יהי ' חידוש רק מכאן ולהבא – נמצא שלא\nעשה איסור כלל , ולא צריך להטעם ד \" לא שב מידיעתו .]\"\nוענה כ \" ק אדמו \" ר שליט \" א , שבכלל – הפס \" ד דב \" ד השני חל רק מכאן\nולהבא ( ובדוגמת פלוגתת ב \" ש וב \" ה , דטרם שנפסקה הלכה עשו ( באתרי '\nדב \" ש ) כב \" ש ולאחרי שנפסקה הלכה כב \" ה – נעשה אז הלכה כב \" ה . אבל\nאין זה בירור מלמפרע ). אלא שישנם ענינים שיבוא ב \" ד ויברר שכן הי '\nלמפרע ( ורק שמקודם לא ידעו מזה ). והגמרא ביומא שם \" שמא יבוא ב \" ד\nאחר וירבה בשיעורין \" איירי בכגון דא שהב \" ד יברר שכן הי ' גם מקודם .\nאם נרשם נכון . דלכאורה , המציאות היחידה שב \" ד יברר שכן הי ' גם\nמקודם – הוא רק שיאמרו שיש להם מסורה עד למשה מסיני [ כי באם\nהב \" ד יפסקו כן רק מצד הסברא או לימוד באחת מן המדות , לא יהי ' זה\nבירור על למפרע . דמכיוון ש \" אינו חייב ללכת אלא אחר ב \" ד שבדורו \"\nרמב \" ם שם )( – הרי בדור הקודם הי ' הדין אליבא דאמת כהפס \" ד דהב \" ד\nשל דור ההוא ]. ובאם שייך לומר שהכוונה בגמרא שם היא שיבוא ב \" ד\nויאמר שיש הלכה למשה מסיני ( שנשכחה במשך כל הדורות ) שהשיעור\nהוא בכזית קטן . דלכאורה , נוסף על מה שזה דוחק גדול , הנה לפ \" ז יהי '\nנמצא דמה שקיי \" ל ( עכשיו ) שהשיעור הוא בכזית בינוני אינו אמת ח \" ו !\nומכיוון שודאי הדבר , שמה דקיי \" ל עכשיו הוא אמת , והפירוש ב \" שמא\nיבוא ב \" ד כו '\" הוא שיפסקו כן ע \" פ לימוד באחת מן המדות ( כברמב \" ם\nשם ) – שבאופן זה , חל הפס \" ד שלהם רק מכאן ולהבא – מהו סברת\nהקס \" ד ( וגם לפי המסקנא , לולי טעם ד \" לא שב מידיעתו \") שיהי ' חייב\nבקרבן , והרי ( בעת אכילתו ) לא אכל כזית .\"?\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – נדפס לעיל . חלק מהמענה\nנדפס – \" בית משיח \" גליון 79 . המענה במלואו מתפרסם בזה לראשונה\nבאדיבות ר ' שלום יעקב שי ' חזן וזכות הרבים תלוי ' בו :)\n[1 ] על מה שכתבו : \" דלכאורה , המציאות היחידה שב \" ד יברר שכן הי ' גם\nמקודם \" – על תיבת \" היחידה כתב :\",\n!!??\n[2 ] על מה שכתבו : \" המציאות היחידה . . הוא רק שיאמרו שיש להם\nמסורה עד למשה מסיני \", כתב :\nמחלוקת היש מסורה ? במציאות !?\n[3 על מה שכתבו : \" דמכיוון ש \" אינו חייב ללכת אלא אחר ב \" ד שבדורו \"]\nרמב \" ם שם )( – הרי בדור הקודם הי ' הדין אליבא דאמת כהפס \" ד דהב \" ד\nשל דור ההוא \" – מחק מה שכתבו \" אליבא ד \", וכתב :"],[9200220076,"76\nמענות קודש – ה ' תשמ \" ג\nהרי בדור הקודם הי ' הדין ][ ( אף שאינו [ אמת ]) [ כהפס \" ד דהב \" ד של דור\nההוא ]\n[4 על מה שכתבו : \" דלכאורה , נוסף על מה שזה דוחק גדול \"] – סימן קו\nתחת התיבות \" זה דוחק גדול \", וכתב :\nויתרה מזה\n[5 וכתב :]\nהורו ב \" ד בטעות והלך אחריהם אינו מקריב קרבן\nקט\nה ' אייר ][\nמענה להרב שמחה עלבערג שהכניס מכתב שכתב א ' מקוראי ירחון\n\" הפרדס \" שבעריכתו , בו שאלות בקשר לשיחת כ \" ק אדמו \" ר שליט \" א\nשנדפסה שם ( חוברת אדר - ניסן תשמ \" ג ( שנה נז חוברת ו ) ע ' 9 ואילך .\nובלקו \" ש חכ \" א ע ' 156 ואילך ), בגדר גניזת הארון בבית המקדש ( מצילום\nכתי \" ק – תשורה קניבסקי ז ' תמוז תשס \" ח :)\n[1 ] במכתבו כתב : \" הנה עתה באתי מאה \" ק ומצאתי על שלחני הפרדס\nחוברת ו ', ובפתחי ראיתי והנה כ \" ק אדמו \" ר שליט \" א מליובאוויטש\nמחדש חידוש נפלא \" בענין מקום הארון בבית השני \" ברמב \" ם פ \" ד מהל '\nבהב \" ח הל ' א , שכוונתו שם שיש מלכתחילה ב ' מקומות לארון בביהמ \" ק ,\nהא ' מקום גלוי על האבן השתי ' בקה \" ק , והב ' מקום נסתר למטה\nמקוה \" ק במטמוניות עמוקות ועקלקלות , וגם מקום זה השני הוא חלק\nמבנין הבית , כי הארון הוא מה שעושה את ביהמ \" ק להיות בית להשם ,\nכלשון הרמב \" ם בריש הל ' ביהב \" ח וכמ \" ש ( תרומה כה , כב ) ונועדתי לך\nשם , וזהו דין בבנין הבית דכשם שמצד שלמו ת המקדש מוכרחים לבנות\nהמקום דקוה \" ק ששם נמצא הארון באופן גלוי , כך צריך ביהמ \" ק שיהי '\nבו בקוה \" ק מקום גניזה לארון , ועי \" ז נעשה קוה \" ק ענין נצחי , ע \" כ ת \" ד .\nומיישב בזה אריכת לשון הרמב \" ם וכמה תמיהות . ואם קבלה היא נקבל\nואם לדין קשה להבינו מכמה טעמים . .\".\nעל התיבות \" ואם קבלה היא נקבל \", כתב :\nפלא גדול – שהרי בפי ' אמרתי ( וכמדומה גם נעתק בהמ \" מ בפרדס –\nאינו עתה ת \" י – ) שזהו חידוש הרגצ ' ובי ( צפע \" נ עה \" ת ר \" פ תשא\nובהפטורת פקודי .)"],[9200220077,"77\nמענות קודש – ה ' תשמ \" ג\nלאחרונה נדפס צפע \" נ על ספר העבודה ושקו \" ט בזה ( הל ' בית הבחירה\nרפ \" ד .)\n[2 ] במכתבו כתב : \" א ) דעצם משמעות גניזה בש \" ס הוא כדי שלא\nלהשתמש בדבר כמו \" בקשו חכמים לגנוז ספר קהלת \" ( שבת ל :) ובמשנה\n\" אע \" פ שכתובים בכל לשון טעונים גניזה \" ( שם קטו .) בה גנזו בית\nחשמונאי אבני מזבח ( יומא טז .) אור שברא הקב \" ה ביום ראשון . . עמד\nוגנזו ( חגיגה יב .) ו בכ \" מ בש \" ס . א \" כ גם גניזת הארון משמע שלילת\nפעולתו עכשו בזמה \" ז , והי ' לו לומר נחבא הארון או נסתר הארון .\"\nסימן בעיגול את התיבות \" פעולתו עכשו בזמה \" ז \" וסימן שני קווים תחת\nתיבת \" פעולתו \", וכתב :\nהרי גם בארון לא נשתמשו מאז – בנוגע לפעולה – הזי ' על הכפורת ,)(\nאבל לא בנוגע לקדושת הארון ולהוספה עי \" ז בקדושת הבית בדרך\nממילא ( 2)\n[3 ] במכתבו כתב : \" ב ) הלא עיקר עשיית הארון מבואר בפ ' הוא כדי שיהיו\nהלוחות מונחים בו כמ \" ש ונתת אל הארון את העדות ( תרו ' כ \" ה ) אין\nבארון רק שני לוחות האבנים ( מלכים א ', ח ) וגם שברי לוחות היו מונחים\nשם ובס \" ת יש פלוגתא ( ב \" ב י \" ד .) ומכיון שנגנזו הלוחות ג \" כ שוב לא הי '\nצורך לארון ( עי ' מנ \" ח מ ' צה ) ואם משום השראת השכינה שעליו , כנראה\nמד ' כ \" ק שהביא את הפ ' \" ונועדתי לך שם \", א \" כ מה יועיל לזה\nהמטמוניות העמוקות והעקלקלות , וכי זה כבוד השכינה הלא \" מעולם\nלא ירדה שכינה למטה מעשרה \" והוא מאמר מוסכם לכ \" ע ( סוכה ה .\").\nסימן בעיגול את התיבות \" שנגנזו הלוחות ג \" כ שוב לא הי ' צורך לארון\nעי ' מנ \" ח מ ' צה )\", וכתב :(\nאינו מובן כלל הרי נגנזו בדרך ממילא ע \" י שנגנז הארון (3 )\nסימן בעיגול את התיבות \" וכי זה כבוד השכינה הלא \" מעולם לא ירדה\nשכינה למטה מעשרה \"\", וכתב :\nבצפע \" נ כי תשא וכו ' ציין לזבחים ( כד , א ) דדוד עד ארעאית תהומא\nקדיש ( 4 )\n[4 ] במכתבו כתב : \" ג ) וביותר תמוה להעמיס חידוש כזה בדברי הרמב \" ם\nז \" ל ביד החזקה שכל דבריו שם בנויים על אדני מקורות הש \" ס בבלי\nוירושלמי תוספ ' וכו ', ואם הרמב \" ם רוצה לחדש איזה דבר הוא אומר\nבלשון \" יראה לי \" כידוע , ומפרש דבריו באר היטב לא ברמזים בפרט\nבדבר שלא בארו חז ל אף ברמז .\"\""],[9200220078,"78\nמענות קודש – ה ' תשמ \" ג\nסימן בעיגול את התיבות \" אדני מקורות הש \" ס בבלי וירושלמי \", וכתב :\nראה בצפע \" נ שם שציין לבבלי וירושלמי . ובהפטורת פקודי שם –\nלהפסוק שבהפטורה (5 )\nואני כתבתי בחפזי ויש להאריך ( 6)\nק י\nי \" ב אייר ][\nמענה להמזכיר רחי \" ק שכתב : \" נתקבל היום המצו \" ב מהעו \" ד ע \" ד\nהעזבון של פראפ . [ שאול ] ליברמן ע \" ה . היום מתקיים הזכרה להשלשים\nשלו . פראפ . דימיטראפסקי ינאום בעיברית , ודוב שי ' זלוטניק ינאום\nבאנגלית \" ( מצילום כתי \" ק – תשורה ניו כ \" ה אד \" ש תשס \" ח :)\n[1 על כללות המכתב , כתב :]\nנת ' ות \" ח\n[2 סימן בעיגול תיבת \" המצו \" ב \", וכתב :]\nלהמל \" ח\nקיא\nי \" ד אייר , פסח שני ][\nמענה להשלוחה מרת חיענא זלצמן שכתבה שקיבלה הסכמת רב לנסיעה\nלאה \" ק לחתונת אחי ' שתתקיים בחודש תמוז , וביקשה הסכמת וברכת\nכ \" ק אדמו \" ר שליט \" א ( תשורה יוזביץ כ \" ה מרחשון תשע \" ח :)\nהסכמה וברכה . אעה \" צ ."],[9200220079,"79\nמענות קודש – ה ' תשמ \" ג\nקי ב\nאייר ][\nמענה לבני משפחת ר ' יחיאל מיכל רפפורט ע \" ה שהכניסו את נוסח\nהמצבה שלו ( מצילום כתי \" ק – ס ' \" מאוצר המלך \" ח \" ב ע ' 146 :)\n[1 על כללות הנוסח , ציין :]\nV\n[2 וכתב :]\nלאחרונה מזכירים במצבה גם שם האם וכיו \" ב להציג גם להם שם\nוק \" ל .\nבכל אופן צ \" ל בהסכמת הח \" ק דבית החיים שפ \" נ\n[3 ] על מה שכתב המזכיר ריב \" ק בצירוף להנוסח : \" נוסח המצבה שרוצים\nלהקים בהקדם \" – סימן שני קווים תחת תיבת \" בהקדם \", וכתב :\nונכון במאד\nומסיימים בטוב\nקי ג\nאייר ][\nמענה למרת דבורה בוטמאן על מכתבה בנושא מסויים ( ס ' \" ימי\nתמימים \" ח \" ח ע ' 182 :)\nכמובן שייך לבי \" ד רבני חב \" ד .\nקי ד\nאייר ][\nמענה לר ' אפרים וואלף על דו \" ח מאסיפת הנהלת ישיבת תו \" ת המרכזית\nבאה \" ק , בה עלתה הצעה לפתוח ישיבת תו \" ת בעיר בני ברק , ושאלו חוות\nדעת כ \" ק אדמו \" ר שליט \" א בזה ( ס ' \" ימי תמימים \" ח \" ח ע ' 182 :)\nהאמנם יש מי שאומר אשר בעיר בני ברק חסרים ישיבות ?"],[9200220080,"80\nמענות קודש – ה ' תשמ \" ג\nק טו\nאייר ][\nמענה לר ' יעקב יהודה העכט שכתב : \" הימים ממשמשים ובאים ובזמן\nקצר יהי ' ל \" ג בעומר , וצריכים לעשות ההכנות על התהלוכה , ושאלתי\nלכ \" ק אד \" ש מי יהי ' האחראי ? ז \" א בתהלוכה האחרונה הי ' ההפסד ממון\nלנו על ארבעים אלף דולר וכל אחד השמיט א \" ע מזה , ואפילו הצדיק\nהנדבן ר ' . . שהבטי ח ליתן שמונה אחוזים ( אם אני זוכר כראוי ) גם לא\nנתן אף פרוטה בתירוצים שונים . ולכן אפשר שבפעם זו ניתן הכבוד\nלצא \" ח או לצבאות ה ' או מי שהוא אחר ואנחנו נעבוד כמו ע \" ע , אבל\nבעניני ממונות יהי ' הם האחראים ועי \" ז לא יהי ' ח \" ו לנו הפסדות , ובטוח\nאני שמוסד שני לא יפסיד מפ ני שעלי אין רחמנות , אבל על אחרים ( יהי '\nמי שיהי ') רחמנות , ואל תגזל דל כי דל הוא ויהי ' מי שירחם עליהם . ואנא\nלייעצני כ \" ק אד \" ש בעצתו הק '\" ( תשורה נאגל ט \" ז אייר תשנ \" ז :)\nא \" כ לא יעשה זה השנה .\nשייך לעסקני אנ \" ש שיחי ' כבכל שאלה , ישאל רב מורה הוראה מי הם .\nקטז\nאייר ][\nמענה לר ' יעקב יהודה העכט שכתב : \" אנא לעורר רחמים רבים ממקור\nהרחמים והחסדים האמתיים שהתהלוכה ביום הגדול והקדוש – יום\nהשמחה – ל \" ג בעומר , הילולא דהתנא הק ' הרשב \" י , יהי ' בהצלחה גדולה\nומופלגה בכלל ובפרט , ושהכל ילך כשורה , ושיהי ' ברוב פאר והדר ,\nוקידוש שם שמים ברבים , ושמזג האויר יהי ' טוב ויפה , ויהי ' המון רב ,\nאנשים , ונשים , וטף , ברוב עם הדרת מלך , ולכתחילה אריבער באופן\nנפלא , ושיביא פעולות טובות ופירות טובות בגו \" ר \" ( תשורה נאגל ט \" ז\nאייר תשנ \" ז :)\nאעה \" צ להנ \" ל – ועוד יותר ולכתחילה אריבער ."],[9200220081,"81\nמענות קודש – ה ' תשמ \" ג\nק יז\nאייר ][\nמענה לר ' יעקב יהודה העכט על מכתבו בקשר לסדרי ה \" פאראד \" דל \" ג\nבעומר ( תשורה נאגל ט \" ז אייר תשנ \" ז :)\n[1 בקשר להגרלה שתיערך בעת הפאראד , כתב :]\nהגרלה עבור ספר וגם עבור [ Bicycle ]\n[2 בקשר לזמר שהוזמן לשיר בפאראד , כתב :]\nמרדכי בן דוד ][ , לאחר – רבי ][ .\nמכמה טעמים ומהם שבנתיים יתוספו עוד ילדים .\n[3 בקשר למימון הפאראד , כתב :]\nמצורף בזה אצל הרב חודקוב – לתוס ' .[ ]. טשעק ע \" ס $3000 .\nקיח\nאייר ][\nמענה לר ' יעקב יהודה העכט על מכתבו בו ביקש מחילה על מאורע\nמסויים שאירע בעת ה \" פאראד \" דל \" ג בעומר ( מהעתקה :)\nהכל מחול לך – הכל כו ' ( ג ' פעמים וכו ') ובפרט לאחר שראיתי בעיני\nההצלחה גם בעמפייר בולברד וכו '\nקי ט\nאייר ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) לכמה מתלמידי ישיבת\nתו \" ת המרכזית על דוחו \" ת פרטיים בקשר ל \" פאראד \" ( תשורה גינזבורג\nט \" ז מרחשון תשע \" ו ;) ( 2 ) לר ' לוי גאלדשטיין על מכתבו ( מהעתקת\nהמזכיר , באדיבות הנמען שי ;)' ( 3 ) להנהלת \" צבאות השם \" על מכתבם\n( מהעתקת המזכיר , באד יבות א ' מאנ \" ש שי :])'"],[9200220082,"82\nמענות קודש – ה ' תשמ \" ג\nנת ' ות \" ח\nודבר בעתו –\nבסמיכות לל \" ג בעומר –\nיום שמחתו גדולה דהרשב \" י ,\nוכדאי ר \" ש לסמוך עליו כו .'\nאזכיר עה \" צ .\nקכ\nי \" ט אייר ][\nממענה לר ' אפרים וואלף שכתב : \" קבלנו ידיעות שבירושלים הודפס ע \" י\nה ' . . שו \" ע אדמוה \" ז . באה \" ק לא ניתן להשיג ולקנות השו \" ע מהוצאה זו ,\nוכנראה שהוא שולח הספרים רק לחו \" ל . שלחנו אליו אנשים , אבל לא\nיכולנו לברר משהו ברור , וזה למעשה רק שמועות \" ( מצילום כתי \" ק –\nנדפס לעיל . המענה מתפרסם בזה לראשונה באדיבות מערכת הספר\nשליחות כהלכתה \" וזכות הרבים תלוי ' בהם :)\"\nבאם חב \" ד הי ' עוסקת בהפצת ספרי חב \" ד לא הייתה השגחה העליונה\nעושה זאת ע \" י אחרים .\nהרי ע \" ז .[ ].\nקכא\nי \" ט אייר ][\nמענה להרב אשר ציילינגאלד שכתב ע \" ד א ' ממקורביו , מנהל אזורי של\nרשת חנויות כל - בו , שהחל לאחרונה לגדל את זקנו , אלא שהעומד על גביו\nאמר לו שעליו יהי ' לגלח את זקנו , כיון שאין זה מתאים עם ה \" Code \"\nכללי הלבוש ) של הרשת . למכתבו צירף עניני דפוס הקשורים לפעילותו ,(\nביניהם כתבה ותמונות שהופיעו באחד העיתונים ממסיבה שנערכה בבית\nהכנסת שלו , בה השתתף ראש - העיר \"( Story My Here’s \" ש \" פ חיי שרה\nתשע \" ו :)"],[9200220083,"83\nמענות קודש – ה ' תשמ \" ג\nבודאי המטרה של ה Code היא בשביל טובת העסק , וכשנשתנה המצב\nבמדינה ( בארצה \" ב ) – משתנה גם ה - Code ( להקיל באיזה ענינים או\nגם לשנותם ) רואים בפועל שכו \" כ מגדלים זקן ( אפילו לא דתיים – ראה\nבתמונה שבמכ \" ע שהמעיאר בזקן ) ועד \" ז בכיסוי הראש ( ויכול להחליף\nהכיפה – בכובע רגיל , לבוש מיל י אָני אנשים בארצה \" ב ) הבירור הפשוט\nמהי טובת העסק – שיבחנו הצלחתו בהעסק ויראו שלא נתמעטה\nואדרבה – באם כהנ \" ל לא יצליח ויתעקשו כן – ישאל רב מורה הוראה\nמה עליו לעשות , מה לאמר לילדיו שי ' וכו '\nקכ ב\nועש \" ק בהו \" ב , כ \" ג אייר ][\nמענה לר ' מנחם מאיר הכהן בלוי על מכתבו בקשר לספר \" תורה\nגעדאנקען \" שמו \" ל – עיבוד משיחות כ \" ק אדמו \" ר שליט \" א על חמשה\nחומשי תורה – בו כתב :\n\" מצו \" ב העתק משיחה הראשונה של הספר החדש . והנני שואל אם כ \" ק\nאדמו \" ר שליט \" א מסכים לזה ? והנני מבקש ברכת כ \" ק אדמו \" ר להצלחה\nבזה . . עפ \" י הוראת כ \" ק אדמו \" ר בתחלת שבוע זה , יוכנס להספר רק\nענינים השוים לכל נפש ( לענ \" ד ). ויסודרו לפי סדר הפרשיות , ולאח \" ז ( לפי\nהזמן והמקום שישאר ) עניני מבצעים וכו .\"'\nכותרת השיחה שהכניס הייתה : \" א ביאור אויף א פתגם והוראה פון\nרבותינו נשיאנו בקשר מיט שבת בראשית / פארוואס איז דוקא שבת\nבראשית נוגע צום גאנצען יאר .\"?\nמענה כ \" ק אדמו \" ר שליט \" א ( קובץ \" זכרון מנחם מאיר \" ח \" א ע ' 18 :)\nסימן בעיגול את התיבות \" מסכים לזה \", וכתב :\nעיקר מטרת הס ' – אריינציען מבחוץ פנימה\nטבע בנ \" א ( ובפרט בנוגע לענין חדש אצלם ) לדון ספר ע \" פ התחלתו\nוסופו )(\nוע \" פ הנ \" ל תהי ' התחלתו : כיון שישנו פתגם תמוה של נשיאי חב \" ד\nרק בעיני חסיד – חב \" ד ( כי סתם בנ \" י אצלם פשוט שבראשית היא\nראשית התומ \" צ כולן ולכן כו '\nובמילא מובן שתוכן הס ' לתרץ תמיהות תמוהות של חב \" ד"],[9200220084,"84\nמענות קודש – ה ' תשמ \" ג\nוכ \" ז בעת שינוי תיבות ספורות – מהפך הרושם ועושה הנ \" ל מעניין\nבחוץ וכו '\nקכ ג\nועש \" ק בהו \" ב , כ \" ג אייר ][\nמענה להנהלת \" נשי ובנות חב \" ד \" על מכתבן בקשר לכינוס השנתי שלהן\nתשורה וויינפעלד כ \" ח סיון תשע \" ח , והעתקת המזכיר :)(\n[1 במכתבן כתבו שרוצים להקדיש את הכנס לנושא ה \" פעטישענס \"]\nעצומות )( – בהמשך להוראת כ \" ק אדמו \" ר שליט \" א אשר ילדי ישראל\nישלחו \" פעטישענס \" לנשיא ארצה \" ב בקשר לייסוד \" רגע של שתיקה \"\nבבתי הספר הממשלתיים .\nמענה כ \" ק אדמו \" ר שליט \" א :\nבצער , אבל אין לי ברירה , ומוכרחני לכתוב הנ \" ל , ואתן הסליחה :\nמובן ופשוט – שלמרות חשיבות ענין הפעטישענס וגודלו – אין לצמצם\nהכנס ( השקו \" ט שבו , ועאכו \" כ – ההחלטות ) אך לנדו \" ז\nואפילו – לא לעשותו העיקר ,\nכי מובן שעיקר ענין ומטרת הכנס ה \" ה – ביסוס והפצת היהדות בפועל\nודתומ \" י ; ( ובפרט – השייכים לנשים במיוחד : כשרות , טהרת\nהמשפחה , חינוך יו \" ח שי ' ( צניעות ) והשתדלות אמתית להחדיר זה בכל\nחוגי בנ \" י ( שכנראה – במשך כל השנים – הפעולה בזה חלושה ביותר ,\nואולי עוד פחות מזה – לבד מבצע נש \" ק .)\nוהמעט שנעשה – ברובו ה \" ז ביזמת נשים בודדות מצ \" ע , ולא כתוצאה\nמהכינוסים , או מועד שהי ' צ \" ל נבחר למטרה זו ( ובמשך 27 שנה –\nכנראה שעדיין לא נבחר ,)\nועד ש ( כנראה ) אין מנצלות כלל – שעת הכושר לכ \" ז כשבאים לכאן\nאורחים - ות מכמה וכמה מדינות להיו \" ט וכו .)'(\nוע \" ד הצחות – בין כנס לכנס הנהלת הכנס והנהלת נשי ובנות חב \" ד\nבכלל נמצאות בוואקיישאן מלא ( לבד כשעושים טומעל גדול ע \" ד מבצע\nחדש .)"],[9200220085,"85\nמענות קודש – ה ' תשמ \" ג\n[2 בקשר לאלבום שצירפו , כתב :]\nעושה רושם יפה וגם חזק וכו ' –\nויה \" ר שתצליחנה בכל עניני הכנס\nובאופן דלכתחילה אריבער .\nאזכיר על הציון\nקכ ד\nשלהי אייר ][\nמענה להנהלת \" נשי ובנות חב \" ד \" על מכתבן בקשר לה \" פעטישענס \"\n( עצומות ) שהורה כ \" ק אדמו \" ר שליט \" א שישלחו ילדי ישראל לנשיא\nארצה \" ב בקשר לייסוד \" רגע של שתיקה \" בבתי הספר הממשלתיים\nתשורה וויינפעלד כ \" ח סיון תשע \" ח , והעתקת המזכיר :)(\nבנוגע לפעטישענס – מוכרח : שתהי ' התאמה דכל ארגוני חב \" ד\nהמתעסקים בזה , שאילת דעת מומחים בנוסח שלהן , אופן שילוחן וכו ,'\nועוד ועיקר שאילת דעת רב ( נים ) בנוגע להנוסח , לההשתדלות וכו ' –\nשיתאימו להאזהרה ושם אלקים אחרים לא ישמע על פיך , ושבאופן\nהמותר – ינצלו כל האפשריות .\nאזכיר עה \" צ .\nקכ ה\nלאחר ש \" פ בהו \" ב , כ \" ד אייר ][\nמענה ל \" ועד הנחות בלה \" ק \" על שאלתם בהמדובר בהתועדות ש \" פ\nבהו \" ב :\n\" בהשיחה נאמר , שהגם שהיתה ההתגלות דפנימיות התורה ע \" י\nהבעש \" ט , ולאח \" ז ביותר ע \" י אדה \" ז , מ \" מ , הענין ד \" יפוצו מעינותיך\nחוצה \" התחיל רק לאחרי פט \" ב ( כשיחה הידועה בתו \" ש ). והגם שאז –\nי \" ט כסלו תקנ \" ט – הי ' כבר כו \" כ שנים לאחרי \" בשנת שש מאות שנה\nגו '\", מ \" מ , גם אז הי ' רק ההתחלה דיפוצו מעינותיך חוצה ."],[9200220086,"86\nמענות קודש – ה ' תשמ \" ג\nלכאורה , \" בשנת שש מאות שנה \" קאי על שנת ת \" ר , וכן הוא בלקו \" ש\nחט \" ו ע ' 42 אולי יש בזה עוד פירוש ( ובשיחה דשבת נאמר כפירוש זה ). –\nש \" בשנת שש מאות שנה \" קאי על התחלת מאה הששי , היינו , מיד לאחר\nשנת ת \" ק . דמכיון שבזהר הובאה הדוגמא \" כבר נש דמתקן ביומא\nשתיתאה מבי ערב שמשא \", משמע , שהכוונה מיד לאחרי חצות . האם\nנכון .\"?\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תצו :)\"\n[1 ] על מה שכתבו : \" והגם שאז – י \" ט כסלו תקנ \" ט – הי ' כבר כו \" כ שנים\nלאחרי \" בשנת שש מאות שנה גו '\", מ \" מ , גם אז הי ' רק ההתחלה דיפוצו\nמעינותיך חוצה \" – מחק את התיבות \" בשנת שש מאות שנה גו '\", וכתב :\n[ והגם שאז – י \" ט כסלו תקנ \" ט – הי ' כבר כו \" כ שנים לאחרי ] התחלת\n)**\nאלף הששי ו לאחרי ][ אתא בוקר שבו [ מ \" מ , גם אז הי ' רק ההתחלה\nדיפוצו מעינותיך חוצה ]\n___\nעיין זח \" א קיז , א , קיט , א ובאוהח שם . אוה \" ח צו ו , ב .*)\n[2 מחק את כל הקטע \" לכאורה . . האם נכון ?\", וכתב :]\nוהנה התגלות הבעש \" ט – בשנת תצ \" ד גם אדה \" ז בשנת תק \" מ ולפנ \" ז\nהאריז \" ל ( דמאז מצוה זאת החכמה ) שנות שלא - ג ,\nובאוה \" ח ( צו ו , ב ) – שנת ת \" ק שכ \" ז לפני שנת ת \" ר , ואף שיש לחלק בין\nיפוצו וכו ' – כדמוכח בשיחת אדנ \" ע\nבאוה \" ח מוכח דשנת ת \" ק ה \" ז אתא בוקר וכו ,' עיי \" ש\nלכן י \" ל דלאחר ת \" ק – התחלת מאה הששית דאלף הששי הייתה עת\nרצון לאתא בוקר ( אור – לא רק עלות השחר ), אלא שמפני סיבות . .\nחלק בפנים המ \" מ בהערות\n[ חלק זה דהשיחה כפי שנערכה ע \" פ המענה – הוגה ע \" י כ \" ק אדמו \" ר\nשליט \" א ( צילום כתי \" ק – \" יחי המלך \" שם ), ונדפס בהתועדויות תשמ \" ג\nח \" ג ע ' 1452 .]"],[9200220087,"87\nמענות קודש – ה ' תשמ \" ג\nקכ ו\nלאחר ש \" פ בהו \" ב , כ \" ד אייר ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בהמדובר בהתועדות ש \" פ\nבהו \" ב :\n\" נתבאר שה \" חידוש \" שנתגלה לאחרונה בחכמת המדע שהרים נעשים\nע \" י רוחות ואידים שבתוך הארץ – כתוב מאז בתורה , בהענין שהר הוא\nבחי ' צומח שבדומם , ומבואר בע \" ח בסופו שצומח יש בו נפש הדוממת\nונוסף לזה יש בו רוח נוספת , נפש הצומחת , ומזה מובן גם בנוגע להר –\nצומח שבדומם – שיש בו רוח נוספת וזה פעל גידול ההר ( ואינו מקום\nמישור .)\nענין זה שהתהוות ההר נעשה ע \" י רוח שבדומם הארץ – מבואר בפירוש\nובארוכה בדרוש ברכת חתנים ( לאדהאמ \" צ ) פ \" י בפירוש הכתוב יוצר\nהרים ובורא רוח ( מצו \" ב צילום מזה ), ושם שהר הוא בחי ' צומח\nשבדומם , וגידול ההרים הוא ע \" י יסוד הרוח ( שיש בו מחלק האש יותר )\nשבדומם הארץ כו '. [ הענין שהר הוא בחי ' צומח שבדומם – כ ' גם בתו \" ח\nפ ' בראשית ( שנזכר בהשיחה ) כ , א .\"]\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תקיח :)\"\nכמדומה ( קרוב לודאי ) שישנו בדרושי אדה \" ז\nויציינו כל מה שימצאו בהמ \" מ\nקכ ז\nלאחר ש \" פ בהו \" ב , כ \" ד אייר ][\nמענה ל \" ועד הנחות בלה \" ק \" על שאלתם בהמדובר בהתועדות ש \" פ\nבהו \" ב :\n\" א . בנוגע לר ' יהודה – הוזכר בהתוועדות ( כפי שזכרו ב \" חזרה \"), שנקרא\nקדוש ע \" ש שלא הסתכל בצורת מטבע .\nלכאורה : ענין זה מצינו בנוגע לר ' פנחס בר ' סימאי , שנקרא בנן של\nקדושים משום שלא הסתכל בצורת מטבע – פסחים קד , א ( ובתוס ' שם :\nתולה קדושתו באביו שגם אביו הי ' קדוש ), ע \" ז נ , א ."],[9200220088,"88\nמענות קודש – ה ' תשמ \" ג\nאולי אפ \" ל , דמכיון שר ' יהודה נקרא חסיד [\" כל היכא דאמרינן מעשה\nבחסיד אחד או רבי יהודה בן בבא או רבי יהודה ברבי אילעי \" ( ב \" ק קג ,\nב )], וחסידות גדולה מקדושה [ כמובן מסוף סוטה : \" קדושה מביאה לידי\nענוה . . יראת חטא . . חסידות \"], יש לומר , שגם אצל ר ' יהודה היתה\nמעלה זו , במכ \" ש מר ' פנחס בר ' סימאי שמצד מעלה זו נקרא בנן של\nקדושים .\nב . בנוגע להדגשת ענין הדירה ע \" י ר ' יהודה – \" פחות ממיכלך וממשתיך\nותוסיף על דירתך \" דוקא ( פסחים קיד , א ), אולי יש מקום להעיר גם\nמויק \" ר רפכ \" ב , קה \" ר פ \" ה , ח , ועוד ( עה \" פ יתרון ארץ בכל היא ): ר '\nיהודה אומר . . כל מי שהוא הומה ומהמה אחר הממון וקרקע אין לו מה\nהנאה יש לו \", והרי קרקע ודירה ענינים אחד הוא .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – \" יחי המלך \" גליון\nתקעא :)\n[1 על מה שכתבו : \" בנוגע לר ' יהודה \", כתב :]\nשנקרא חסיד\n[2 ] על מה שכתבו : \" הוזכר בהתוועדות ( כפי שזכרו ב \" חזרה \"), שנקרא\nקדוש ע \" ש שלא הסתכל בצורת מטבע \", כתב :\nלא [ שנקרא ]\nלא הוא הדגשתי שמצינו בחז \" ל עד \" ז\n[3 ] על מה שכתבו : \" אולי אפ \" ל , דמכיון שר ' יהודה נקרא חסיד . .\nוחסידות גדולה מקדושה . . יש לומר , שגם אצל ר ' יהודה היתה מעלה זו ,\nבמכ \" ש מר ' פנחס בר ' סימאי שמצד מעלה זו נקרא בנן של קדושים ,\"\nכתב :\nצע \" ג אם שייך בכגון זה ק \" ו\n[4 ] על מה שכתבו : \" בנוגע להדגשת ענין הדירה ע \" י ר ' יהודה . . אולי יש\nמקום להעיר גם מויק \" ר רפכ \" ב , קה \" ר פ \" ה , ח , ועוד ( עה \" פ יתרון ארץ\nבכל היא ): ר ' יהודה אומר . . כל מי שהוא הומה ומהמה אחר הממון\nוקרקע אין לו מה הנאה יש לו \"\" – סימן בעיגול תיבת \" הנאה \", וכתב :\nגם עבד יש לו הנאה ובפרט הנרצע \" אהבתי \" עד כ \" כ כו '\n[5 על מה שכתבו : \" והרי קרקע ודירה ענינים אחד הוא \", כתב :]\nלא בכ \" מ"],[9200220089,"89\nמענות קודש – ה ' תשמ \" ג\nקכ ח\nלאחר ש \" פ בהו \" ב , כ \" ד אייר ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בהמדובר בהתועדות ש \" פ\nבהו \" ב , בביאור דברי הזוהר פ ' בחוקותי ( ח \" ג קטו , ב ): \" א \" ר חייא כו '\nת \" ח כתיב ונתתי שלום בארץ הוא יסוד , דאיהו שלמא דארעא שלמא\nדביתא שלמא דעלמא \", ומציין הררלי \" צ ( לקולי \" צ ע ' שמח ) שלעיל בזוהר\nפ ' צו ( שם לא , א ) הובא מאמר רשב \" י בסדר הפוך : \" שר שלום דא צדיק\nדאיהו שלמא דעלמא שלמא דביתא שלמא דמטרוניתא \". ונת '\nבהתועדות , שרשב \" י מצד מדריגתו הנעלית לא הוצרך להקדים הענין\nד \" שלמא דארעא \", הכשרת העולם לפעול בו , כי מלכתחילה הי ' אצלו\nשלמא דמטרוניתא \", העולם כפי שנברא ע \" י הקב \" ה ,\" ולכן התחיל\nתומ \" י ב \" שלמא דעלמא \", הפעולה בעולם . במכתבם כתבו :\n\" ע \" פ הנ \" ל מובן מדוע במאמר רשב \" י אין צריכים להדגיש ( ולהתחיל ) עם\n\" שלמא דארעא \", כ \" א \" שלמא דמטרוניתא \". אבל עדיין לא נתבאר\nלכאורה – מדוע הסדר במאמר רשב \" י הוא ש \" שלמא דמטרוניתא \" בא\nלבסוף ( אחר \" שלמא דעלמא \" ו \" שלמא דביתא \"). דהן אמת שבזה מודגש\nשמצד בחי ' רשב \" י אין צריכים להדגיש להכשרת העולם לעבודה ( שהרי\nמצד למעלה הרי העולם טוב מאד ובמצב של שלום כו '), ומתחילים תיכף\nעם עבודה בפועל (\" שלמא דעלמא \" ו \" שלמא דביתא )\" – אבל אעפ \" כ\nהסדר צ \" ל מלמעלמ \" ט – תחלה צריכים לדבר ע \" ד עצם ענין השלום ,\nשהעולם והאדם מוכשרים לכללות ענין העבודה ( שזהו התוכן ד \" שלמא\nדמטרוניתא ,)\" ואח \" כ ע \" ד עבודה בפועל ( בביתא ובעולם ), כמו שהי ' אצל\nהקב \" ה בבריה \" ע : תחלה ברא העולם , \" וירא אלקים את כל אשר עשה\nוהנה טוב מאד \", \" שלמא דמטרוניתא \", ואח \" כ \" ויניחהו בגן עדן לעבדה\nולשמרה כו \"' – א \" כ צ \" ל תחלה \" שלמא דמטרוניתא .\"\nוגם : אי \" מ לכאורה מהו הסדר לפנ \" ז במאמר רשב \" י – תחלה \" שלמא\nדעלמא \" ואח \" כ \" שלמא דביתא ( ואח \" כ \" שלמא דמטרוניתא )\"\" – הרי\nסדר העבודה היא תחלה \" שלמא דביתא \" ואח \" כ \" שלמא דעלמא .\"\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – ריש תו \" מ תפארת לוי\nיצחק ע \" ס ויקרא . \" יחי המלך \" גליון תקיז :)\nהרי כן הי ' הסדר בפועל מתחיל מלמע ' מסההשת \" ל )(\n1) נתאוה כו ' בתחתונים ( תאוה שאין שייך בזה קשיא ( ושכל ) אדה \" ר\n2 ) אח \" כ הטעם בשביל ישראל"],[9200220090,"90\nמענות קודש – ה ' תשמ \" ג\nג ) אח \" כ הבפו \" מ : בראשית – ברא גו ' מטרוניתא\nקכ ט\nלפני חודש סיון ][\nמענה למערכת עיתון \" משיח טיימס \" היו \" ל ע \" י \" צבאות השם \" שהכניסו\nאת שער העיתון דחודש סיון שעליו ציור בו נראים ילדי צבאות השם\nמנשקים את ספר התורה ( תשורה התועדות חסידים אור לועש \" ק שמיני\nתשנ \" ה , והעתקת המזכיר :)\nכדאי לנצל ציור המענטעלע לציור לוחות מרובעות\nקל\nד ' סיון ][\nמענה לר ' שניאור זלמן יפה על מכתבו בצירוף ה \" יומן \" שלו ( ס ' \" Mr.\nManchester ע '\" 280 :)\nנתקבל ( וכל המצורף בזה ) ות \" ח ת \" ח , ובפרט על היומן של 113 עמודים\nוההקדמה עוד 3 , בטח זוכר הדאגה שלו מה יכתוב וכו ', כן יבשר טוב\nבכל הדאגות ל \" ע , ויפסיק לדאוג בבטחון ובשמחה .\nאזכיר על הציון .\nקל א\nתחלת סיון ][\nממענה להשליח הרב יוסף העכט על מכתבו – בקשר לתכנית הדפסת ס '\nהתניא במצרים ( ראה לעיל מענה לא ) – בו כתב שאין רואים כל\nהתקדמות בקשר להשגת האישורים הדרושים , וכתב שלדעת הקונסול\nאם הייתה מגיעה למצרים בקשה מארצה \" ב בדבר הדפסת ס ' התניא ,\nהנה ההתייחסות מצדם תהי ' בודאי אחרת , ובמילא אולי כדאי להפגש\nעם שגריר מצרים בארצה \" ב ולהסבירו ע \" ד בקשת תנועת חב \" ד להדפיס\nאת ס ' התניא במצרים , ואשר הוא יפנה לשלטונות במצרים בבקשה\nלאשר את הדפסת הספר ( תשורה העכט כ \" ט אדר תשס \" ב :)"],[9200220091,"91\nמענות קודש – ה ' תשמ \" ג\nכ \" ק אדמו \" ר שליט \" א ענה בחיוב , והורה שיסע לוואשינגטאן לפגוש את\nשגריר מצרים בארצה \" ב , ולבקש גם ממנו שיפעל להשגת אישור להדפסת\nס ' התניא – וכתב :\n.[ ]. ואולי דודו שי ' שזה עתה פתח אסיפת הקאנגרעס בתפילה ונתפרסם\nברעקארד ישתתף בזה או גם ישתדל בסידור הפגישה וכו ' אזכיר עה \" צ .\nקל ב\nלאחר ש \" פ נשא , ט ' סיון ][\nמענה ל \" ועד הנחות בלה \" ק \" על מכתבם בקשר להמדובר בהתועדות ש \" פ\nנשא , בביאור פרש \" י עה \" פ ( נשא ה , ט ) \" וכל תרומה לכל קדשי בנ \" י אשר\nיקריבו לכהן לו יהי \"' – \" א \" ר ישמעאל וכי תרומה מקריבין לכהן , והלא\nהוא המחזר עלי ' לבית הגרנות , ת \" ל אשר יקריבו לכהן , אלו הביכורים ,\nשנאמר בהם תביא בית ה \" א , ואיני יודע מה יעשה בהם , ת \" ל לכהן לו\nיהי ', בא הכתוב ולימד על הביכורים שיהיו נתנין לכהן \". ונת ' בהתועדות ,\nדר ' ישמעאל שהי ' כהן – \" מסייע כהני \", ולכן משנה את הפסוק\nממשמעותו ומפרש ש \" תרומה \" קאי על ביכורים , כי ע \" ע לא נאמר בכתוב\nשצריך לתת את הביכורים לכהנים ( משא \" כ תרומה ). ובמענה לשאלת\nהמניחים , ענה כ \" ק אדמו \" ר שליט \" א שהמקום בו נתפרש לפנ \" ז בקרא\nשצריך לתת את התרומה לכהן , הוא בפ ' ויחי , ששם פר ש \" י ( עה \" פ מט , ז )\n\" שבטו של לוי עשאו מחזר על הגרנות לתרומות ומעשרות \". ובהמשך לזה\nכתבו :\n\" בהמשך למענה כ \" ק אדמו \" ר שליט \" א בנוגע לפרש \" י דפ ' ויחי , ששם\nהוזכר כבר ש \" שבטו של לוי עשאו מחזר על הגרנות לתרומות ומעשרות \"\n– עדיין לא תפסנו :\nבהתוועדות נתבאר שכאשר לומדים את הפסוק \" וכל תרומה וגו ' אשר\nיקריבו לכהן וגו '\" בפשוטו של מקרא , הנה לשיטת רבי ישמעאל – \" כהנא\nמסייע כהני \" – עדיף לשנות את הפסוק ממשמעותו ולפרש ש \" תרומה \"\nקאי על ביכורים , כדי לסייע לכהנים בכך שהביכורים ינתנו להם , מכיון\nשבפסוק \" תביא בית ה ' אלקיך \" לא נאמר עדיין שצריכים לתת את\nהביכורים לכהנים .\nועל זה שאלנו : אם פסוק זה קאי על ביכורים ולא על תרומה – היכן\nמפורש בקרא לפני פ ' קורח ( כי בפ ' קורח מפורש הן בנוגע לתרומה והן\nבנוגע לביכורים ) שצריכים לתת תרומה לכהנים , ומכיון שענין זה לא\nנתפרש עדיין בקרא , מדוע רואה ר ' ישמעאל לסייע לכהנים בענין"],[9200220092,"92\nמענות קודש – ה ' תשמ \" ג\nהביכורים יותר מאשר בענין התרומה , הרי בנוגע לשניהם לא נתפרש\nעדיין בקרא שצריכים לתתם לכהנים ?\nורצינו לתרץ ע \" פ המבואר בלקו \" ש ח \" ח ע ' 31 – שגם כאשר מפרשים\nש \" תרומה \" קאי על ביכורים , עדיין מפורש בקרא ( כאן ) שגם התרומה\nניתנת לכהנים , מכיון שנאמר \" לכל קדשי בני ישראל . . לכהן לו יהי .\"'\nושאלנו האם זו היתה הכוונה .\nמ \" ש כ \" ק אדמו \" ר שליט \" א שבנוגע לתרומה הוזכר כבר בפרש \" י פ ' ויחי\n– לא תפסנו : הרי ענין זה מפורש רק בפרש \" י ולא בפסוק עצמו , וא \" כ ,,\nכיצד אפשר לומר שהפסוק אינו צריך לחדש כאן שהתרומה ניתנת לכהן\n[ כפשטות לשון הכתוב : \" וכל תרומה וגו ' לכהן לו תהי '\", ולכן אפ \" ל דקאי\nעל ביכורים כדי לסייע לכהנים בענין הביכורים ], מכיון שענין זה נתפרש\nכבר בפרש \" י ?\nבסגנון אחר : כאשר ר ' ישמעאל מפרש שפסוק זה קאי על ביכורים ולא\nעל תרומה ( כדי לסייע לכהנים בענין הביכורים ) – אינו יכול לסמוך על\nפרש \" י בפ ' ויחי .\nוגם : אפילו בפרש \" י דפ ' ויחי לא נתפרש שהתרומה ניתנת לכהנים דוקא ,\nכי אם באופן סתמי – תרומות ומעשרות לשבטו של לוי . ומצד הצורך\nלסייע לכהנים , צריכים לפרש שהתרומה ניתנת לכהנים דוקא . ואם\nנסמוך על זה שהמלמד יסביר לבן חמש למקרא שהתרומות לכהנים\nוהמעשר ללוי כו ', א \" כ , גם בנוגע לביכורים ( בפ ' משפטים ותשא ) יסביר\nהמלמד שהם ניתנים לכהן .\"?\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון שדמ :)\"\n[1 על מה שכתבו : \" ורצינו לתרץ ע \" פ המבואר בלקו \" ש ח \" ח ע '] 31 כתב :\",\nבאם את \" ל שלשון פרש \" י סובל פי ' זה\n[2 ] על מה שכתבו : \" מ \" ש כ \" ק אדמו \" ר שליט \" א שבנוגע לתרומה הוזכר\nכבר בפרש \" י פ ' ויחי \" – על התיבות \" מ \" ש כ \" ק אדמו \" ר שליט \" א \", כתב :\nבאם את \" ל שאינו מרומז אפילו\n[3 ] על מה שכתבו : \" הרי ענין זה מפורש רק בפרש \" י ולא בפסוק עצמו \",\n– מחק את התיבות \" הרי \" \" רק \", וכתב :\n[ ענין זה מפורש בפרש \" י ] שבא לא לחדש דינים , כ \" א לפרט פשוטו ש \" מ\nבויחי"],[9200220093,"93\nמענות קודש – ה ' תשמ \" ג\n[4 ] על מה שכתבו : \" כאשר ר ' ישמעאל מפרש שפסוק זה קאי על ביכורים\nולא על תרומה ( כדי לסייע לכהנים בענין הביכורים ) – אינו יכול לסמוך\nעל פרש \" י בפ ' ויחי \" – מחק תיבת \" אינו \", וכתב :\nיכול לסמוך על ][ פשוטו ש \" מ\n[5 ] על מה שכתבו : \" אפילו בפרש \" י דפ ' ויחי לא נתפרש שהתרומה ניתנת\nלכהנים דוקא , כי אם באופן סתמי – תרומות ומעשרות לשבטו של לוי .\nומצד הצורך לסייע לכהנים , צריכים לפרש שהתרומה ניתנת לכהנים\nדוקא \" – סימן קו הדגשה נוסף תחת תיבת \" לכהנים \", מחק תיבת\nצריכים \", וכתב :\"\nה \" ז ל ' הש \" ס בנוגע לענין אחר שהזכרי אני ולא פרש \" י – בנדו \" ד\nמספיק שהי ' משבט לוי ומסייע שבט לוי ופשוט\nקל ג\nי \" ב סיון ][\nמענה להשליח הרב יוסף העכט על דו \" ח מהפגישה – שלו ושל דודו הרב\nאברהם דוב העכט ( ראה לעיל מענה קל א ) – עם שגריר מצרים בארצה \" ב\nבקשר להדפסת ס ' התניא במצרים ( מצילום כתי \" ק – תשורה העכט כ \" ט\nאדר תשס \" ב :)\nהדו \" ח נת ' ות \" ח ת \" ח ויה \" ר שיבש \" ט מהמשך טוב בכ \" ז וכיו \" ב\nקל ד\nי \" ד סיון ][\nמענה להחתן הת ' אהרן סלונים שכתב : \" מצו \" ב היחידות וכן הנחה\nמהתוועדות דש \" ק פרשת נשא שמקוים לחלק היום בעת סעודת החתונה .\nומבקש הנני בזה ברכת כ \" ק אדמו \" ר שליט \" א \" ( מצילום כתי \" ק – תשורה\nסלונים ד ' מרחשון תשס \" ח :)\n[1 על מה שכתב : \" מצו \" ב היחידות וכן הנחה מהתוועדות דש \" ק \", כתב :]\nנת ודבר בעתו וכו '"],[9200220094,"94\nמענות קודש – ה ' תשמ \" ג\n[2 על מה שכתב : \" הנחה מהתוועדות דש \" ק פרשת נשא \", כתב :]\nנשא ][ את ראש\n[3 על מה שכתב : \" ומבקש הנני בזה ברכת כ \" ק אדמו \" ר שליט \" א \", כתב :]\nמתחיל מבנין עדי עד כו '\n( עיין לקו \" ת פ ' פקודי העדות – עדי עדיים וכו .)'\nאזכיר עה \" צ\nקל ה\nסיון ][\nמענה להשליח ר ' יוסף שמואל יהושע גערליצקי על מכתבו בקשר לרעיון\nפתיחת \" כולל \" בעירו תל - אביב ( מצילום כתי \" ק – תשורה אלטיין ט \" ו\nסיון תשע \" ח . \" התקשרות \" גליון א ' מא :)\nלפי מצב \" עסקנות \" חב \" ד באה \" ק ובפרט בשנה זו – איני רואה שזה\nמעשי\nקל ו\nסיון ][\nמענה להת ' איסר זלמן ווייסברג שהכניס את הקובץ \" ביאורים בפרשת\nהשבוע \" שהכין לש \" פ שלח – עיבוד משיחות כ \" ק אדמו \" ר שליט \" א\nלציבור התורני .\nאת הקובץ הכין בהמשך למכתבו לכ \" ק אדמו \" ר שליט \" א , בו כתב שישנם\nהרבה חידושים בהשיחות שהעולם היש י בתי הליטאי היו בעצם מאד\nמעוניינים בהם , אבל לא בצורתם כפי שהם ערוכים בלקו \" ש . הן משום\nשאינם מורגלים לעיין בחידושי תורה הכתובים באידיש , והן ובעיקר\nמשום ש אינם מורגלים באופן הרצאת הדברים . ומאחר והוא התחנך\nבישיבות ליטא י ות ומבין את מהלך מחשבתם וכן את אופי וסגנון\nהחידו \" ת שהם מורגלים בהם , לכן הוא מבקש רשות מ כ \" ק אדמו \" ר\nשליט \" א לערוך מחדש את אותם החידושים שלפי דעתו היו מתקבלים\nבחיבה אצל העולם היש י בתי ."],[9200220095,"95\nמענות קודש – ה ' תשמ \" ג\nכ \" ק אדמו \" ר שליט \" א ענה ( בע \" פ ) שיעשה דוגמא להבהיר מה הוא\nמתכוון לעשות . בהתאם לזה , ערך קונטרס על פרשת שלח .\nבגלל ההתנגדות החזקה לחב \" ד בכמה חוגים , עלה בדעתו להו \" ל את\nהקונטרסים תחלה מבלי לציין שהם חידושיו של כ \" ק אדמו \" ר שליט \" א ,\nולגלות ז את רק בהמשך הזמן , אחרי שכבר י קנו שם בעולם התורה . וכך\nנעשה בגליון הראשון .\nמענה כ \" ק אדמו \" ר שליט \" א ( ס ' \" היכל מנחם \" ח \" ג ע ' צא . תשורה\nינובסקי כ \" ט ניסן תשנ \" ז :)\nבכלל נכון הדבר וטוב\nאבל למה יהי ' על אחריות יחיד וטוב ומתאים שיהי ' עכ \" פ ג ' מתאימים\n– להעתקה מאידית כדבעי הגה וכו ' –\nכן – אין מוזכר כלל של מי זה !\nהרושם שנאמר ( נכתב ) בשנה זו !\nכן מובן שאין להכניס בפנים מה שלא אמרתי ( וגם בהערה בשוה \" ג –\nצ \" ל זהירות מה לציין ומה שאינו מתאים .)\nקל ז\nסיון ][\nמענה להשלוחה מרת סוניא ווייטמאן על מכתבה בו שאלה האם לבצע\nבדיקות רפואיות מסויימות , כדעה אחידה של כמה רופאים מומחים ; וכן\nכתבה ע \" ד מחשבות כו ' שיש לה ( תשורה ווייטמאן י \" א אלול תשס \" ו :)\nמחשבות ][ זרות – כפשוט \" תזרקם \" החוצה ( ע \" י \" טראכט גוט וועט זיין\nגוט \" כמארז \" ל ) עניתי שאשרי חלקם וכו ' והשם יצליחם עוד יותר\nותבש \" ט"],[9200220096,"96\nמענות קודש – ה ' תשמ \" ג\nקל ח\nסיון ][\nמענה להת ' שמשון אהרן יוניק על מכתבו בו כתב ע \" ד הסיפור שאירע\nבשנת תרפ \" א , כאשר חלה אדמו \" ר מהריי \" ץ , אשר חסידים נתנו אליו\nמשנות חייהם במתנה ; וכתב שלאחר שחשב ע \" ד הנושא ברצינות , החליט\nשרוצה לתת שנה מחייו לכ \" ק אדמו \" ר שליט \" א ( מהעתקה :)\nכוונתו רצוי ', אבל לא יתעסק בענינים שאינם שייכים לו כלל , וכו ' –\nוייקר כל שנה ואפילו יום ללמוד תורה בשקידה וכו ' וזוהי אמיתית\nהנתינה לי\nאזכיר עה \" צ\nקל ט\nסיון ][\nמענה לר ' יעקב יהודה העכט שכתב ( בשני מכתבים ) בקשר להוראת כ \" ק\nאדמו \" ר שליט \" א אשר ילדי ישראל ישלחו \" פעטישענס \" ( עצומות ) לנשיא\nארצה \" ב בקשר לייסוד \" רגע של שתיקה \" בבתי הספר הממשלתיים :\n\" בקשר לה \" פעטיש ע נס \" הי ' לנו אסיפה עריו \" ט , והי ' לנו שאלות אחדות\nאבל כמעט כולם נתיישבו לנו בההתוועדות היום . אבל עדיין נשאר\nשאלות אחדות .\" ( מהעתקה :).\n[1 במכתבו כתב :] \" איפו יהי ' הכתובת למי יפנו אלו שיש להם שאלות ,\nצריכים חיזוק , עצות וכו '. ז \" א האם יהי ' מרכז Central , שיארגן א \" ז או\nכ \" א יעבוד לעצמו ? .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nיברר מי עוד עוסק בזה ויתדברו ביניהם עדכ \" ז ( בחילוקי דעות יבקשו\nב \" ד רבני אנ \" ש שיח ' שיתווך ביניהם )\nאני לא אמנה ראשים כי אז תיכף ומיד יהפכו הענין שזהו בנשיאותי וכל\nשאינו רוצה בזה לא ישתתף וכו ' ( היפך מהדגשתי בזה ) .[ ].\n[2 במכתבו כתב :] \" האם יש בודזשעט ע \" ז . ואם לאו מהיכן ירק זה חי ?\nהאם צריכים לעשות מגבית ע \" ז ? .\"\nיאמרו \" אהא \" מקבצין הון תועפות ."],[9200220097,"97\nמענות קודש – ה ' תשמ \" ג\n[3 במכתבו כתב :] \" עד כמה ללכת עם ה - Media ז \" א רדיא ,, T.V. ,\nהעיתונים , ובכלל הפרסומת ? .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nעיקר ההשפעה ע \" י קשרים אישים ידידותיים , וכו ', עם מנהלי ארגוני\nהחינוך וכו ' .[ ].\nכנ ' נוטה שאני מנהל בכל דבר הכי פשוט וכו ', ולהרבות בצעטלין זהו\nהיפך הנ \" ל ענין כלל וכלל .[ ].\n[4 במכתבו כתב :] \" בנוגע להרגע של תפילה בשתיקה נולד עוד שאלה :\nבנוגע להאינם יהודים : אם נצליח להשפיע על עיר הבירה שיעשו חק\nבנוגע להנ \" ל . אז נהי ' אנחנו הגורמים להאינם יהודים ( בפרט\nהקטוליקים , ולא צריכים ראי ' ע \" ז ) להתפלל לאותו האיש ימש \" ו , ואז\nאנו עוברים על לפני עור לא תתן מכשול , ואפילו אם נאמר שהם יעשו א \" ז\nבלי העזרה משלנו אבל אז הפסק \" ד מהרמב \" ם לכוף את הגוים לשמור\nהז ' מצוות , ואיך אנו יכולים לעשות תעמולה זו ? ואנא ליתן לי כקאד \" ש\nהתירוץ ע \" ז .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nהגדיל עשוה שאהי ' ממלא מקום על הלומדים וכו ', הרי עד \" ז המנגדים\nטומלען כל הזמן , ולאחר עשר שנים שואל תירוץ אצלי .\nוכו \" כ תירוצים מעשה אבותיהם בידיהם ובפרט בחלק העבוד \" ז\nשבנצרות , המותר לא לעשות באמונת רבבות בנ \" י מפני החשש דלפני\nעור דבני נח ועוד .[ ].\nקמ\nועש \" ק שלח , כ \" ב סיון ][\nמענה למערכת \" ספר הליקוטים – דא \" ח צמח צדק \" ( מצילום כתי \" ק –\nקובץ \" לקט מענות קודש בקשר להדפסת ספר הליקוטים דא \" ח צמח\nצדק \" ע ' 46 :)\n[1 ] במכתבם כתבו : \" מצו \" ב הגעליס של רשימת ראשי תיבות שבספר\nהליקוטים .\""],[9200220098,"98\nמענות קודש – ה ' תשמ \" ג\nמענה כ \" ק אדמו \" ר שליט \" א :\nנת ' ות \" ח\n[2 במכתבם כתבו : \" עדיין לא ידוע לנו הפיענוח של הר \" ת :] מהו רש \" ב ;\nמהו ריי \" צ – אף ששאלנו כמה מבינים .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nשמות כמה מבינים ][ של לנו ][\nקמא\nכ \" ד סיון ][\nמענה למערכת \" ספר הליקוטים – דא \" ח צמח צדק \" שכתבו :\n\" בקשר למענה כ \" ק אדמו \" ר שליט \" א לספר הליקוטים , בנוגע לפיענוח\nהר \" ת מהו רש \" ב , מהו ריי \" צ , מצו \" ב רשימת שמות האנשים ששאלנו :\nהרה \" ת יואל כהן , הרה \" ת שלום מאראזאוו , הרה \" ת אלימלך צוויבעל ,\nהרה \" ת שלום בער לעווין , חברי ועד להפצת שיחות , חברי ועד הכתבים .\nלאחר מענת כ \" ק אדמו \" ר שליט \" א , שאלו את [ ח . ל .], והוא אמר\nשהפיענוח של \" מהו \" הוא \" מורנו ורבנו הרב \" או \" מורנו הרב \" ( כמו\n\" מוה \"), ורק שהכותבים לא דקו בסדר האותיות \" מהו \", אף שהגירסא\nהנכונה היא \" מוה .\"\nועפ \" ז , האם להכניס ברשימת הר \" ת : מהורש \" ב – מורנו ורבנו הרב . . .\n.\"?\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – קובץ \" לקט מענות קודש\nבקשר להדפסת ספר הליקוטים דא \" ח צמח צדק \" ע ' 46 :)\n[1 על מה שכתבו : \" שהפיענוח של \" מהו \" הוא \" מורנו ורבנו הרב \"\"] –\nכ \" ק אדמו \" ר שליט \" א שינה ושם את תיבת \" הרב \" לפני תיבת \" ורבנו \"\nמורנו הרב ורבנו .]\"[\"\n[2 על מה שכתבו : \" ורק שהכותבים לא דקו בסדר האותיות \"] – על תיבת\nשהכותבים \", כתב :\"\nהמעתיקים"],[9200220099,"99\nמענות קודש – ה ' תשמ \" ג\n[3 ] מחק את מה שכתבו : \" שהגירסא הנכונה היא \" מוה \"\", ואת מה\nשכתבו : \" ועפ \" ז , האם להכניס ברשימת הר \" ת : מהורש \" ב – מורנו ורבנו\nהרב . . . .\"?\nקמ ב\nאור לער \" ח תמוז ][\nמענה לר ' לוי גאלדשטיין שכתב : \" היום הציעו לי משרת מלמדות במחנה\nגן ישראל דניו יארק לקיץ הבעל \" ט . ועבור זה נותנים דירה ואכילה וכו '\nעבור המשפחה שיחיו . ב 2 שנים שעברו היינו שם , והי ' ב \" ה בהצלחה .\nוהננו שואלים עצת כ \" ק אדמו \" ר שליט \" א האם לקבל ההצעה \"\n( מהעתקה . המענה מתפ רסם בזה לראשונה באדיבות הנמען שי ' וזכות\nהרבים תלוי ' בו :)\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות \" ב 2 שנים שעברו היינו שם ,\nוהי ' ב \" ה בהצלחה \"; מחק תיבת \" האם \" וסימן בחץ ובעיגול את התיבות\nלקבל ההצעה \", וכתב :\"\nאזכיר עה \" צ\nקמ ג\nועש \" ק חוקת , ו ' תמוז ][\nמענה למערכת \" ספר הליקוטים – דא \" ח צמח צדק \" שכתבו : \" בקשר\nלהוראת כ \" ק אדמו \" ר שליט \" א לערוך מילואים לסה \" ל : לאחר שיצא\nלאור אוה \" ת בראשית כרך ז ' – ערכנו מילואים להערכים דסה \" ל אותיות\nא – ל , והוספנו הוספות להמילואים שכבר נערכו מאותיות מ – ת , –\nמלוקט מאוה \" ת הנ \" ל . ומצו \" ב המילואים דאותיות : כ , ל , נ , ס , ע , פ , צ ,\nק , ש \" ( מצילום כתי \" ק – קובץ \" לקט מענות קודש בקשר להדפסת ספר\nהליקוטים דא \" ח צמח צדק \" ע ' 47 :)\nנת ' ות \" ח ת \" ח\nובודאי ימהרו בההו \" ל וה ' יצליח\nלהחזיר"],[9200220100,"100\nמענות קודש – ה ' תשמ \" ג\nקמ ד\nועש \" ק חוקת , ו ' תמוז ][\nממענה לא ' מאנ \" ש שכתב ע \" ד ריבוי מעשי הגניבות בשכונת קראונהייטס\nמהעתקה . המענה מתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי '(\nוזכות הרבים תלוי ' בו :)\nירעישו בועד השכונה שסו \" ס יעשו בשטח זה כדרוש .[ ].\nקמ ה\nט ' תמוז ][\nמענה לא ' מתושבי שכונת קראונהייטס שכתב : \" זה לא כבר , נתברר לנו\n( ע \" י בדיקה ) שאשתי תי ' היא מעוברת ב \" ה , והננו מבקשים את ברכת\nכ \" ק אדמו \" ר שליט \" א שיהי ' ההריון כשורה ובנקל ובהצלחה , בוולד שלם\nבגו \" ר בבריאות הנכונה . ושתרגיש טוב . גם , הננו שואלים עצת כ \" ק\nאדמו \" ר שליט \" א ב נוגע להרופא , בעבר היא בקרה ד \" ר . . וד \" ר . .\nבפלעטבוש ), ושמענו שיש רופא . . שיש לו משרד בשכונתנו , כאן צוה ה '(\nאת הברכה . ושאלתנו היא האם להמשיך ברופא שעבר ( שהיתה שבעת\nרצון מהם ) או כדאי להחליף להרופא . .\" ( מהעתקה . המענה מתפרסם\nבזה לראשונה באדיבות הנמען שי ' וז כות הרבים תלוי ' בו :)\nכרצון זוג ' תי '\nאזכיר עה \" צ\nקמ ו\nיו \" ד תמוז ][\nמענה למערכת \" ספר הליקוטים – דא \" ח צמח צדק \" שכתבו : \" מצו \" ב\nהגעליס של \" תוכן ומפתח הערכים ( – רשימת הערכים והסעיפים ) של\nספר הליקוטים אותיות כ \" ף – תי \" ו . בספר הליקוטים אותיות אל \" ף –\nיו \" ד ישנו כבר בסוף כל ספר \" תוכן ומפתח הערכים \" – ויודפס בכרך\nהמילואים באופסט . גם מצו \" ב דוגמא של סדר העמוד מ \" תוכן ומפתח\nהערכים \"\" ( מצילום כתי \" ק – קובץ \" לקט מענות קודש בקשר להדפסת\nספר הליקוטים דא \" ח צמח צדק \" ע ' 48 :)"],[9200220101,"101\nמענות קודש – ה ' תשמ \" ג\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול תיבת \" מצו \" ב \", וכתב :\nלהחזיר\nויה \" ר שיהא כ \" ז בהצלחה , ויו \" ל בזריזות וכו '\nאזכיר עה \" צ לבשו \" ט בכ \" ז וג \" כ בזריזות\nקמ ז\nי \" ב תמוז ][\nמענה למערכת \" ספר הליקוטים – דא \" ח צמח צדק \" שכתבו : \" מצו \" ב\nמילואים לאותיות : ג , ה , ח , ט , י , מ , ר , ת \" ( מצילום כתי \" ק – קובץ \" לקט\nמענות קודש בקשר להדפסת ספר הליקוטים דא \" ח צמח צדק \" ע ' 48 :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול תיבת \" מצו \" ב \", וכתב :\nלהחזיר\nבודאי יזדרזו בההו \" ל וכמדובר כו \" כ פעמים וה ' יצליחם\nוסימן שני קווים תחת תאריך המכתב \" חג הגאולה י \" ב תמוז .\"\nקמ ח\nי \" ב תמוז ][\nמענה לר ' אלתר לוי רייטער ששאל האם לפתוח מרפאה לאודיאולוגי '\nבשכונת קראונהייטס ( מהעתקת המזכיר . המענה מתפרסם בזה\nלראשונה באדיבות הת ' מנחם מענדל שי ' הכהן העכט וזכות הרבים תלוי '\nבו :)\nהאין בזה השגת גבול\n[ במכתבו שאל גם בקשר לבעי ' רפואית מסויימת – ועל זה ענה כ \" ק\nאדמו \" ר שליט \" א ( תוכן ): לשמוע לרופא , לא לפחד .]"],[9200220102,"102\nמענות קודש – ה ' תשמ \" ג\nקמ ט\nועש \" ק בלק , י \" ג תמוז ][\nמענה לר ' אלתר לוי רייטער על מכתבו בהמשך להמענה שקיבל בנוגע\nלפתיחת מרפאה בשכונה ( מהעתקת המזכיר . המענה מתפרסם בזה\nלראשונה באדיבות הת ' מנחם מענדל שי ' הכהן העכט וזכות הרבים תלוי '\nבו :)\nאזכיר על הציון\nק נ\nועש \" ק בלק , י \" ג תמוז ][\nמענה למערכת \" ספר הליקוטים – דא \" ח צמח צדק \" שכתבו : \" מצו \" ב\nמילואים לאותיות : א . ב . ד . ז . – ובזה נשלם עריכת המילואים להערכים \"\n( מצילום כתי \" ק – קובץ \" לקט מענות קודש בקשר להדפסת ספר\nהליקוטים דא \" ח צמח צדק \" ע ' 49 :)\nנת ' ות \" ח\nלהחזיר\nובודאי יו \" ל בהקדם ובזריזות\nאזכיר עה \" צ\nקנא\nלאחר ש \" פ בלק , י \" ד תמוז ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א להמניחים בקשר\nלהמדובר בהתועדות ש \" פ בלק – בביאור הטעם שפרש \" י בפירושו\nהראשון עה \" פ \" הן עם כלביא יקום וגו '\", \" כשהן עומדין משינתם שחרית\nהן מתגברים כלביא וכארי לחטוף את המצות ללבוש ציצית לקרוא את\nשמע ולהניח תפלין \", ולא דקאי על מלחמת כיבוש ארץ ישראל כמשמעו\n( וכפירושו השני ), וטעם הדבר הוא – מכיון שהבן חמש למקרא יודע\nמלימודו לפנ \" ז שלא היו מלחמות \" כארי \" אז ( מצילום כתי \" ק – תשורה\nזאנדהויז ז ' אדר תשע \" ב :)"],[9200220103,"103\nמענות קודש – ה ' תשמ \" ג\nכדי למנוע שקו \" ט וכו ' להוסיף בהר \" ד :\nמנין יודע הבן ה ' שלא היו מלחמות כארי בסוף ימי המדבר ובכבוש א \" י\n–\nמפרש \" י שכבר למד ויחי ברכות יעקב לבניו .\nקנ ב\nלאחר ש \" פ בלק , י \" ד תמוז ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בהמדובר בהתועדות ש \" פ\nבלק :\nנזכר בהשיחה מאמר ספר יצירה ( פ \" ב משנה ב '\" – ע \" פ כמה נוסחאות )\nשאין למעלה מעונג . ואף שישנו השקו \" ט בהמשך תרס \" ו בנוגע לרצון\nותענוג מי קדם למי – אי \" ז שייך למ \" ש בספר יצירה . ובפרט ע \" פ מנהג\nישראל ( במילא יש לזה יסוד ) שכל פיסקא דספר יצירה נק ' \" משנה ,\"\nובמילא חל על זה דוגמת הכלל דהטועה בדבר משנה חוזר .\nאבל בהמשך תרס \" ו ( ס \" ע סג . ע ' עב ואילך ) מביא מאמר ספר יצירה דאין\nלמעלה מעונג בקשר עם החקירה אם תענוג קדם לרצון או להיפך , שע \" פ\nמאמר דאין למעלה מעונג הרי עונג קדם לרצון . ומסיק שם בההמשך ( ע '\nעב ) שתענוג הוא למעלה מרצון , כי אין למעלה מעונג ( ולא אומרים אין\nלמעלה מרצון ), כמבואר שם .\nוכן בקונטרס לימוד החסידות ע ' 4 הובא המאמר אין למעלה מעונג בקשר\nעם חקירה זו בתור ראי ' שתענוג קדם לרצון . וכן הוא בשער היחוד פכ \" ג .\nוא \" כ מה היתה הכוונה שהחקירה בנוגע רצון ותענוג מי קדם למי לא\nשייך למאמר ספר יצירה דאין למעלה מעונג . ובפרט שזהו בדוגמא\nהטועה בדבר משנה חוזר .\"?\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה פולטורק ג ' כסלו\nתשס \" ה :)\nכו \" כ מקושיותיהם בעבר ( ושל כיו \" ב ) הן בסגנון הנ \" ל – ובהנ \" ל גופא\nלא שמו לב להסתיר ות שבהמצויין לעיל בזל \" ז – ופשיטא ממ \" א –\nולשיטתם – הקלאץ קושיא בהרגיל בכ \" מ באדהאמ \" צ \" ודלא כנ \" ל ,\"\nולא השמיט ה \" כנ \" ל \" ( ועד \" ז בנגלה ומשנה לא זזה וכיו \" ב )"],[9200220104,"104\nמענות קודש – ה ' תשמ \" ג\nואולי סו \" ס יעיינו בראש התניא בהג \" ה : וע ' פנים לתורה .\n___\nעצם העונג ( – ואין שייך לומר ע \" ז \" שורש \" \" עיקר \" וכיו \" ב , כ \" א ע \" ד\n\" שם המושאל \" וג \" ז צע \" ג אם שייך ) –\nשעשועי המלך בעצמותו\nולא נמצא זה ברצון .\nקנ ג\nתמוז ][\nמענה כללי - פרטי דימים אלו [ בין השאר – למערכת \" הערות התמימים\nואנ \" ש – פלפול ועיון בשיחות כ \" ק אדמו \" ר שליט \" א \" שע \" י תלמידי\nישיבת תו \" ת לוד בקשר לגליון לב שהכניסו ( מהעתקה . וראה לקמן מענה\nקס ז :])\nנת ' ות \" ח ת \" ח\nודבר בעתו – בסמיכות לחג הגאולה יב - יג תמוז ה ' תשמ \" ג\nאזכיר עה \" צ\nקנ ד\nתמוז ][\nמענה לר ' אפרים וואלף על מכתבו ע \" ד א ' מישיבות חב \" ד באה \" ק ( ס '\nימי תמימים \" ח \" ח ע '\" 189 :)\nכפשוט שייך להנהלות ישיבות תו \" ת – וכך להבא ."],[9200220105,"105\nמענות קודש – ה ' תשמ \" ג\nקנ ה\nתמוז ][\nמענה לר ' אפרים וואלף על מכתבו בקשר לא ' מעובדי ישיבת תו \" ת\nהמרכזית באה \" ק ( ס ' \" ימי תמימים \" ח \" ח ע ' 189 :)\nאחת ולתמיד בכל הנ \" ל וכיוצ \" ב שייך לבי \" ד רבני אנ \" ש דאה \" ק .\nקנ ו\nתמוז ][\nמענה לנערה ששאלה ע \" ד מקום המשך לימודי ' ( מהעתקה . המענה\nמתפרסם בזה לראשונה באדיבות ר ' יחיאל יהודה שי ' קופצ ' יק וזכות\nהרבים תלוי ' בו :)\nקדימה למקום שבו למדה\nקנ ז\nתמוז ][\nמענה לר ' שלום דובער לוין ( קובץ \" עבודת הקודש אצל הרבי \" ע ' קכ :)\n[1 ] במכתבו כתב : \" על כתובת \" יגדיל תורה \" נתקבלו לאחרונה כמה\nקטלוגים של הוצאות ספרים . האם כדאי להשיב להם ( אולי מהספריה\nאו מ \" קה \" ת \") שמעונינים בספרים שעדיין אינם כאן , ותמורתם יושלחו\nספרי קה \" ת .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\nתלוי – מבין אלה שעדיין לא שולחים בלאה \" כ – להשייכים להנ \" ל .\n[2] למכתבו צירף מכתב - חוזר שנתקבל אודות מהדורת צילום מסידור\nמצוייר .\nמענה כ \" ק אדמו \" ר שליט \" א :\nלא שייך לזה כלל ."],[9200220106,"106\nמענות קודש – ה ' תשמ \" ג\nקנ ח\nכ \" ד תמוז ][\nמענה לר ' יעקב יהודה ארי ' ליב זאיאנץ ששאל האם להעביר את המכללה\nלבנות מהעיר פטרופוליס לעיר ריא , לאחר התרעה על התקפה ( ס '\nישיבה של מעלה \" ע '\" 444 :)\nוכן יעשו\nקנ ט\nועש \" ק מטו \" מ , כ \" ז תמוז ][\nמענה להרב מרדכי מענטליק ( מצילום כתי \" ק – תשורה קליין י \" ז סיון\nתשס \" ו :)\n[1 ] במכתבו כתב : \" הנני מוסר בזה מכתבי מענה של הישיבות ע \" ד לימוד\nמסכת חדשה על זמן הבע \" ל , מסכת ב \" ב שלמדנו בשנת תשל \" ו , או מסכת\nב \" ק שלמדנו בשנת תשל \" ז .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול קטע זה , וכתב :\nלהחזיר\n[2 במכתבו כתב : \" במאנטרעאל , כפר חב \" ד ( ע \" י הטלפון ), תו \" א ,]\nאוסטראליא , וכן בכאן , מסכימים ללמוד מסכת ב \" ב . בראשון - לציון\nנוטים ללמוד מסכת ב \" ק . מצרפת לא נתקבל מענה ע \" ע .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nואחרי רבים להטות ויהא בשטומו \" צ\nויה \" ר שבקרוב ממש יחזיר הקב \" ה האבדה – ואבדתם בגויים – דא ב \" ב\nזח \" ג קצח , א )( – תליתאה למקומה ולביהמ \" ק תליתאה"],[9200220107,"107\nמענות קודש – ה ' תשמ \" ג\nקס\nשלהי תמוז ][\nמענה להרב מרדכי מענטליק שכתב – בקשר למראי - מקומות להמענה\nשקיבל : \" אם להוסיף : פי ' הזהר עיין בלקלוי \" צ שם , ומתרץ קושית\nניצוצי אורות שם \" ( מצילום כתי \" ק – תשורה קליין י \" ז סיון תשס \" ו :)\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" אם \" וסימן בחץ מה שכתב \" להוסיף\nכו .\"'\nקסא\nשלהי תמוז ][\nמענה להמזכיר רחי \" ק שהכניס תרומה בקשר ליארצייט אביו , וכתב :\n\" לעילוי נשמת שמעי ' בן זאב ארי ' ע \" ה היא \" צ העשרים שלו כ \" ג תמוז\nתשג \" מ \" ( מצילום כתי \" ק – תשורה קארף ג ' ניסן תשע \" ז :)\nותנצבה\nלכולל\nקס ב\nלאחר ש \" פ מטו \" מ , כ \" ח תמוז ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א להמניחים – בקשר\nלהמדובר בהתועדות ש \" פ מטו \" מ מבה \" ח מנ \" א , שנתבאר של ' הרמב \" ם\n\" הר הבית והוא הר המורי '\" בא לתרץ איך יכלו לבנות ביהמ \" ק בהר שבו\nעבדו כנענים עבודה זרה ( מצילום כתי \" ק – תשורה גראנער ח ' כסלו\nתשע \" ד :)\nלהר \" ד דשקממנ \" א\nריטבא עז נג , א דאף במעשה אינו אוסר דבר שאינו שלו\nבכלל – לעיין אנצקלופדיא מע ' דבר שאינו שלו\n___\nבהערה במקום המתאים\nמעניני י \" ז בתמוז העמיד צלם ב ( כבר הי ') היכל"],[9200220108,"108\nמענות קודש – ה ' תשמ \" ג\nקס ג\nועש \" ק דברים , ה ' מנ \" א ][\nמענה לה \" ועד להפצת שיחות \" שהכניסו את הספר לקוטי שיחות כרך כב\n( מצילום כתי \" ק – \" בית משיח \" גליון 269 :)\n[1 על תאריך המכתב \" ועש \" ק פ ' דברים \", כתב :]\nפ ' חזון\nותחזינה כו '\n[2 על כללות המכתב , כתב :]\nנת ' ות \" ח ת \" ח\nאזכיר עה \" צ\nקס ד\nיו \" ד מנ \" א ][\nמענה למרת טעמא גורארי ' שביקשה ברכה עבור אחיינה התינוק שלקה\nבהרעלת דם , ושמונה עשר רופאים ממליצים לנתחו , בעוד שרופא ידיד\nמתנגד לכך ( ס ' \" הרב אשכנזי \" ע ' 529 תשורה אשכנזי ב ' אדר תשס \" ח :).\nכעצת רופא ידיד . אזכיר על הציון .\nקס ה\nלאחר ט \" ו במנ \" א ][\nמענה לר ' צבי הירש נאטיק שכתב : \" בקשר להמדובר בהתוועדות דאור\nלט \" ו באב בביאור גרסת הירושלמי \" הכאורות \" – באל \" ף – הנני בזה\nלהעיר מספר \" רמזי דחכמתא \" להרה \" ג מוהר \" ר שמואל ארי ' לייב ז \" ק\nזצ \" ל , אבד \" ק ביאלא גדול ( שנדפס ז \" ע מחדש ), וז \" ל ( בהוצאה זו ע ' 96 :)\nבירושלמי גרס כאורות באלף ויש לפרש בו ל ' אור , וזה כתוב רק\nבירושלמי שהוא בחי ' עלמא דאתכסיא , משא \" כ בבלי הגירסא כעורות\nמלשון כ תנות עור בעי \" ן והבן \" ( מצילום כתי \" ק – תשורה כ \" ח אדר\nתשס \" ד :)"],[9200220109,"109\nמענות קודש – ה ' תשמ \" ג\nנת ' ות \" ח\nוראה לקו \" ש חכ \" ד ע '[ 57 הערה 15 .]\nקס ו\nמנ \" א ][\nמענה להמזכיר רחי \" ק שהכניס תרומה בקשר ליארצייט אמו , וכתב :\n\" לעילוי נשמת עטא בת אברהם דוד שמרי ' ע \" ה היא \" צ הט \" ז שלה י \" ב\nמנחם אב תשג \" מ \" ( מצילום כתי \" ק – תשורה קארף ג ' ניסן תשע \" ז :)\nותנצב \" ה\nלכולל\nקס ז\nמנ \" א ][\nמענה למערכת \" הערות התמימים ואנ \" ש – פלפול ועיון בשיחות כ \" ק\nאדמו \" ר שליט \" א \" שע \" י תלמידי ישיבת תו \" ת לוד שהכניסו את גליון לב\nשהו \" ל , וכתבו שהחוברת יצאה במימון התמימים ואנ \" ש מכיון שלא הי '\nמי שיממן זאת , וכתבו שאין ביכולתם לשאת עוד את המשא הזה על\nכתפיהם ונאלצים לסגור את המערכת ( לקו \" ש חל \" ט ע ' 242. ס ' \" נלכה\nבאורחותיו \" ע ' 225 והעתקה :).\nכפשוט – משא הכספי אינו שייך לכתפים שלהם כלל וכלל . וענינם –\nכחמור למשא דלימוד התורה הנגלה והחסידות , ולמשא לה . ולא יקחו\nע \" ע משא דאחרים שה \" ז גורע במשא שלהם וק \" ל . ויקבלו שכר על\nהפרישה .\nוצירף את המענה כללי - פרטי דימים אלו ( לעיל מענה קנ ג .)"],[9200220110,"110\nמענות קודש – ה ' תשמ \" ג\nקס ח\nלאחר ש \" פ ראה , כ \" ז מנ \" א ][\nמענה ל \" ועד הנחות בלה \" ק \" על מכתבם בקשר להמדובר בהתועדות ש \" פ\nראה : \" בנוגע לכלל בפרש \" י בענין חסר ויתיר , שרש \" י מדגיש ומפרש\nתיבת \" חסר \" כאשר מדובר אודות ענין של חסרון – עברנו על כל פירושי\nרש \" י בחומש שבהם מובא הענין ד \" חסר \", וברובם – מובן בפשטות כלל\nזה , אלא שבכמה מהם , לכאורה , דרוש עדיין ביאור בהתאם לכלל זה .\nועל סדר הכתובים : . .\" ( מצילום כתי \" ק – יחי המלך \" גליונות : תק ,\"\nתקמ , תקמב , תרפד :)\n[1 במכתבם כתבו :] \" 2 ) בראשית א , כח : \" וכבשה – חסר וי \" ו , ללמדך\nשהזכר כובש את הנקבה שלא תהא יצאנית כו \"' – שלילת ענין של חסרון .\n.\")?(\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" שלא תהא יצאנית כו ' ,\"\nוכתב :\nמשא \" כ הזכר\nכי דעתה קלה ותנזק .\n[2 במכתבם כתבו :] *\" 2 ) בראשית ו , ב : \" כי טבת הנה – טבת כתיב , כשהיו\nמטיבין כו ' גדול נכנס כו '\". ולכאורה , הרי זה ענין של חסרון , ומדוע לא\nכתב רש \" י \" חסר \" כתיב .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\n1 זהו ל ') ר \" י ולא דרש \" י )(\n2 ) בשעת \" ויראו \" לא היו בחסרון\nמעלה הכי גדולה שעד שנכנס גדול כו '( – כי צנועות ( ראה פרש \" י ח \" ש\nכד , טז ) היו – ורש \" י מוכרח לומר כן ע \" פ פש \" מ – ולא לכתוב חסר –\nושלא היו צנועות\nאלא שידעו שסופן לא טוב\n3 ) גם שמו יודן – חסר ה \" א כתיב ואם ידגיש חסר כתיב כו '"],[9200220111,"111\nמענות קודש – ה ' תשמ \" ג\n[3 במכתבם כתבו :] \" 7 ) וירא יט , א : \" ולוט ישב – ישב כתיב , אותו היום\nמינוהו שופט עליהם \" – ענין של מעלה ( אף שמודגש בזה שרק אותו יום\nמינוהו כו ', מכיון שלא הי ' ראוי לכך .))?( 8 ) חיי שרה כג , י : \" ועפרון ישב\n– כתיב חסר אותו היום מינוהו שוטר כו \"', – ענין של חסרון , מכיון שלולי\nשאברהם הי ' צריך לו , לא הי ' ראוי לזה ( כמשנ \" ת בהתוועדות .\")\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" אותו היום . . אותו\nהיום \" וכתב :\nוכל הנהגותיהם ע \" ע אינן באשמתו כלל\n[4 במכתבם כתבו :] \" 10 ) חיי שרה כד , לט : \" אלי לא תלך האשה – אלי\nכתיב , בת היתה לו לאליעזר , והי ' מחזר למצוא עילה כו \"' – ענין של מעלה\nביחס לאליעזר ( אף שביחס לאברהם הרי זה ענין של חסרון , \" אין ארור\nמדבק בברוך .\")\"\nעל התיבות \" ענין של מעלה ביחס לאליעזר כתב :\",\nלבתו – שלולא חטאו דחם – ראוים ליצחק\n[5 במכתבם כתבו :] \" 11 ) חיי שרה כה , ו : \" הפילגשים – חסר כתיב , שלא\nהיתה אלא פילגש אחת כו '\". ולכאורה : מהו החסרון בזה שלא היתה\nאלא אחת .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\nמבהיל – ה \" ז חסרון הכי בולט – שאין בפלג שים אלא אחת\n[6 במכתבם כתבו :] \" 12 ) תולדות כה , כד : \" והנה תומים בבטנה – חסר\nכו ' אחד צדיק ואחד רשע \" – ענין של חסרון ( כמשנ \" ת בהתוועדות .) 13 )\nוישב לה , כז : \" מלא , ולהלן תומים חסר כו '\", כנ \" ל . [ אבל עדיין לא נתבאר\nמדוע חוזר רש \" י ענין זה ב \" פ , ובפרשיות הסמוכות זו לזו – גם בפ '\nתולדות ו גם בפ ' וישב .\"]\nמענה כ \" ק אדמו \" ר שליט \" א :\nובתולדות בהוספת \" א ' צדיק \"\nתומם – חסר א וגם יו \" ד שהוא דוקא סימן לרבים . וצ \" ע בפרש \" י\n[7 במכתבם כתבו :] \" 14 ) שמות ג , טו : \" זה שמי לעלם – חסר וי \" ו , לומר\nהעלימהו שלא יקרא ככתבו \" – חסרון בגילוי אלקות .\""],[9200220112,"112\nמענות קודש – ה ' תשמ \" ג\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" העלימהו שלא יקרא ;\"\nהוציא את התיבות \" בגילוי אלקות \" ( תיבת \" בגילוי \" ע \" י מחיקה , ותיבת\nאלקות \" ע \" י סימון להוציא ); וכתב :\"\nחסרון ][ הכי בולט\n[8 במכתבם כתבו :] \" 19 אמור כג , מ : \" כפת תמרים \") – חסר וי \" ו , למד\nשאינה אלא אחת \". ולכאורה : מהו החסרון שבדבר .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\nמבהיל – חסרון הכי בולט\nוסימן בחץ למש \" כ לעיל סעיף 5.\n[9 במכתבם כתבו :] \" 22 ) בלק כב , ה : \" והוא יושב ממלי – חסר כתיב ,\nקרובים הם להכריתני כו \"' – ענין של חסרון ביחס לבלק .\"\nעל התיבות \" קרובים הם להכריתני \", כתב :\nותחסר כל מציאותו\n[ 10 במכתבם כתבו :] \" 23 ) דברים א , יג : \" ואשמם בראשיכם – חסר יו \" ד ,\nלומר שאשמותיהם של ישראל כו \"' – ענין של חסרון \" .\nמענה כ \" ק אדמו \" ר שליט \" א :\nואשמם ][ ענין דגדלות והפכו שאשמותיהם ][\n[ 11 במכתבם כתבו :] \" 24 ) דברים ב , לג : \" ואת בנו – בנו כתיב , שהי ' לו בן\nגבור כמותו – ענין של מעלה , שהיכו גם את בנו , אף שהי ' גבור כמותו .\"\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" שהיכו גם את בנו , אף \", וכתב :\nמבהיל\n[ 12 ] במכתבם כתבו : \" עדיין לא תפסנו : מהו הביאור בנוגע לפסוק \" לדרת\nעולם \", מדוע כותב רש \" י \" חסר \", הרי מדובר בענין של מעלה – דורם של\nצדיקים כו '. ואף שמודגש החסרון דדורות אלו – הרי חסרון זה הוא\nמעלה .\"\nעל התיבות \" מדוע כותב רש \" י \" חסר \"\", כתב :\nה \" ז פשוטו ש \" מ שהדורות חסרים דורו של חזקי ' כו '"],[9200220113,"113\nמענות קודש – ה ' תשמ \" ג\n[ 13 על כללות המכתב , כתב ( בראש המכתב :)]\nמפליא – עד כמה ששוללים כל פי ' פשוט !\n[ 14 על כללות המכתב , כתב ( בסיום המכתב :)]\nועוד י \" ל ( בכמה מהנ \" ל )\n[ רשימת המקומות שבהם פירש רש \" י את הטעם דחסירות – ע \" פ מענה\nזה – נדפס בלקו \" ש חכ \" ט ע ' 58 ואילך .]\nקס ט\nט \" ו אלול ][\nמענה לר ' יוסף ברוך הכהן פרידמאן שכתב : \" בקשר לנסיעתי לתערוכת\nספרי המל \" ח קה \" ת וכו ' במאסקווא , קבלתי את הוויזא להנסיעה הנ \" ל ,\nומצו \" ב תכנית הנסיעה . נתעוררו איזו שאלות בנוגע להנ \" ל \" – ושאל\nבנוגע התעסקות בהפצה , שיעורים וכו ', וכתב : \" והנני שואל את כ \" ק\nאדמו \" ר שליט \" א איך להתנהג בכל הנ \" ל \" ( מצילום כתי \" ק – תשורה\nליפסקר ח \" י סיון תשע \" ג :)\nה \" ה נוסע לשם בתור ב \" כ המל \" ח קה \" ת וכו ]'[ ובזה יתעסק ובמרץ\nבאופן המותר ע \" פ החוק שם )( –\nוכל השאר שייך לאלו דאנ \" ש שי ' הטוריסטן וכיו \" ב\nאזכיר עה \" צ להצלחה רבה\nקע\nאלול ][\nמענה לא ' מעסקני אנ \" ש על מכתבו בנושא כללי מסויים ( מצילום כתי \" ק\n– ס ' \" מבית המלכות \" ח \" א ע ' 67 :)\n[1 על כללות המכתב , כתב :]\nכנראה מאכט ער זיך"],[9200220114,"114\nמענות קודש – ה ' תשמ \" ג\n[2 ] במכתבו כתב : \" וכבר שאלתי אודות זה מכ \" ק . אכן כתוב אתה\nהחילות . ונבקש עוד הפעם .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nהמענה כאז , ואדרבה , כי \" קירוב הלבבות \" עוד הוגרע , ר \" ל , באנ \" ש .\nובודאי ירחם השם ותהא כוח \" ט הנרונ \" ג ( 2 )\nמהיר\nח\nקעא\nאלול ][\nמענה להשליח ר ' נחמן סודאק ( ס ' \" היכל מנחם \" ח \" ג ע ' קנג :)\nע \" פ מה ששמעתי ( וכמה פעמים ) מכ \" ק מו \" ח אדמו \" ר :\n(1 ) מוסד חינוך כשר אמתי – אין לו לדחות קבלת תלמיד ( ה ) אפילו ליום\n– כי אין בטחה שמחר יפגשהו ויתרצה להכנס לביה \" ס ואין בטחה לאן\n( איזה חינוך ) יתגלגל וה \" ז עכ \" פ ספק פקו \" נ רוחני לכל חייו\n(2 ) ופשיטא שאין לצמצם כתות הקיימות כבר .\n3 ) משא \" כ לדוחק בכסף – שיש למלאתו מחר מבלי גריעותא , יש\nלהשתדל למצוא עוד נדיבים מחר , לקבל הלוואה נוספת מחר .\n4 ) ע \" פ טבע הדבר – כשיש ת ' רבים - ות , סו \" ס זה ממשיך נדיבים\nנוספים והוספה בהתרומות .\n5 ) פשיטא שכל ת ' נוסף – מוסיף בברכת השם להמוסד .\n6 ) אזכיר עוה \" פ עה \" צ בהנוגע .[ ]. נוסף על שאזכיר בנוגע להמוסדות"],[9200220115,"115\nמענות קודש – ה ' תשמ \" ג\nקע ב\nאלול ][\nמענה להרב אברהם ארי ' סטאון שהכניס את ספרו \" the Expounding\nFestivals/Tishrei the on Torah \" שהו \" ל ע \" פ הוראת כ \" ק אדמו \" ר\nשליט \" א אליו . הספר כלל טורים על החגים : ר \" ה , שבת שובה , יוהכ \" פ ,\nחה \" ס , הוש \" ר , שמע \" צ ושמח \" ת ( תשורה סטאון כ \" ה אדר תשס \" א :)\nנת ' ות \" ח ויה \" ר שיפעלו הדברים ועד למעשה בפועל וכו '\nע \" פ דברי נשיאנו – ש \" ק בראשית ה \" ז חותם חודש תשרי ( ואולי מקום\nלצרף עלון בלימוד מזה וזה לצרפו לכל טופס עי \" ז יתוסף בהתענינות\nבש \" ק בראשית .\nאזכיר עה \" צ .\nקע ג\nט \" ז אלול ][\nמענה להשליח ר ' גרשון שוסטרמן על מכתבו ( להנהלת המל \" ח ) – בקשר\nלבית הספר היברו אקדמי חב \" ד שמנהל בעיר לאנג ביטש קליפורניא –\nבו כתב שרוצים להפריד את כל הכתות שיהיו בנים ובנות בנפרד , אלא\nשחברי הנהלת בית הספר חוששים שאם יעשו זאת במהירות יגרום זה\nלהפחתה משמעותית ברישום התלמידים אשר רובם מבתים שאינם\nשומרי תומ \" צ לע \" ע , ולכן מעדיפים להפריד לאט לאט , ושאל כיצד לנהוג\nבזה ( ס ' \" שליחות כהלכ תה \" ע ' 754 :)\nעל פי כל הנ \" ל ישאלו רב מאנ \" ש שי ', ובטח יקיל ככל האפשרי על פי\nשולחן ערוך – כי חומרא בזה עלולה חס ושלום לגרש ילדי בני ישראל\nלחינוך כו '. כמדומה נוהגין להפריד כתה א ' נוספת מדי שנה בשנה ."],[9200220116,"116\nמענות קודש – ה ' תשמ \" ג\nקע ד\nט \" ז אלול ][\nמענה למר איתמר גארמאן על מכתבו – בקשר לדברי כ \" ק אדמו \" ר\nשליט \" א ( ביחידות יום ה ', י \" ז שבט תשמ \" א – שיחות קודש תשמ \" א ח \" ב\nע ' 799 לא ' מנגידי לונדון :)\n\" מ ' האט די הבטחה , אז בשעת מ ' גיט הונדערט פונט אויף צדקה , גיט\nדערנאך דער אויבערשטער פיר הונדערט פונט כנגד זה , פיר מאל אזוי פיל ,\nאון בשעת מ ' גיט א מיליון פונט אויף צדקה , האט מען פון דעם\nאויבערשטן פיר מיליון פונט ! און דא האט איר א מעגליכקייט – איך\nווייס ניט וואס אייער אפעטיט איז , אבער בכל אופן – איז \" ארבע הידות\nיהי ' לכם \" ( אזוי שטייט דער לשון ), און זאל דער אויבערשטער העלפן אז\nמ ' זאל טאן אין דערויף בשמחה ובטוב לבב . א תודה חמה אויב צווישן\nאייערע צדקות וואלט איר געגעבן אויך פאר די מוסדות וואס פירן זיך\nברוח פון כ \" ק מו \" ח אדמו \" ר , הגם אז מצד צדקה קענט איר יוצא זיין\nבמקום אחר , אבער איך וואלט געדארפט זוכן א צווייטן – איז\nפארשפארט מיר עגמת נפש , פארשפארט מיר די טרחא און די דאגה .\"\nכעת , כאשר נקלעו מוסדות ליובאוויטש בלונדון לחובות גדולים , לא\nהסכים הנגיד האמור להיעתר ולתרום , ובכן פנה השליח ר ' נחמן סודאק\nאל הנדיב מר איתמר גארמאן , שהסכים לקחת זאת על עצמו , באופן\nשישקיע בעסק מסויים יחד עם שותפים נוספים , ומהרווחים שיניב\nהעסק יפרישו סכום מסו יים למוסדות ליובאוויטש , באם יאשר כ \" ק\nאדמו \" ר שליט \" א שיהי ' הוא ה \" צווייטער \" ( המדובר ביחידות הנ \" ל )\nשיקח על עצמו את הנ \" ל .\nמענה כ \" ק אדמו \" ר שליט \" א ( קונטרס ועד הנחות בלה \" ק ש \" פ פנחס\nתשע \" ד :)\n[1 על כללות הענין , כתב :]\nויהא בשעטומו \" צ\n[2 בקשר להעסק שפותח , כתב :]\nיברר מתי \" המא רקעט \" בהמדינה מתאים לזה\n[3 בקשר לסכום התרומה , כתב :]\nכל הסכום שתאמר ההנהלה בלונדון בהוספת – 36 לירות"],[9200220117,"117\nמענות קודש – ה ' תשמ \" ג\n[4 על איחוליו , כתב :]\nוכל המברך כו '\nמצו \" ב לצדקה בלונדון\n[ וראה לקמן מענה קע ה . ליקוט מענות קודש תשד \" מ מענה יב . ליקוט\nמענות קודש תשמ \" ו מענות קעה , קעח , רכז , רכח , רכט , רל .]\nקע ה\nועש \" ק תבוא , י \" ז אלול ][\nמענה למר איתמר גארמאן על מכתבו – בהמשך להמענה שקיבל – בו\nכתב שלאחר הדיבור עם אביו ואחיו החליטו שמקבלים על עצמם\nבשמחה את כל הענין , כולל הסכום וכו ' ( קונטרס ועד הנחות בלה \" ק ש \" פ\nפנחס תשע \" ד :)\nנת ' ות \" ח ת \" ח על הבשו \" ט , והבטיחו רז \" ל בכל כיו \" ב – שהקב \" ה עוזר ,\nושיהי ' בשמחה וט \" ל . אזכיר עה \" צ .\nקע ו\nלאחר ש \" פ תבוא , ח \" י אלול ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בהמדובר בהתועדות ש \" פ\nתבוא :\n\" במה שנתבאר בההתוועדות בדברי הספרי ר \" פ תבוא \" אין והי ' אלא\nמיד \", שלדעת הספרי נתחייבו בביכורים תיכף כשנכנסו לארץ לפני\nירושה וישיבה ( ולא כבגמ ' קדושין לז , ב ) ולא כמו שרצו להגי ' בספרי ,\nובשיחה ב ' נתבארו ב ' הדיעות בעבודת האדם , העבודה ד \" מיד \" – בחי '\nמודה אני שהוא בבחי ' דילוג , והעבודה שבמדוה \" ג וע \" פ סדר – לאחר\nירושה וישיבה כו .'\nמצו \" ב צילום מהערת כ \" ק אדמו \" ר שליט \" א בלקו \" ש חי \" ט ס \" ע 608 ( וכן\nמפורש בקיצור בלקו \" ש ח \" ט ע ' 152 הערה 2 .)"],[9200220118,"118\nמענות קודש – ה ' תשמ \" ג\nולהעיר שע \" ד הפי ' בהערה דמיד תבוא אל הארץ מפורש גם בזית רענן\nמהמג \" א ) לילקוט ר \" פ תבוא ( וכ ' שם ב ' פירושים \" פי ' שמיד יבואו לארץ ,(\nוב \" א פי ' מיד לאחר ירושה וישיבה \") ותולדות אדם לספרי ר \" פ תבוא ,\nועד \" ז מפרש בזית רענן שם את ההמשך בספרי וילקוט \" עשה מצוה\nהאמורה בענין שבשכרה תכנס לארץ \" – פי '\" לאחר ירושה וישיבה תעשה\nמצוה זו שהרי בשכרה תכנס לארץ פי ' בשבילה .\"\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תפג :)\"\n[1 ] על מה שכתבו \" שלדעת הספרי נתחייבו בביכורים תיכף כשנכנסו\nלארץ לפני ירושה וישיבה \", כתב :\n(1 ) לדעת – כמה גדולי ישראל ( ) שמפרשים כן\n[2 על מה שכתבו : \" מצו \" ב צילום . . לקו \" ש חי \" ט . . לקו \" ש ח \" ט \", כתב :]\nיוסיפו בהערה – השמטה ציון [ מצו \" ב צילום . . הערה 2 ])\n[3 ] על מה שכתבו : \" ולהעיר שע \" ד הפי ' בהערה דמיד תבוא אל הארץ\nמפורש גם בזית רענן ( מהמג \" א ) לילקוט ר \" פ תבוא . . ותולדות אדם\nלספרי ר \" פ תבוא \", כתב :\nאמרתי וכ \" פ שרצונם שכל הפי ' יהיו דוקא בשיטה ופי ' אחד א \" א היא\nקע ז\nי \" ט אלול ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א למסור למר מנחם בגין\nבעקבות הודעתו בישיבת הממשלה דיום א ', י \" ט אלול אשר בכוונתו\nלהתפטר מתפקידו כראש הממשלה ( מצילום כתי \" ק – תשורה לאזאר\nט \" ו תמוז תשע \" ז :)\nלמרות חילוקי דעות בענינים עיקרים שאיני יכול להסכים עליהם –\nלדעתי , ברור – שהמצב הפנימי והבין לאומי דבנ \" י באה \" ק דורש\nומכריח שכבודו י משיך בכהונתו כל משך התקופה שנבחר לכהן בה ,\nואפילו אם זהו קשור באי כבוד , במאמצים בבריאות וכו '"],[9200220119,"119\nמענות קודש – ה ' תשמ \" ג\nכי מצב הנ \" ל מכריח שלילה ככל האפשרי דכל בלבול נוסף ומחלוקת\nנוספת וחיפוש חסרונות ושגיאות דאיש ברעהו ומפלגה ברעותה , שלילת\nהכנסת ( א רײ נשלעֶפן ) דאו \" ה בהחלטות הנוגעות באופן הכי רציני\nבקיום העם היושב בציון – שכ \" ז מוכרח לבוא בתעמולת בחירות , שלכן\nמוכרחת דחייתן ככל האפשרי והנעשה בכיונים האמורים ע \" ע ע \" י\nאישים שונים – כבר גרמו נזק רב שאינו שווה כלל בהריוח המפוקפק\nשמקווים לקבל עי \" ז .\nשתקתי ע \" ע כי מי אני להתערב מרחוק וכו ', ועוד ועיקר כי כ \" כ ברור\nהכרח כהונתו ככל האפשרי לדעתי ברורה שהי ' ברור בעיני שכל\nהדיבורים עד \" ז הם בתור לחץ בכדי להשיג הסכם שר או מפלגה\nבענינים מסוימים\nאבל בהִוָדעי הודעה הרשמית של ישיבת הממשלה דהיום ( יום א )\nנתעוררה היראה שאולי החששא רעאלית\nורואה אני עצמי מוכרח – לחוו \" ד בענין שלא שאלוני כלל ושאיני בטוח\nאיך תתקבל ומה תהי ' התגובה להתערבותי בכ \" ז ,\nכי אין כ \" ז (\" כבודי \" וכו )' –\nבערך חששות הנ \" ל שלדעתי מהוות סכנה –\nואף שהקב \" ה שמר וישמור עם קדושו ואה \" ק –\nנצטוונו לעשות כל האפשרי לבטחון וכו ' בדרך הטבע .\nוהשם ירפאהו ברפו \" ש ויאמצהו לנצל תפקידו הכי האחראי לטוב העם\nוהארץ ותורתנו – שחד הם .\nבכבוד בבקשת סליחה בהוקרה ובברכה\nקע ח\nכ \" ף אלול ][\nמענה להשליח ר ' אברהם קארף בקשר לפתיחת בית חב \" ד חדש במיאמי\nמהעתקה . המענה מתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי '(\nוזכות הרבים תלוי ' בו :)\n1 ) יבקשו פס \" ד בכתב מרב מומחה שמותר לתת להם ממון באופן כזה"],[9200220120,"120\nמענות קודש – ה ' תשמ \" ג\n2 ) באם הנ \" ל בסדר אסיפת עסקני אנ \" ש שי ' שבמקום 1 ) האם בזה\nהשגת גבול 2 הכדאי וכו ')\nאזכיר עה \" צ\nלהחזיר המצו \" ב\nקע ט\nכ \" א אלול ][\nמענה לר ' לוי גאלדשטיין ( מהעתקה . המענה מתפרסם בזה לראשונה\nבאדיבות הנמען שי ' וזכות הרבים תלוי ' בו :)\n[1 ] במכתבו כתב : \" בעוד איזה ימים מתחיל שוב סדר הלימודים ביתות \" ל\nאשען פ ' קוויי , בה הנני מלמד בכתה א '. והנה בננו שניאור זלמן שיחי ,'\nעומד לעבור לכתה א ', ושאלתנו היא , האם נכון שילמוד אצלי או שילמוד\nאצל הר ' יוסף ב \" צ שי ' רייצעס – המלמד של כתה א ' האחרת .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nכעצת ההנהלה כמפורסם\n[2 ] במכתבו כתב : \" היום נתמלאו לי ל \" א שנים , ומצו \" ב פ \" נ ל \" ב\nשקלים .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" נתמלאו לי ל \" א שנים ,\"\nוכתב :\nמנהגי\nאזכיר עה \" צ"],[9200220121,"121\nמענות קודש – ה ' תשמ \" ג\nקפ\nקייץ ][\nמענה לר ' אהרן חיטריק שכתב :\n\" כרך מאמרי אדהצ \" צ על מארז \" ל וענינים סודר בדפוס , וצריכים להגיה\nאותם .\nבענין כרך זה יש אצלי שאלה :\nהאם להדפיס עוה \" פ המאמרים שנדפסו במקום אחר . לדוגמא : ד \" ה ג '\nבחי ' אדם – הנדפס באוה \" ת בלק . ד \" ה לה \" ע הברכות – נדפס באוה \" ת\nבראשית . ד \" ה ר ' בנאה – נדפס שם .\nמצורף פה רשימה מהמאמרים שלא נדפסו , ורשימה מהמאמרים\nשנדפסו .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה גראס ח ' תמוז\nתשע \" ט :)\n[1 ] על מה שכתב : \"\" כרך מאמרי אדהצ \" צ על מארז \" ל וענינים סודר\nבדפוס \", כתב :\nובודאי ביום הולדת אדהצ \" צ ][ יוכלו רבים וגם באה \" ק ללמוד בהספר\n[2 ] סימן בעיגול את מה שכתב : \" האם להדפיס עוה \" פ המאמרים שנדפסו\nבמקום אחר \", וכתב :\nהרי רבים הם – ולכן רק לציין בכרך הבע \" ל שמאמר פ ' נדפס בס ' פ '\n( אולי בהוספת מספר הפרקים וכיו \" ב )\nקפ א\nקייץ ][\nמענה להורים שכתבו ע \" ד הרטבת לילה אצל ילדם , וכתבו אשר לרופאים\nאין תרופה לזה ( לקו \" ש חל \" ו ע ' 323 ס ' \" היכל מנחם \" ח \" א ע ' קצא :).\nעל מה שכתבו : \" לרופאים אין תרופה לזה \", כתב :\n!?"],[9200220122,"122\nמענות קודש – ה ' תשמ \" ג\nכמפורסם מיעצים : מנוה \" ח דהנ \" ל ככל האפשרי , היסח דעתם דהנ \" ל\nבהנ \" ל ( ופשיטא שלא להגזימו .)\nמיעוט שתי ' סמוך לשינה וכו .'\nאזכיר עה \" צ .\nקפ ב\nקייץ ][\nמענה לר ' שלום דובער לוין שכתב : \" מצו \" ב המבוא לכרך החמישי\n[ דאגרות - קודש אדמו \" ר מהריי \" ץ ], ובסופו – ע \" ד אגרות ארכיון כ \" ק\nאדמו \" ר מוהריי \" צ נ \" ע – שנמסרו ע \" י הרח \" ל שי '\" ( קובץ \" עבודת הקודש\nאצל הרבי \" ע ' מו :)\nמפני תוכן , כדאי שידבר עד \" ז עם הרח \" ל שי ]'[ וכו ' ובפרטיות .\nקפ ג\nקייץ ][\nמענה להשליח ר ' יוסף יצחק וולסוב שכתב שהציעו לו לשמש כראש\nהמועצה - הדתית בעירו רמת ישי בנוסף לתפקידו כרב העיר , ושאל האם\nמתאים הדבר א חסידישער דערהער \" סיון תשע \" ט , והעתקה :)(\"\nיבדוק אם יש בהנ \" ל תועלת להבית חב \" ד\nקפ ד\nקייץ ][\nמענה להשליח ר ' אברהם קארף על מכתבו בקשר לתכנית מסויימת\n( מהעתקה . המענה מתפרסם בה לראשונה באדיבות א ' מאנ \" ש שי ' וזכות\nהרבים תלוי ' בו :)\nנתקבל ות \" ח\nכמדומה חשש למחלוקת וכו ' – ויברר ויעשה בהתאם\nאזכיעה \" צ"],[9200220123,"123\nמענות קודש – ה ' תשמ \" ג\nקפ ה\nתשמ \" ג ][\nמענה להרב משה וואלפסאן ששאל האם כדאי להו \" ל חלק שני מספרו\n\" אמונת עתיך \", וביקש ברכה שלא יזיק לו ח \" ו ( מצילום כתי \" ק – ס '\nמאוצר המלך \" ח \" א ע '\" 376 והעתקה , באדיבות א ' מאנ \" ש שי :)'.\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" להוציא חלק שני ,\"\nוציין : (1 )\nעל מה שכתב \" שלא יזיק לי ח \" ו \", כתב :\nאדרבא ואדרבא – יועיל ויועיל (2 )\nלהו \" ל , ומה טוב בהקדם כי רואים במוחש איך שהלעומ \" ז מתנכל\nבאופנים ובדרכים משונים להפיץ שנאת ישראל ר \" ל ,\nושומו שמים על שכו \" כ נפלו ברשתו ועושים מלאכתו וכו ' , אף שיודעים\nשהגלות הזה הוא מפני שנאת חנם וכו '\n[ ואין לדבר , ובפרט להאריך , בהיפך טובתם של ישראל , כ \" א המוכרח\nביותר ]\nוכל דיבור ובפרט הנדפס – שתוכנו מביא לאהבת השם התורה ישראל\n( כולל – כפס \" ד רז \" ל – אעפ שחטא ישראל הוא ) – שחד הוא\nה \" ז ענין שהזמ \" ג ודורש ומכריח [ ובכהנ \" ל – אפילו על הספק צריך\nלהו \" ל ובפרט שלדעתי זהו ודאי ]\nאזכיר עה \" צ לכהנ \" ל .\nמצו \" ב לצדקה באה \" ק\nקפ ו\nתשמ \" ג ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א למסור לועד רבני חב \" ד\nבאה \" ק – (1 ) בקשר למוסד חב \" די מסויים שכתבו על ה \" בלאנק \" שלהם\nשהוא \" בנשיאות כ \" ק אדמו \" ר שליט \" א ;\" ( 2 ) בקשר למכתבי כ \" ק\nאדמו \" ר שליט \" א ( מכתב ג ' שבט תשמ \" ג – ס ' \" מקדש מלך \" ח \" א ע ' 208-\n9 . מכתב כ \" ד אדר תשמ \" ג – שם ע ' 60-1 ) ע \" ד שלילת \" אריכות הזמן של"],[9200220124,"124\nמענות קודש – ה ' תשמ \" ג\nכל הד \" ת או סכסוכים וחילוקי דיעות הבאים לפניהם – אריכות\nמהתחלת הדו \" ד , והשקו \" ט , ואריכות הכי גדולה עד להוצאת הוראה\nברורה בפס \" ד \" ( מצילום כתי \" ק – ס ' \" מאוצר המלך \" ח \" ג ע ' 4 ס '.\nמקדש מלך \" ח \" א ע '\" 76 בהערה . והעתקה :)\n1 כמפורסם אין כותבים זה במוסדות חדשים\nוישמידו תומ \" י כל הנדפס בנוסח זה\n2 ) כתבתי מלפני כו \" כ זמן להב \" ד שמוכרחת הזריזות בהד \" ת וכו '\nובקשתי לאשר קבלת מכתבי זה\nוע \" ע לא אושר\nוכנראה פשיטא שלא נעשה דבר וד \" ל\nלטלפן . מהיר\nקפ ז\nתשמ \" ג ][\nמענה לר ' חיים שמריהו גורארי ' שכתב : \" אם יש לי תקוה לחיות ולזכות\nלבוא לשנה הבע \" ל תשמ \" ד . . אזי אגמור עם מר פינסאן לקנות המצות\nלפני שבת בראשית \" ( מצילום כתי \" ק – תשורה קליין י \" ז סיון תשס \" ו :)\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" תקוה \", וכתב :\nב אם ][ ח \" ו תתעכב ביאת המשיח\nלאחרי כל השטורם שלי ע \" ד ביאת משיח – האב איך אויסגעפירט\nששואל כנ \" ל !?"],[9200220125,"125\nמענות קודש – ה ' תשמ \" ג\nקפ ח\nתשמ \" ג ][\nמענה להשליח הרב יצחק דוד גראנער ( לקו \" ש חכ \" ד ע ' 526 , ומהעתקת\nהמזכיר :)\nעכ \" פ בעת שמחה גדולה ( עיין ד \" ה שמח תשמח וכיו \" ב ) הי ' צריך לפעול\nעליו שיתחיל עכ \" פ – בבשורה משמחת ו \" אפילו \" בענינים הכלליים ,\nואח \" כ \" ימסור \" הכתיבה להמ \" ש שלו .\nדרך אגב \"\" – מה האָט זיך אויפגעטאן לטוב – ע \" י המ \" ש הנ \" ל במשך\nהשנים הרבות ?\nולאחרי שראה בעיני בשר – שכל מ \" ש הנ \" ל לא נתקיימו כלל וכלל –\nקלא מערט ער זיך בה !\nאזכיר עה \" צ לכהנ \" ל ויבש \" ט .\nקפ ט\nתשמ \" ג ][\nמענה להשליח ר ' זלמן אהרן גראסבוים ( ס ' \" שליחות כהלכתה \" ע ' 392 :)\n[1 ] במכתבו כתב ע \" ד בית חב \" ד שנבנה בשנת תשל \" ט בצפון טורונטו , על\nסמך הבטחת גביר מסויים שישלם הסכום עד חורף תשמ \" ג . לפועל ,\nכשהגיע הזמן השתמט הגביר מלשלם בכל פעם שדיבר עמו , ובכן כתב\nשחושב אולי לבקש מהתורם לסגת באופן רשמי מהבטחתו , ויהי ' רשמי\nשאינו נותן הממון ויח נכו הבנין בלעדיו .\nמענה כ \" ק אדמו \" ר שליט \" א :\nנתקבל ות \" ח , כבר אמרתי ( וכמה פעמים ) שאפילו עסקן הכי גדול\nמוכרח שיתייעץ עם עוד עסקנים ובפרט בשאלה מסובכת .\nבטח יסבירוהו אז פון איינרייסן פארדינט מען ניט . ואז ההסברה לבקש\nהודעה רשמית מ .[ ]. אז ער זאגט זיך אפ מהתחייבות שלו , ושהנהלת\nחב \" ד בעיר תבקש זאת הרי זה חידוש נפלא .\n[2 על התיבות : \" כל פעם שאני מבקש הבטחתו הוא דוחה אותי \", כתב :]\nאיזה מהבעלי - בתים העשירים דיברו אתו על דבר זה ?"],[9200220126,"126\nמענות קודש – ה ' תשמ \" ג\nקצ\nתשמ \" ג ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א לר ' שלום דובער לוין –\nבצירוף ל \" ביכל \" שנתקבל שנרשם עליו ששייך לר ' אהרן זאב שו \" ב\nדפלעשניץ (\" כפר חב \" ד \" גליון 100 :)\nלשאול הרח \" ל שי ' אולי יודע אודותו\nקצא\nתשמ \" ג ][\nמענה לר ' שלום דובער לוין על מכתבו – בהמשך להמענה שקיבל – בו\nכתב את אשר בירר בנוגע לר ' אהרן זאב שו \" ב דפלעשניץ ( קובץ \" עבודת\nהקודש אצל הרבי \" ע ' קטו :)\nלצרף להביכעל .\nקצב\nתשמ \" ג ][\nמענה להנהלת \" צבאות השם \" שכתבו ע \" ד הצעה לערוך \" קונצרט \"\nלילדים בבנין של אחת האוניברסיטאות (\" התקשרות \" גליון נח :)\nצע \" ג אם כדאי להזמין ולקבל ילדים בקאלעדש וכיו \" ב , וק \" ל .\nקצ ג\nתשמ \" ג ][\nמענה להרב ברוך אלכסנדר זושא ווינער שכתב שחושב לכתוב הערות\nוציונים על הל ' שחיטה שבשו \" ע אדה \" ז ( תשורה סלבטיצקי כ \" ב אלול\nתשס \" א :)\nבטח ראה אלו שכבר הו \" ל – להרב ביסטריצקי שי '"],[9200220127,"127\nמענות קודש – ה ' תשמ \" ג\nקצ ד\nתשמ \" ג ][\nמענה להרב ברוך אלכסנדר זושא ווינער שהכניס דוגמא של ביאורים\nוהערות על חלק מסימן אחד מהל ' שחיטה שבשו \" ע אדה \" ז , ושאל האם\nכדאי להמשיך בזה ( תשורה סלבטיצקי כ \" ב אלול תשס \" א :)\nכחוו \" ד רבני אנ \" ש שי '\nבאם שקולים הם – יו \" ל\nקצ ה\nתשמ \" ג ][\nמענה להשליח ר ' יוסף דוד ווייטמאן בקשר לנסיעתו יחד עם זוגתו לברית\nהמועצות עבור הימים נוראים ( תשורה ווייטמאן י \" א אלול תשס \" ו :)\nכ \" ק אדמו \" ר שליט \" א שלח 18 דולר , וכתב :\nלחלק שם בכסף המדינה , ולהחליף באופן רשמי .\nקצ ו\nתשמ \" ג ][\nמענה להשליח ר ' ארי ' ליב קפלן שכתב ע \" ד רעיון שהועלה שקרית חב \" ד\nבצפת עיה \" ק תקבל מספר בניני מגורים בצד השני של העיר שמתחילים\nלבנות ( תשורה קפלן כ \" ה טבת תשס \" ט :)\n[1 במכתבו כתב שלדעתו \" א \" א לפצל את הקרי ' לשני קצות העיר .\"]\nמענה כ \" ק אדמו \" ר שליט \" א :\nכפשוט .\n[2 ] במכתבו שאל האם להמשיך בכיוון של בני ' עצמאית אף שמשרד\nהשיכון אינו מעוניין להשתתף בפיתוח הקרקע .\nמענה כ \" ק אדמו \" ר שליט \" א :\nכעצת ידידים מבינים באה \" ק ."],[9200220128,"128\nמענות קודש – ה ' תשמ \" ג\nקצ ז\nתשמ \" ג ][\nמענה להשליח ר ' אברהם אלטיין על מכתבו בקשר למקום לימודי בתו\nהמתקרבת לגיל 10 , שרוצים לשלוח אותה מעירם וויניפעג ללמוד בבית\nהספר \" בית רבקה \" במאנטרעאל , ושתתתאכסן שם בבית הורי ' זקני .'\nבמכתבו כתב : \" והננו לשאול חוו \" ד כ \" ק אדמו \" ר שליט \" א האם נכון\nהדבר שתלך בשנה זו למ רחוק ללמוד בבית - רבקה , ואם נכון הדבר\nמבקשים אנו ברכת כ \" ק אדמו \" ר שליט \" א להצלחה בזה \" ( תשורה\nאלטיין ט \" ו סיון תשע \" ח :)\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" האם \", ותיבת \" למרחוק \", וסימן\nבעיגול את התיבות \" ברכת כ \" ק אדמו \" ר שליט \" א להצלחה בזה \", וכתב :\nאזעה \" צ .\nקצ ח\nתשמ \" ג ][\nמענה לר ' נתן קלמן פעליג שביקש ברכה עבור בנו חיים שלמה שיום\nהולדתו יחול בקרוב ( קטלוג התמונות של ספריית אגו \" ח מספר 3874 :)\nמנהגי\nקצ ט\nתשמ \" ג ][\nמענה להנהלת ה \" חדר \" באמסטרדם על תמונות מביקורו של פרופסור\nמסויים שם ( קטלוג התמונות של ספריית אגו \" ח מספר 7950 :)\n[1 סימן בעיגול תיבת \" פרופסר \" שבכיתוב שעל המעטפה , וכתב :]\n?\n[2 בקשר לתמונות , כתב :]\nלהחזיר"],[9200220129,"129\nמענות קודש – ה ' תשמ \" ג\nר\nתשמ \" ג ][\nמענה לא ' השלוחים על מכתבו בקשר לסכסוך עם שליח אחר במקומו\nמהעתקה . המענה מתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי '(\nוזכות הרבים תלוי ' בו :)\nכמענתי כ \" פ כהוראת הב \" ד דאנ \" ש שי ' ( דכאן ) שעסקו ע \" ע בהמוסדות\nהנ \" ל\nרא\nתשמ \" ג ][\nמענה להרב יעקב יהודה העכט שכתב :\n\" הרב . . [ מראשי ארגון \" מרכז הרבנים \"] צועק בשבועות האחרונות\nאודות המגפה של נישואי תערובות ר \" ל , ומדייק שלא הי ' ע \" ע שום מוסד\nשיעשה דבר ממשי בנוגע זה , וגם יש לו טענות על האגודת הרבנים ,\nוהעיקר על הרעפארמער ולא ח \" ו על הקאנסערוואטיווער , וגם אצל\nהרעפארמער רק בנוגע נישואי תערובות ולא ח \" ו נגד העוולות האחרים\nשלהם ( שבאמת אני לא מבין אותו ) אבל מה שאני רוצה לדעת איפו הי '\nכל החמשה ושלשים שנה שאנו צועקים געוואלד בנוגע להמגפה הזאת –\nברדיא , בהעיתונים , ובכל מקום וזמן , שזהו לא דבר שהי ' במסתרים אלא\nבפומבי וכל אחד ידע מזה , איפו הי ' שלא נשמע ממנו אף \" קרעכץ \" על\nהצרה הזו ועכשיו הוא בא כצדיק הדור , שרוצה לתקן כל העבירות\nשבעולם והוא יביא ישועה והצלה לכלל ישראל .\nשאלתי האם זה ענין עבורי לעשות \" געשעפט \" מזה עמו , או להיות שב\nואל תעשה ואם יתקן מה , תבוא עליו ברכה , או לכה \" פ לעשות מחאה –\nמדוע לא יכיר עבודתינו שב \" ה הצליח בעזהשי \" ת להציל עשיריות\nמישראל מהאסון הזה , וגם עבודתינו בענין של De-Programing , שידוע\nלכ \" ק אד \" ש וכו ', ואנחנו עדיין עומדים בראש בזה . ואנא לייעצני כ \" ק\nאד \" ש בעצתו הק .\"'\nמענה כ \" ק אדמו \" ר שליט \" א ( מהעתקה . המענה מתפרסם בזה לראשונה\nבאדיבות מערכת הספר \" שליחות כהלכתה \" וזכות הרבים תלוי ' בהם :)\nבאם יתערב באיזה פרט מהנ \" ל , הר \" ז התערבות בין הנ \" ל וארגונו ,\nואגודת הרבנים ."],[9200220130,"130\nמענות קודש – ה ' תשמ \" ג\nלזכות\nכ \" ק אדמו \" ר שליט \" א"],[9200230001,"ליקוט\nיום הבהיר י ” ד כסלו\nפראנקפורט , גרמני '\nיום הבהיר י “ א ניסן\nמענות קודש\n• •\n• ה ' תש ” תשד נ \" מ •"],[9200230002,""],[9200230003,"ב \" ה .\nפתח דבר\nלקראת יום הבהיר כ \" ח סיון הבעל \" ט , התחלת שנת השמונים ליום בו\nניצלו כ \" ק אדמו \" ר שליט \" א והרבנית הצדקנית נ \" ע מעמק הבכא האירופאי\nוהגיעו צלחה לארצות הברית ,\nהננו מוציאים לאור בזה ליקוט \" מענות קודש – ה ' תשד \" מ \", הכולל את\nמענות קודש כ \" ק אדמו \" ר שליט \" א שכתבם במשך שנת ה ' דשת \" מ .\n*\n\" פון איין תורת נשיא דורנו גייט מען צו נאך א תורת נשיא דורנו \" ( שיחת\nש \" פ תזו \" מ תנש \" א – בלתי מוגה ). כמה \" חלקים \" ישנם לתורת נשיא דורנו\nכ \" ק אדמו \" ר שליט \" א .\nבין החלקים השונים בתורת כ \" ק אדמו \" ר שליט \" א , \" חלק \" מיוחד ישנו ,\nוהוא : \" מענות קודש \", הם אלפי המענות אשר כתב כ \" ק אדמו \" ר שליט \" א\nבמענה להשואלים :\nהחל מהשנים הראשונות לנשיאות כ \" ק אדמו \" ר שליט \" א , הנה לצד\nה \" אגרות \" ששלח להפונים אליו , נענו רבים מהמכתבים ע \" י כ \" ק אדמו \" ר\nשליט \" א בכתב יד קדשו על מכתב השואל , כאשר לאחר מכן נמסרים\nהדברים להנמען .\nבעוד ובשנים הראשונות הי ' זה באופן מצומצם ( בעיקר – לאלו הנמצאים\nבסמיכות מקום ), הנה ככל שעברו השנים הלך הדבר והתרחב יותר ויותר , עד\nשהי ' לאופן העיקרי בו עונה כ \" ק אדמו \" ר שליט \" א להכותבים אליו .\nעל אף היותו של \" חלק \" זה בתורת כ \" ק אדמו \" ר שליט \" א – חלק עיקרי ,\nנדמה , כי חלק זה אין מוסבת תשומת הלב אליו ככל הדרוש .\nטעם העיקרי לדבר הוא , ככל הנראה , כיון שמפוזרים מענות הקודש על\nפני כמה וכמה מקומות שונים , ועד עתה לא נמצא להם גואל שילקטם\nלפונדק אחד .\nצורך זה באנו למלאות בליקוטים אלו . קד מו לליקוט שלפנינ ו \" ליקוט\nמענות קודש – תשמ \" ה \",\" ליקוט מענות קודש – תשמ \" ו \", \" ליקוט מענות\nקודש – תשמ \" ז \" ,\" ליקוט מענות קודש – תשמ \" ח \" , \" ליקוט מענות קודש –\nתשמ \" ט ,\" \" ליקוט מענות קודש – תש \" נ ,\" \" ליקוט מענות קודש – ת נש \" א ,\"\nו \" ליקוט מענות קודש – תש נ \" ב ,\""],[9200230004,"4\nמענות קודש – ה ' תשד \" מ\nובתכניתנו להוציא ליקוטים נוספים מסוג זה , להרוות צמאון אנ \" ש\nוהתמימים .\n*\nתודתנו נתונה לכל אלו שהואילו למסור את מענות הקודש שבידם\nלפרסום בליקוט זה , וזכות הרבים תלוי ' בהם .\nבמיוחד תודתנו נתונה למערכת אפליקציית \" מפתח \" על עזרתם .\nוכאן המקום לבקש בבקשה כפולה ומכופלת מכל מי שיש בידו מענות\nקודש שטרם פורסמו , למוסרם לידי המערכת על מנת לפרסמם בליקוטים\nיבואו , ויהיו בזה ממזכי הרבים .\nכתובת הדוא \" ל של המערכת : likkutkatyak@gmail.com .\n*\nויהי רצון שיחוס וירחם השי \" ת עלינו , ונזכה להתראות עם כ \" ק אדמו \" ר\nשליט \" א תיכף ומיד ממש , ותחזינה עינינו בהתפשטות מלכותו על כל באי\nעולם , תיכף ומיד ממש !\nמערכת \" ליקוט כתבי יד קודש \"\nערב יום הבהיר כ \" ח סיון , ה ' תש \" פ\nשבעים שנה לנשיאות כ \" ק אדמו \" ר שליט \" א\nברוקלין , נ . י ."],[9200230005,"5\nמענות קודש – ה ' תשד \" מ\nצילו מי כתי \" ק\n– פרסום ראשון –\nלקמן מענה קה"],[9200230006,"6\nמענות קודש – ה ' תשד \" מ\nלקמן מענה קנו\nלקמן מענה קסד"],[9200230007,"7\nמענות קודש – ה ' תשד \" מ\nלקמן מענה ק פא"],[9200230008,"8\nמענות קודש – ה ' תשד \" מ"],[9200230009,"9\nמענות קודש – ה ' תשד \" מ\nלקמן מענה רנב"],[9200230010,"10\nמענות קודש – ה ' תשד \" מ\nלקמן מענה רפ"],[9200230011,"11\nמענות קודש – ה ' תשד \" מ\nמענות קוד ש – ה ' תשד \" מ\nא\nז ' תשרי ][\nמענה על פתק שכתב המזכיר ריל \" ג , בו כתב : \" הרב שאר ישוב הכהן כהן\nביקש לשאול : בקשר לספרו של הרב חיים שלום ע \" ה הלוי סגל על פרש \" י\nקיבל הוראה להדפיס הפירוש ביחד עם החומש . כעת מבקשים ב \" ב שי '\nשל הרב סגל – היות שהדפסת הנ \" ל תשהה זמן רב , ורוצים להדפיס ספרו\nעוד במשך שנת האבילות שלו , ההצעה להדפיס כעת הפירוש לבד ,\nולהמשיך גם בהדפסת הפירוש עם החומש . הוא יסכים לזה באם יקבל\nהסכמת כ \" ק אדמו \" ר שליט \" א \" ( מצילום כתי \" ק – תשורה אראנאוו י \" ב\nסיון תשס \" ד :)\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות \" להדפיס ספרו עוד במשך\nשנת האבילות שלו , ההצעה להדפיס כעת הפירוש לבד ולהמשיך גם\nבהדפסת הפירוש עם החומש \", וסימן בעיגול תיבת \" הסכמת \", וכתב :\nונכון ומתאים מאד ( 3 )\nובפרט שעי \" ז יתרבו בהקדם לומדי פירש \" י וכו '\nשעשה ובהצלחה וכו ' תוה \" ק \" בהמצאו גו ' קרוב \" בהבנת פשוטו ש \" מ\nשעי \" ז הכניסה לתוך\nר אש של כאו \" א מ )(\nש בטי\nי שראל"],[9200230012,"12\nמענות קודש – ה ' תשד \" מ\nב\nתשרי ][\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – ס ' \" מאוצר המלך \" ח \" ג\nע ' 30 ס ' \" מקדש מלך \" ח \" א ע '. 156 :)\n1 ) מפורסמת דעתי שמקום לימודי ת ' הוא כעצת הנהלה אצלה למד\nבאחרונה\n2 ) שכל העושה בהגדלת המחלוקת ( גם ע \" י גירוי ושיסוי אחרים ) ה \" ז\nלוחם בחב \" ד\nאזכיר עה \" צ\nג\nתשרי ][\nמענה לר ' שלום דובער לוין על מכתבו בו הזכיר את ר ' יהושע מונדשיין\nבנוגע לנושא מסויים ( מצילום כתי \" ק – תשורה מונדשיין י \" ז כסלו\nתשס \" ח . ליקוט כתי \" ק יום הבהיר י \" א ניסן ע ' 35 :)\nלפני כמה שנים אמר שמתחיל להתעסק בנוגע לשו \" ע אדה \" ז ( ע \" ד\nשעשה בנוגע לתניא – וארך כו \" כ שנים , והיו צריכים לזרזו ובדברים\nחריפים וכו ' וכו ' )\n2 ) יברר – באם גם בנוגע לשו \" ע תכניתו לאויו \" ש טובות – יתחילו בזה\nתומ \" י המתעסקים בכיו \" ב בהספרי ' דכאן – באופן שיהי ' לאחר\nהכריכה בפו \" מ לי \" א ניסן תשד \" מ ומה טוב לפורים\nוראה לקמן מענות :[ ד , ע ה , קל ו , קל ז , קל ח , קל ט , קס ו , קפ ד , קפ ה , קצ ג ,\nקצ ד , קצ ה , ר א , ר ב .]"],[9200230013,"13\nמענות קודש – ה ' תשד \" מ\nד\nתשרי ][\nמענה לר ' שלום דובער לוין שהכניס את מכתב ר ' יהושע מונדשיין בקשר\nלספר על שו \" ע אדה \" ז ( מצילום כתי \" ק – תשורה מונדשיין י \" ז כסלו\nתשס \" ח :)\n[1 ] במכתבו ( של ר ' שלום דובער לוין ) כתב : \" בקשר לרשימת דפוסי שו \" ע\nאדה \" ז , כתבתי לר \" י שי ' מונדשיין את דברי כ \" ק אד \" ש , וקבלתי היום\nאת תשובתו המצו \" ב .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" תשובתו המצו \" ב ,\"\nוכתב :\nלהחזיר\n[2 ] במכתבו ( של ר ' יהושע מונדשיין , וכן לקמן ) כתב : \" את רישום דפוסי\nהשו \" ע וכו ' סיימתי לפני זמן רב , עבור מפעל הביבליוגרפיה , ולא לחצתי\nעליהם לזרז הבדיקה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(1 ) ה \" ז הדבר שעוררתי ע \" ז\n[3 במכתבו כתב : \" רישום זה היה רק עד הוצאת תש \" כ .\"]\nמענה כ \" ק אדמו \" ר שליט \" א :\n(2 ) לאח \" ז היו בטח רק הוצ ' צילום ( או בהוספות ברורות ) ולכן כדאי\nלהשלים ע \" ע , כיון שלא תדרש חקו \" ד רבות\n[4 ] במכתבו כתב : \" הרשימה היא בהשמטת פרטים ודקדוקים שדורשים\nעוד עבודה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(3 בהשמטה אפ \" ל רק חסרון ( כשמה )) וכל חסרון – ה \" ז חסרון .\n[5 ] במכתבו כתב : \" תקוותי להשי \" ת שיסייעני להשלים העבודה כרצון\nכ \" ק אדמו \" ר שליט \" א .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n(4 ) לפענ \" ד הסיוע ודאי , אבל הבחירה – בידו .\nלשלימות הענין – כדאי שתתוסף בסופו רשימה ( קצרה , כדי שלא לעכב\nההו \" ל ) דס ' השקו \" ט בשו \" ע אדה \" ז , ועאכו \" כ – דעיקרם בזה ."],[9200230014,"14\nמענות קודש – ה ' תשד \" מ\nה\nתשרי ][\nמענה למרכז \" צעירי אגודת חב \" ד \" באה \" ק על דו \" ח מתכנית מבצע ד '\nמינים ברחבי אה \" ק (\" כפר חב \" ד \" גליון 114 :)\nת \" ח ת \" ח על הבשורות הטובות\nויהי רצון שיהי ' זמן שמחתנו בכל ולהמשיך בכל השנה .\nאזכיר על הציון\nו\nתשרי ][\nמענה להנהלת \" בית רבקה \" בכפר חב \" ד ב ' על שאלתם – בהמשך לפטירת\nחבר ההנהלה הרב נחום טרבניק ז \" ל – את מי למנות לחבר הנהלה\nבמקומו ( ס ' \" מקדש מלך \" ח \" ב ע ' 306 והעתקה :),\nמיניתי את הר ' טרבניק ז \" ל בתור מרא דאתרא לבית רבקה , שמזה מובן\nשעתה צ \" ל הרב מרא דאתרא דעתה .\nז\nתחלת תשד \" מ ][\nמענה לר ' שלום דובער לוין על מכתבו – בהמשך למה שכתב כ \" ק אדמו \" ר\nשליט \" א על עלי - ההגהה דספר \" שערי תשובה \" אשר לאדמו \" ר האמצעי ,\nשבו , ב \" רשימת דפוסי הספר \", דן בכמה פרטים לא ברורים בהוצאות\nהראשונות , וציין לכמה ספרים ביבליוגרפיים : \" פשוט שכל השקו \" ט\nוהזכרת עלי עין וכיו \" ב לא יודפסו ביחד עם הס ' דאדהאמ \" צ , כ \" א רק\nהמסקנא המוכרחת והנ \" ל במכ ' ביגדיל תורה \". במכתבו שאל האם רק\nלציין לספר שדן בנושא , בלי שקו \" ט ( קובץ \" עבודת הקודש אצל הרבי \"\nע ' צט :)\nאין מקום להזכרת ס ' ביבליוגרפיא ולשקו \" ט בזה – בס ' אדהאמ \" צ !\nוירשום רק : בהשער נזכר \" שקלאוו \", אבל חותם הביקורת הוא מהרב\nדקאפוסט .\nוכל השקו \" ט , באם כבר ברורה אצלו עכ \" פ , ידפיסה ביגד \" ת ."],[9200230015,"15\nמענות קודש – ה ' תשד \" מ\nח\nתחלת תשד \" מ ][\nמענה להנהלת \" נשי ובנות חב \" ד \" בקשר לתכנית מסויימת ( תשורה\nוויינפעלד כ \" ח סיון תשע \" ח והעתקה :),\nויהי רצון שיהי ' בהצלחה רבה\nאזכיר על הציון\nט\nתחלת תשד \" מ ][\nמענה להנהלת \" נשי ובנות חב \" ד \" בקשר לתכנית מסויימת ( תשורה\nוויינפעלד כ \" ח סיון תשע \" ח והעתקה :),\nבאם תהיינה הפעולות והמרץ כמו עד עתה אין לקחת על עצמן הנ \" ל או\nכיו \" ב . באם יתוסף בהנ \" ל כדרוש בנוגע לפועל ממש בכוחן להביא כל\nהנ \" ל לפועל ועוד יותר ובלי קשיים יתרים אזכיר על הציון על כל הנ \" ל ..\nי\nתחלת תשד \" מ ][\nמענה להנהלת \" נשי ובנות חב \" ד \" בקשר לתכנית מסויימת ( תשורה\nוויינפעלד כ \" ח סיון תשע \" ח והעתקה :),\nשייך להחליט אך ע \" י ההנהלה עצמה ואז זה גם יחייב וימריץ אותן וכו '\nוק \" ל .\nיא\nער \" ח מרחשון ][\nמענה לא ' על מכתבו אותו פתח בתיבות : \" מה עלי לעשות \" ( מצילום\nכתי \" ק – תשורה ניסילעוויטש י \" ט שבט תשע \" א :)\n– כפשוט , כמש \" כ בשו \" ע\nפננ"],[9200230016,"16\nמענות קודש – ה ' תשד \" מ\nיב\nער \" ח מרחשון ][\nממענה להשליח ר ' נחמן סודאק ( קונטרס ועד הנחות בלה \" ק ש \" פ פנחס\nתשע \" ד :)\nההמשך דגאָרמאַן שי ?'\nוראה ליקוט מענות קודש תשמ \" ו מענה קעד .][\nיג\nער \" ח מרחשון ][\nמענה לאחת מנשות אנ \" ש שכתבה : \" בקשר למצב בריאות אחותי . .\nנמסר לי שלפי דעת ד \" ר . . ולפי דעת האחות המטפלת בה , יש אפשרות\nלהועיל לה ע \" י שאבקר אותה . ובכן , נתעוררה אצלי השאלה האם כדאי\nלנסוע ל . . לבקרה ( ביחד עם התינוק שלנו . . ושלשת הילדים שיחיו\nישארו כאן עם בעלי שליט \" א ). הנני מעוברת ב \" ה כחמשה חדשים וד \" ר .\nמסכים לנסיעה . והנני שואלת עצת כ \" ק אדמו \" ר שליט \" א \" ( מהעתקה ..\nהמענה מתפרסם בזה לראשונה באדיבות משפחת הנמענת וזכות הרבים\nתלוי ' בהם :)\nכעצת רב מורה הוראה בפועל\nאזכיר עה \" צ\nיד\nתחלת מרחשון ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) לר ' צבי מאיר שטיינמעץ\nשהכניס את הרבעון \" בצרון \" ( תשורה זלמנוב כ \" ד סיון תשע \" א . וראה\nלקמן מענה טו ); (2 ) להנהלת \" נשי ובנות חב \" ד \" ( תשורה וויינפעלד כ \" ח\nסיון תשע \" ח . וראה לקמן מענה טז :])\nנת ' ות \" ח ,\nודבר בעתו –\nבסמיכות לז ' מ \" ח ,\nאזכיר עה \" צ ."],[9200230017,"17\nמענות קודש – ה ' תשד \" מ\nטו\nתחלת מרחשון ][\nמענה לר ' צבי מאיר שטיינמעץ שכתב : \" הנני מתכבד להגיש בזה את\nהרבעון \" בצרון \" ובו מאמר מאת פרופ . אהרן מירסקי מירושלים על ספרי\n\" מכנף הארץ \" ותקותי שכ \" ק אד \" ש ימצא ענין במאמר הנ \" ל . . בבקשת\nסליחה על ההטרחה \" ( תשורה זלמנוב כ \" ד סיון תשע \" א :)\nעל תיבת \" ההטרחה \", כתב :\n!?\nטעות כיו \" ב – אינה מלכתחילה כמובן\nוהלואי וירבו כמותה וכו '\nוצירף את המענה כללי - פרטי דימים אלו ( לעיל מענה יד .)\nטז\nתחלת מרחשון ][\nמענה להנהלת \" נשי ובנות חב \" ד \" ( תשורה וויינפעלד כ \" ח סיון תשע \" ח ,\nוהעתקה :)\nמצורף בזה השתתפות $36\nהרשימות של המשתתפות נלקחו\nכבר נתן להן\nוצירף את המענה כללי - פרטי דימים אלו ( לעיל מענה יד .)\nיז\nתחלת מרחשון ][\nמענה להשליח ר ' דוד לייב גראסבוים ( ס ' \" שליחות כהלכתה \" ע ' 203 ,\nוהעתקה :)\n[1 על שאלתו בקשר להצעה מסויימת , כתב :]\nכעצת אנ \" ש שבמדינה"],[9200230018,"18\nמענות קודש – ה ' תשד \" מ\n[2 על שאלתו האם מותר לגוי ללמוד את התנ \" ך , כתב :]\nכדעת רב מורה הוראה בפועל\nאזעה \" צ\nיח\nט ' מרחשון ][\nמענה לא ' התמימים על מכתבו אותו פתח בתיבות : \" המצב שלי – בפרט\n– ברוחניות \" ( מצילום כתי \" ק – \" כפר חב \" ד \" גליון 971 :)\nכמפורסם בכל כיו \" ב [– בפרט – ברוחניות ]\nכהוראת המשפיע שי '\nולפלא גדול – שאינו יודע מזה !\nיט\nט ' מרחשון ][\nמענה לר ' משה פנחס הכהן כ \" ץ שכתב :\n\" הנני בזה להודיע כי אתמול בהמדור בתחנה WEVD מסרתי בתחלה\nמענין הכנסים להמשיך עד ט \" ו מרחשון הבע \" ל , מסרתי ג \" כ ר \" פ\nמהמדובר בש \" ק בהתועדות ומעט מהשיחה הק ' הראשונה [ שם נת '\nמש \" כ בזהר \" מאלול עד שית יומין בחשון . . יומין דאתוון ( אותיות )\nנינהו \", אשר הענין ד \" המלך בשדה \" נמשך עד אז .]\nבהשיעור תניא הוספתי הביאורים על השיעור שנדפס בהמ \" מ והערות\nלהפרק הזה .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה כ \" ץ י \" ד שבט\nתשע \" ב :)\nנת ' ות \" ח וכו .'\nהאותיות ( שמדובר בזהר ) הן להביא המלך למטה להשדה ( ולא –\nלהיפך )"],[9200230019,"19\nמענות קודש – ה ' תשד \" מ\nכ\nט ' מרחשון ][\nמענה להשליח ר ' ברוך שלמה אליהו קונין על מכתבו – בהמשך ל מענה\nשקיבל על ההצעה להשיג ממון באמצעות משחקי \" בינגו \", אשר \" מופרך \"\n– בו כתב פעם נוספת בנושא ( ס ' \" שליחות כהלכתה \" ע ' 407 ( חלק מתוכן\nהמענה .) המענה בשלימותו מתפרסם בזה לראשונה מהעתקה באדיבות\nהנמען שי ' וזכות הרבים תלוי ' בו :)\nבתמהון גדול קראתי הנ \" ל – דכשכתוב מופרך צריך להיות שאלה –\nהאם הכוונה להמשיך ( המופרך ) או לא – בכל אופן – במענתי מופרך –\nכוונתי מופרך\nכא\nי \" א מרחשון ][\nמענה ל מ ערכת עיתון \" משיח טיימס \" היו \" ל ע \" י \" צבאות השם \" שהכניסו\nאת שער העיתון ד חודש כסלו שעליו ציור בו נראים ילדי צבאות השם\nמדליקים את נרות חנוכה ( תשורה התועדות חסידים אור ליום ג ' פ '\nויק \" פ תשנ \" ו :)\nכדאי להוסיף בקרן הימני למטה צורת סביבון .\nכב\nמרחשון ][\n\" צעטל \" בכתי \" ק שכתב כ \" ק אדמו \" ר שליט \" א לר ' שלום דובער לוין\nבקשר לספרים שהכניס ר ' מנחם מענדל שפרינגער , מהם אחדים מספרי\nהרה \" ג הרה \" ח הרב אברהם דוד לאוואוט ז \" ל , מעזבון נכדיו המתגוררים\nבמאנטרעאל קנדה . בספרים אלו הערות אחדות שכתב על הגליון . בנפרד\nהכניס הנ \" ל את רשי מת הספרים , וכתב : \" הספרים מסרתי לה \" ר שד \" ב\nשיחי ' הספרן \" ( קובץ \" עבודת הקודש אצל הרבי \" ע ' עג :)\n[1 בקשר לרשימת הספרים , כתב :]\nלמסור לו רשימה הנ \" ל .\n[2 בקשר לההערות שעל הגליון , כתב :]\nבאם מתאים להדפיסם ביגד \" ת ."],[9200230020,"20\nמענות קודש – ה ' תשד \" מ\n[3 על אחד הספרים ( שאינו מהאוסף האמור ), כתב :]\nלהראני .\nכג\nי \" ז מרחשון ][\nמענה בקשר לרשימת תלמידים השלוחים לישיבת תו \" ת דברינוא ( ס '\nיומן \" רישומה של שנה \" ע ' 91 :)\nאזכיר עה \" צ .\nכן הורה כ \" ק אדמו \" ר שליט \" א שיסעו \" תיכף .]\"[\nכד\nח \" י מרחשון ][\nמענה בקשר לרשימת תלמידים השלוחים לישיבת תו \" ת דמאנטרעאל ( ס '\nיומן \" רישומה של שנה \" ע ' 91 :)\nהסכמה וברכה .\nכה\nכ \" ף מרחשון ][\nמענה לר ' שניאור זלמן גורארי ' על מכתבו בו כתב ע \" ד הטבה ובשורה\nטובה במצב בריאותה של הרבנית הצדקנית ( תשורה סלונים ד ' מרחשון\nתשס \" ח :)\n[1 על כללות המכתב , כתב :]\nנת ' ות \" ח על הבשו \" ט\nויה \" ר שגם בזה תהי ' הליכה מחיל אל חיל ויבש \" ט כו .'\n[2 על ציון תאריך המכתב \" ב \" ה ה ' חיי \" ( כ \" ף מרחשון ), כתב :]\n– הולדת זקנה כו '\nומזלו גובר וכו '"],[9200230021,"21\nמענות קודש – ה ' תשד \" מ\nכו\nכ \" ף מרחשון ][\nמענה לאחת שכתבה שכל הצרות והיסורים שבעולם משפיעים עלי ' לרעה\nוגורמים לה מחשבות יאוש ( לקו \" ש חכ \" ד ע ' 527 :)\nכמפורסם מיסודי תורתנו הק ' ענין השגחה - פרטית ותתבונן בזה . וח \" ו\nלומר שהעולם הפקר . תלמוד שער הבטחון בספר חובת הלבבות , ישנו\nגם באנגלית .\nבדיקת המזוזות , דיוק בכשרות האכילה ושתי .'\nכז\nלאחר כ \" ף מרחשון ][\nמענה לא ' על מכתבו בהמשך להמדובר בהתועדות אור לכ \" ף מרחשון ע \" ד\nרמ \" א שי ' זליגסון :)\n[1 במכתבו שאל מהמנהג בבתי כנסיות להראות תמונות אריות ועוד ,]\nשהם חיות בלתי טהורות .\nמענה כ \" ק אדמו \" ר שליט \" א :\nכפשוט שם הכוונה להזכיר ע \" ד המרכבה ( או עד \" ז לציווי המשנה עז\nכנמר כו .)'\n[2 ] במכתבו העיר על מה שנזכר מנהג נשי ישראל כשיוצאות מן הטבילה\nליזהר שלא יפגע בה תחלה דבר טמא ובאם כן לחזור לטבול .\nמענה כ \" ק אדמו \" ר שליט \" א :\nעיין יו \" ד ס \" ס קצ \" ח וש \" נ ."],[9200230022,"22\nמענות קודש – ה ' תשד \" מ\nכח\nלאחר כ \" ף מרחשון ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בקשר להערה בשיחת אור\nלכ \" ף מרחשון – שנערכה ע \" פ המענה דלעיל ( מענה כז :)\n\" בקשר עם מ \" ש בהערה 1 ( בהשיחה ע \" ד צורת בהמות טהורות ) ע \" ד מה\nשמצינו בכו \" כ בתי כנסיות ציורי פני ארי ' ופני נשר על הפרוכת דארון\nקודש ועל המעיל וכתר דס \" ת בכדי \" להזכיר ע \" ד הכרח התפלה ועבודת\nהאדם לה ' באופן דגבור כארי כו ' . . . ואולי י \" ל – ע \" ד המרכבה שבה פני\nארי ' ופני נשר \" –\nהנה ישנו שקו \" ט בזה ( בענין צורת ארי ' כו ' בביהכנ \" ס ) בפוסקים , ויש\nמתירים את זה ( ב \" י יו \" ד סקמ \" א ד \" ה כתב ) [ ומ \" ש בשו \" ע יו \" ד סרמ \" א\nס \" ד \" אסור לצייר צורות שבמדור שכינה כגון ד ' פנים בהדי הדדי דוקא ,\"\nאבל כל אחד לחוד – מותר ] ויש אוסרים ( רבינו אליקים – הובא בב \" י\nשם . ט \" ז שו \" ע יו \" ד שם . ברכ \" י שם ד \" ה צורות . ועוד – הובאו בשערי\nתשובה לשו \" ע יו \" ד שם ובס ' יסודי ישורון ( בהוספות – ע ' יט ) כו \" כ שו \" ת\nהדנים בזה ואוסרים ). ועפ \" ז אולי כדאי להוסיף גם בההערה ( בתור\nהשמטה :) . .\".\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תקל :)\"\nמהיכא תיתא .\nאבל להוסיף שלכן רק \" אולי י \" ל ע \" ד המרכבה כו ' כי לסברא הא ' כל\nהעושים כן מטעם זה , ה \" ז מותר לכולי עלמא :\nהצורה מצ \" ע – אינה שלימה וכו ' והכוונה למשנה אבות – הוראה\nבעבודת ה ' ( תפלה ותורה ) שצריך להשתדל בזה וכו '\nויתרה מזה מצינו – שהרמב \" ם צייר מנורה בת ז ' קנים וכפתורי ' וגביעי '\n( לא שהורה לקטן איך לצייר – מדלא הזכיר זה ). ואכ \" מ .\nהמענה נכלל בלקו \" ש חכ \" ה ע '[ 309 הערה 1 ובשוה \" ג .]"],[9200230023,"23\nמענות קודש – ה ' תשד \" מ\nכט\nלאחר כ \" ף מרחשון ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בשיחת אור לכ \" ף מרחשון :\n\" מצו \" ב ההוראה ע \" ד ציורים דבהמות כו ' טהורות . בקשר עם כללות\nתוכן השיחה – שאלו כמה מלמדי תינוקות – האם ההוראה היא גם בנוגע\nלציורים דבהמות וחיות טמאות המדוברים בפרשת השבוע ( כמו גמלים\nבפ ' חיי שרה ) שמציירים עבור התינוקות בכדי להקל לימודם כו ' – האם\nכדאי למנוע מלצייר ציורים אלו ?\" ( מצילום כתי \" ק – \" יחי המלך \" גליון\nתפ :)\n[1 על מה שכתבו : \" שאלו כמה מלמדי תינוקות \", כתב :]\nכבר ענה מלמד תינוקת הכי מפורסם – רש \" י ( שמיני יא , ב :) מראה –\nהחי ' שלא תאכלו ובהדגשה ( דלכאורה מיותר כיון שהראה כל הנאכלות )\n[2 על מה שכתבו : \" האם ההוראה היא גם בנוגע כו \"'] – מחק את התיבות\nהאם \" \" היא גם \", וכתב :\"\nההוראה ][ לא [ בנוגע לציורים דבהמות וחיות טמאות המדוברים בפרשת\nהשבוע ( כמו גמלים בפ ' חיי שרה ]) בעת [ שמציירים עבור התינוקות בכדי\nלהקל לימודם כו ]'\nאו כשמעתיקים הסיפור מתנ \" ך ומדרז \" ל ,\nשאז ה \" ז לימוד ופי ' התורה כפשוט .,\n[3 על מה שכתבו : \" האם כדאי למנוע מלצייר ציורים אלו ?\", כתב :]\nיתרה מזו – מציירים ארי וכיו \" ב ואין מסתפקים בציור צבי ( להזכיר\nמשנה ספ \" ה דאבות .)\nהמענה נכלל בלקו \" ש חכ \" ה ע '[ 310 הערה 5 .]\nל\nכ \" ג מרחשון ][\nמענה להמזכיר רחי \" ק שכתב :\n\" בקשר לההתעוררות לסדר כינוס של שלוחים שיחיו וכן בהמשך\nלהמענה שקבלתי מכ \" ק אדמו \" ר שליט \" א נידו \" ז בתחילת חודש תמוז\nלהתדבר בזה עם הנהלת המל \" ח , הנני בזה להודיע שלאחר ההתדברות\nבין השלוחים ועם ועד מיוחד שנתמנה לפעול בזה , וכן עם הרב חדקוב"],[9200230024,"24\nמענות קודש – ה ' תשד \" מ\nשי ', הוקבע שיתקיים כאן כינוס של השלוחים דארצה \" ב בש \" ק תולדות\nמבה \" ח כסלו הבע \" ל , ויומשך עד יום ב ' אור ליום ג ' שאח \" כ .\nכנראה כעת ישתתפו בזה כשבעים שלוחים מעיירות שונות דארצה \" ב .\nהכינוס יתקיים ב 770 ובחדר גדול בבנין הסמוך 784 .\nמצו \" ב רשימה מהצעות לסדר היום של הכינוס .\nובשם השלוחים והועד הפועל הנ \" ל הננו מבקשים הוראות בכל הנ \" ל ,\nומבקשים ברכה שיהי ' הכינוס הנ \" ל בהצלחה רבה .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה קרינסקי ב '\nמרחשון תשס \" ח :)\nויה \" ר שיהא כהנל בהצלחה רבה\nל א\nכ \" ג מרחשון ][\nמענה למערכת \" ספר הליקוטים – דא \" ח צמח צדק \" ( מצילום כתי \" ק –\nקובץ \" לקט מענות קודש בקשר להדפסת ספר הליקוטים דא \" ח צמח\nצדק \" ע ' 51 :)\n[1 ] במכתבם כתבו : \" מהנהלת קה \" ת מסרו לנו , שהחלקים הראשונים\nדספר הליקוטים ( אותיות ת – מ ) כבר אזלו מן השוק , וצריך להדפיסם\nעוד הפעם ( באופסט ). התכנית היא : א ) לתקן בפנים הספר טעויות הדפוס\n( שבמקורם באוה \" ת הם לנכון ). ב ) להוסיף בסוף הספר לוח התיקון עפ \" י\nכת \" י ( עבור טעויות הדפוס באוה \" ת ). ג ) להוסיף ציונים עיקריים החסרים\nבהוצאה הראשונה . ד ) לשנות כותר ות הסעיפים לכמו שהם מופיעים\nבכרך המפתחות ( שיו \" ל בקרוב ). ה ) להוסיף בראש כל דף שם הערך .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nההוספות כדאי שיהיו גם בקונטרס בפ \" ע ( שיוכלו לצרפו להוצאה הא '\n[2 ] במכתבם כתבו : \" לאחר הדפסת חלקים הראשונים דסה \" ל , יצאו\nלאור כמה ספרי מפתחות מספרי דא \" ח [ והם : מאמרי אדה \" ז ; ספרי\nאדמו \" ר האמצעי ; ספרי אדמו \" ר מהר \" ש ; ספרי אדמו \" ר מהורש \" ב ;\nספרי אדמו \" ר מהוריי \" צ ; לקוטי שיחות ( חלקים י - טו )], שלא נכללו\nבמראי מקומות הבאים בסוף כל ערך . – האם להדפיסם בהוצאה זו בסוף\nהספר .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :"],[9200230025,"25\nמענות קודש – ה ' תשד \" מ\n– רק בקונטרס בפ \" ע\n[3 ] במכתבם כתבו : \" בנוגע לכרך המפתחות – כל הספר כבר מסודר\nבדפוס , ונשאר רק לסדר העמודים .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" כל הספר כבר מסודר\nבדפוס \", וכתב :\nוהזריזות ביותר תשובח ביותר\nלב\nכ \" ה מרחשון ][\nמענה לר ' זלמן יהודה דייטש שכתב שהוא מתעניין לאחרונה בקניית\nנדל \" ן , וישנם אפשרויות שונות בעסקים אלו , ושואל את דעת כ \" ק\nאדמו \" ר שליט \" א בענין ( ס ' \" ויהי איש מצליח \" ע ' 119 :)\nכעצת ידידים ( לשון רבים ) מבינים . אזכיר על הציון .\n[ וראה לקמן מענה מו .]\nלג\nכ \" ז מרחשון ][\nמענה לר ' אפרים וואלף שכתב ע \" ד הצעה שעלתה להקים ישיבה שתהי '\nכעין \" מכינה \" בין הישיבה קטנה בלוד לבין הישיבה בכפר חב \" ד , וכתבו\nאשר \" בשיחות עם מרא דאתרא והועד . . יש התייחסות חיובית מאוד\nלהצעה הנ \" ל \" ( ס ' \" ימי תמימים \" ח \" ח ע ' 207-9 :)\nבאם [ כי בשיחות עם מרא דאתרא והועד . . יש התייחסות חיובית מאוד\nלהצעה הנ \" ל ] היינו הסכמה – טוב כהנ \" ל ."],[9200230026,"26\nמענות קודש – ה ' תשד \" מ\nלד\nועש \" ק תולדות , כ \" ח מרחשון ][\nמענה לר ' אפרים וואלף שכתב ע \" ד הצעת אישיות מסויימת – לשמש\nכראש כולל , וכראש ישיבה עבור ה \" מכינה \" שמתכננים לפתוח ( תשורה\nהלפרין י \" ד תמוז תשס \" ב :)\n1 באם אין בזה השגת גבול , טוב ויהא בשעטומ \" צ .)\n1 כמה מינוט מתבוננים קודם להציע הנ \" ל ?)\n2 ) כמה מחנכים משתתפים בהדיון ?\n3 ) בטח יענו ע \" ז מתאים להמציאות שהיתה בפועל – ויוסיפו לאח \" ז\nהסברה : המדובר בתל ' שהם כבר באמצע חינוך חב \" די , הוריהם\nוהסביבה יודעים שהנ \" ל בעל מסי \" נ על חב \" ד ובפועל , אבל אך זה עתה\nנכנס בתוך חב \" ד ( ואך זה עתה ) עלה לאה \" ק ולתנאי ' מעולם לא הי ' ר \" י\nבגיל כהנ \" ל ולסוג ישיבה כהנ \" ל ובכל זאת החליטו כנ \" ל – כי :\nואענה ע \" ז לאחרי קבלת זה\nלה\nועש \" ק תולדות , כ \" ח מרחשון ][\nמענה לא ' שכתב שבנו הצעיר אינו לומד כראוי , ורוצה שבנו יעזוב את\nהישיבה ויעבוד ( ס ' יומן \" רישומה של שנה \" ע ' 98 :)\nכפשוט אין עניני לומר לבנו שי ' שאינו שייך ... ללימוד תוה \" ק , ח \" ו !,\nובפרט שזהו היפך החזקה דבנ \" י .\nלו\nלאחר ש \" פ תולדות , ער \" ח כסלו ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בשיחת ש \" פ תולדות :\n\" בנוגע למ \" ש בכתי \" ק ( בהשיחה ע \" ד השלוחים ) שהוספת אדה \" ז\nבמאחז \" ל שלוחו של אדם כמותו )( – כמותו ( דהמשלח ) ממש – הוא \" ע \" פ\nל ' ר ז \" ל . \". – עדיין לא תפסנו הכוונה בזה . חפשנו באוצר לשון התלמוד\nערך ממש וערך כמותו , אבל לא מצאנו שם איזה לשון השייך לעניננו"],[9200230027,"27\nמענות קודש – ה ' תשד \" מ\nישנם שם ריבוי מקומות ברז \" ל שהובא הלשון \" ממש \"( – \" מלך חדש\nממש \", ועוד הרבה .)\nאולי הכוונה – לקידושין מג , א : \" שלוחו של אדם כמותו הוה לי ' כגופו .\"\nוא \" כ – ההערה צ \" ל : ע \" פ ל ' רז \" ל קידושין מג , א : שלוחו של אדם כמותו\nהוה לי ' כגופו האם נכון .\"?.\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תצג :)\"\nכוונתי כפשוטה שכתוב שלוחו ש \" א כמותו ממש\nלז\nלאחר ש \" פ תולדות , ער \" ח כסלו ][\nמענה ל \" ועד הנחות התמימים \" שכתבו – בהמשך להמענה שקיבלו :\n\" הלשון ב רז \" ל \" שלוחו של אדם כמותו ממש \" – לא מצאנו ( לע \" ע .)\nתוכן הענין מובן מכמה דרז \" ל – כמובא בלקח טוב ( לר \" י ענגיל ) כלל א '\n( הנסמן בהמשך השיחה בקשר עם ג ' ( ד ') דרגות בשליחות , עד כמותו\nממש ), ובשו \" ע אדה \" ז או \" ח סרס \" ג סכ \" ה בקו \" א ( ג \" כ נסמן לקמן שם )\nכ ': \" כעושה בעצמו ממש וכו ' וה \" ז כאלו אוחז בידו של חברו שנעשית\nכידו אריכתא .\"\nועפ \" ז אולי לציין בההערה ( על התיבות און ווי דער אלטער רבי איז\n*\nמוסיף – כמותו דהמשלח ממש ): *) ראה לקמן בפנים ובהנסמן בהערה\n10 .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תצג :)\"\n[1] על התיבות \" הלשון ב רז \" ל כתב :\",\nבס ' שלפני זמן אדה \" ז\n[2 על התיבות \" תוכן הענין מובן מכמה דרז \" ל \", כתב :]\nמקידושין ומכילתא וכו '\n[3 על מה שכתבו \" ועפ \" ז אולי לציין כו '\", כתב :]\nמהיכא תיתא"],[9200230028,"28\nמענות קודש – ה ' תשד \" מ\nל ח\nלאחר ש \" פ תולדות , ער \" ח כסלו ][\nמענה ל \" ועד הנחות התמימים \" שכתבו – בהמשך להמענות שקיבלו :\n\" הלשון ( והענין ) ששלוחו של אדם כמותו ממש בס ' שלפני זמן אדה \" ז )( –\nמצאנו בתשובת הריב \" ש סרכ \" ח : \" ילפינן ( קידושין מב ) שלוחו של אדם\nכמותו מדכתיב בפסח ושחטו אותו כל קהל עדת ישראל , כמותו ממש\nילפינן שהרי קרא השליח בשם כל הקהל וא \" כ השליח כבעלים לגמרי .\"\nובהמשך הענין : \" כמותו לגמרי . והשליח ראשון עושה שליח שני ושני\nשלישי וכן לעולם במידי דליכא קפידא אע \" פ שלא פירשו הבעלים לשליח\nראשון שיוכל למנות אחר תחתיו .\"\nועפ \" ז האם צ \" ל ההערה על התיבות בהשיחה \" און ווי דער אלטער רבי\n*\nאיז מוסיף – כמותו ( דהמשלח ) ממש .\nע \" פ ( או : ע \" ד ?) לשון הריב \" ש ( בתשובותיו סרכ \" ח .\")*)\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תצג :)\"\nמחק את התיבות : \" ע \" פ ( או : ע \" ד ?)\", וכתב :\nוכן הוא לשון הריב \" ש ( בתשובותיו סרכ \" ח ].)[ ובודאי נמצא בכ \" מ .\nנדפס בלקו \" ש חכ \" ה ע '[ 340 הערה 6 .]\nל ט\nלאחר ש \" פ תולדות , ער \" ח כסלו ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם בשיחת ש \" פ תולדות :\n\" בענין \" ועשתה את צפרני '\" לשון תיקון – כפי שהובא בהמשך תער \" ב\n( ח \" ג ע ' א ' שפט ) בשם \" ת \" א \". בת \" א שלפנינו – ליתא . ואולי צ \" ל במקום\nת \" א \"\" – רמב \" ן , ע \" פ דעת ר ' אליעזר יבמות מח , סע \" א .\nוהנה ז \" ע מצאנו בסידור ( שער המילה ) קמה , א ובסהמ \" צ להצ \" צ מצות\nמילה ( ט , א ) ( בענין ברא אלקים לעשות – לתקן ) שם : \" כמו ועשתה את\nצפרני ' ותרגומו ותתקן ובהמשך תער \" ב שם הלשון הוא \" ועשתה ( את )\".\nצפרני ' ת \" א ותקנית . .\nחפשנו בנוסחאות ת \" א , ובכולם – כמו הגירסא שלפנינו . ."],[9200230029,"29\nמענות קודש – ה ' תשד \" מ\nע \" פ הנ \" ל אולי צ \" ל ההערה בלשון כזה ( בתור הקדמה ל \" ועשתה \" לשון\nתיקון ): רמב \" ן עה \" פ . סידור קמה , א . דרמ \" צ מצות מילה ( ט , א ). המשך\n*\nתער \" ב ח \" ג ע ' א ' שפט . – ע \" פ דעת ר ' אליעזר יבמות מח , סע \" א ( וראה\nרש \" י שם – ד \" ה עשי '). ספרי עה \" פ .\n*) בשם תרגום . ובהמשך תער \" ב בשם \" ת \" א \". אבל בתרגום ות \" א\nשלפנינו – ליתא . ואולי צ \" ל במקום \" תרגומו \" ( ו \" ת \" א )\" – רמב \" ן .\nהאם נכון לעשות כן – כי לכאורה בסידור , סהמ \" צ והמשך תער \" ב שם –\nהובא לשון התרגום \" ותתקן \", \" ותקנית \", ובמילא דוחק לומר שבמקום\nתיבת \" תרגומו \" ( או \" ת \" א \") צ \" ל רמב \" ן .\"?\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – יחי המלך \" גליון תקלג :)\"\n[1 תיקן במכתב והוסיף הערה לרשימת השיחה :]\n)*\n[ בענין \" ועשתה את צפרני '\" לשון תיקון ]\nלהעיר :*) בהמשך תער \" ב ( ח \" ג ע ' א ' שפט ])[ ועשתה צפרני '\" ת \" א ][\nותקנית ].\"[ ו [ בת \" א שלפנינו – ליתא . ואולי צ \" ל ] ועשתה את צפרני ' ותר '\nותתקנ ' ועפ \" ז יומתק ג \" כ שלא שינה מל ' הסידור שער המילה ) קמה ,[(\nא ובסהמ \" צ להצ \" צ מצות מילה ( ט , א ])\nומחק את כל המשך הדברים במכתבם .\n[2 על מה שרצו לכתוב בשוה \" ג לההערה : \" ואולי צ \" ל במקום \" תרגומו \"]\nו \" ת \" א )\"( – רמב \" ן \" – סימן בעיגול את התיבות \" במקום כו '\", וכתב :\nטעות כזה הוא מעשה נסים\nמשא \" כ \" תתקן תקנית – תקוץ \" ובפרט בכת \" י\n[3 ] על מה שכתבו : \" ע \" פ הנ \" ל אולי צ \" ל ההערה בלשון כזה . . האם נכון\nלעשות כן \", כתב :\n\" אולי \" יבחרו בהכי פשוט ( סו \" ס עכ \" פ ) ויכתבו כנ \" ל (*) ( בע ' שלפנ \" ז )\nנדפס בלקו \" ש חכ \" ה ע '[ 343 הערה 30 .]"],[9200230030,"30\nמענות קודש – ה ' תשד \" מ\nמ\nאדר \" ח כסלו ][\nמענה להמזכיר רחי \" ק על מכתבו ( בתאריך עש \" ק פ ' תולדות ), בו כתב :\nהנני להודיע שסדר זמני כינוס השלוחים דימים הבאים יהי :'\"\nההתחלה בהתועדות כ \" ק אדמו \" ר שליט \" א – ויומשך במוצש \" ק בשעה\n8:00 וההמשך ביום א ' וכן ביום ב ' יהי :',\nבשעה 8:00 בבוקר לימוד דא \" ח , בשעה 9:00 תפלת שחרית ולימוד נגלה ,\nבשעה 11:00 ישיבה א ' עד 2:00 , בשעה 3:15 תפלת מנחה , בשעה 3:45\nישיבה ב ' עד 6:45 , בשעה 6:45 תפלת ערבית , בשעה 8:00 ישיבה ג .'\n( הישיבות תהיינה בעיקר בחדר גדול בקומה העליונה בהבנין הסמוך\nל 770 . הארוחות – ביחד בבנין ופרצת על קינגסטאן עוועניו .)\nחברי הועד המסדר הם שלמה קונין , ישראל שמוטקין ואברהם שמטוב .\nהח \" י נקודות שנמסרו כבר לכ \" ק אדמו \" ר שליט \" א נחלקו לששה סוגים ,\nובכל א ' מהו ' ישיבות ידברו בא ' הסוגים כמצו \" ב . ( ולאו דוקא בסדר\nהמצו \" ב .\")\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה קרינסקי ב '\nמרחשון תשס \" ח :)\n[1 סימן קו תחת התאריך \" עש \" ק \", וכתב :]\nוהגיעני יום א '\n[2 על כללות המכתב , כתב :]\nויה \" ר שיהא כהנ \" ל בהצלחה רבה בכל ויבש \" ט\nמא\nבדר \" ח כסלו ][\nמענה להשלוחים המשתתפים ב \" כינוס השלוחים \" על הפ \" נ כללי\n( מצילום כתי \" ק – תשורה ניאזוף י \" א שבט תשע \" ו . לקו \" ש חכ \" ה ע ' 343 :)\n*\nבנוסף על השיחה ( כולל – ש \" בין השורות \" שלה ) כבר מלתייהו אמורה\n**\n– כל המברך מתברך בברכתו של הקב \" ה שמרובה על העיקר – מתחיל\nב ההוספה ב העיקר , מילוי השליחות בשלימות .\n___"],[9200230031,"31\nמענות קודש – ה ' תשד \" מ\n*) ירושלמי ( ברכות ספ \" ח ) הובא בתוד \" ה ואברכך – חולין מ ט , א . וראה\nהערה הבאה .\nב \" ר פס \" א , ד . וראה בארוכה לקו \" ש ח \" ה ע '**) 422 ואילך . ועוד .\nמב\nג ' כסלו ][\nמענה למר אורי עמית – תושב קרית - טבעון אה \" ק – שכתב שלפני לידת\nבנו היו בעיות , ובדקו המזוזות ומצאו שאחת הייתה הפוכה , ולאחר\nשסידרו את זה הכל הסתדר . וכתב שחושב שיש קשר בין זה שהמזוזה\nהייתה הפוכה , לבעי ' שהייתה שהעובר הי ' הפוך , ושלאחר שהפכו את\nהמזוזה הכל הסתדר ( לקו \" ש חכ \" ד ע ' 374 . \" בית חיינו \" ( תנש \" א ) גליון\n68 :)\n.[ ]. ת \" ח על הודיעני סיפור המזוזה , ובעיקר – על שצירף פירושו\nדהקשר – וה \" ז מיסודי אמונתינו – אשר הכל הוא בהשגחה פרטית\nמהשם בורא עולם ומנהיגו , אלא שאיש חכם מבין ורואה זה ומי שאינו\nוכו .'\nמג\nד ' כסלו ][\nמענה לא ' שכתב : \" לפני כשנתיים גידלתי זקן , התחלתי להניח תפילין\nולשמור שבת . חבר למקצוע יעץ לי שאם אגלח את זקני , העסק יצליח\nיותר משום שבאמריקה האנשים מצפים מהרופא להראות מגולח , אך\nאיני בטוח שיהיה נכון מצידי לגלח את הזקן . בעצתו של הרב . . אני כותב\nלכבוד הרב בבק שת עצה וברכה בענין זה . \" יהיו לרצון אמרי פי והגיון לבי\nלפניך ה ' צורי וגואלי \"\" ( מצילום כתי \" ק – קונטרס ועד הנחות בלה \" ק\nש \" פ בהעלותך תשע \" ח :)\nסימן בעיגול את התיבות : \" האנשים מצפים מהרופא להראות מגולח ,\"\nוכתב :\n?!\nהרי דוקא לאחרונה – מתרבים והולכים מגדלי זקן בארצה \" ב , ביניהם\nרופאים וכו ' ( 1 )\nעל התיבות : \" איני בטוח שיהיה נכון מצידי לגלח את הזקן \", כתב :"],[9200230032,"32\nמענות קודש – ה ' תשד \" מ\n!?\nהרי מפורש בזוהר הק ' דגידול הזקן ממשיך ברכות רבות מהשם ( 2)\nאזכיר עה \" צ ויבש \" ט ( 3)\nמד\nתחלת כסלו ][\nמענה לר ' צבי מאיר שטיינמעץ שכתב את הערותיו בהקדמת הספר\nאמרי יוסף \" עה \" ת להרה \" ק הרב יוסף מאיר מספינקא :\" ( 1 ) במה שכתוב\nאשר המחבר \" שקד מאד בלמוד ספר התניא \", פלא כי הי ' תלמידו של\nהרה \" ק הרב יצחק אייזיק מזידיטשוב שהי ' תלמידו של דודו הרה \" ק הרב\nצבי הירש מזידישטוב ב על \" עטרת צבי \", אשר ידועים חילוקי הדיעות\nבינו ובין אדה \" ז ; ( 2 ) במה שכתוב אשר הרה \" ק הרב אברהם יהושע\nהעשיל מאפטא בעל \" אוהב ישראל \" אמר \" שגם אבותינו הקדושים\nאברהם יצחק ויעקב הלכו בדרך העבודה של הספר לקוטי אמרים ,\"\nנראה כסותר את המסופר בדבר קפידתו על א ' מחסידי אדה אמ \" צ על\nלמדו חסידות חב \" ד ביאסי ( תשורה זלמנוב כ \" ד סיון תשע \" א :)\nנת ' ות \" ח ודבר בעתו בסמיכות לי ' כסלו יום גאולת האדמו \" ר האמצעי\nועיקר : הלפרסם וכו ', היחפש וכו '\nכידוע נסתדרו אח \" כ .\nמה\nח ' כסלו ][\nמענה על פתק שכתב המזכיר ריל \" ג , בו כתב : \" הרב בנימין אליהו\nגורודצקי שי ' טלפן – קיבל טלפון מר ' שלמה שי ' מטוסוף – ר ' דוד שי '\nעמר בקשו להשתדל – היות שהוא מגיע לכאן בסוף שבוע הבא בכדי\nלהשתתף באסיפות מטעם הדזשאנט , רצונו ליכנס ליחידות ביום ב ' ויגש\nער \" ח טבת , ובאשר עליו לסדר תכניתו נחוץ לו לדעת בהקדם אם זה\nאפשרי . – אח \" כ טלפן ר ' שלמה שי ' מתוסוף בעצמו בתוכן הנ \" ל והוסיף\nשר ' דוד הנ \" ל לוחץ עליו שיקבל מענה \" ( מצילום כתי \" ק – תשורה קוגל\nי \" ט אד \" ר תשע \" ד :)\nמעת הסתלקות כ \" ק מו \" ח אדמור הנני ער \" ח ][ עה \" צ\nהיינו 33 שנה"],[9200230033,"33\nמענות קודש – ה ' תשד \" מ\nמ ו\nט ' כסלו ][\nמענה לר ' זלמן יהודה דייטש שכתב : \" מזדמן כעת לקנות בניין גדול\nומתכונן לקנותו עם עוד שותפים . ומבקש ברכת כ \" ק אדמו \" ר שליט \" א \"\nס ' \" ויהי איש מצליח \" ע '( 119 :)\nאזכיר על הציון .\n[ כ \" ק אדמו \" ר שליט \" א צירף 100 דולר בתור \" השתתפות .]\"\nמ ז\nי \" א כסלו ][\nמענה להנהלת \" נשי ובנות חב \" ד \" בקשר ל \" שבוע האשה היהודי \"'\nשמארגנות ( ס ' יומן \" רישומה של שנה \" ע ' 113 . תשורה וויינפעלד כ \" ח\nסיון תשע \" ח . והעתקה :)\nבכלל נכון וטוב ונחוץ במאד .\nנקודה משותפת לכל פגישות , כינוסים , דינער ' ס וכיו \" ב – הפגישה וכו '\nהמרכזית ( הראשונה ) צ \" ל בשכונת מרכז ( קראונהייטס ) ורק לאח \" ז\nבמק \" א .\nקדימה לסדר הנ \" ל בתקופות – שבאים לכאן ממק \" א בלאה \" כ ( חנוכה ,\nשק \" מ , י ' שבט , פורים .)\nכדאי שעכ \" פ בקשר להיותר חשובות דהפגישות כו ' יו \" ל חוברת\nשתכלול : דברי תורה ( קדימה – בענין שהז \" ג ) זמן הדה \" נ דהזמן\nוהבדלה ) ע \" ד נשי ובנות חב \" ד ופעולותיהן וכיו \" ב .(\nונכון במאד שתהי ' בצורה – שירצו לקחתה למזכרת ולקשוט בפינת\nהספרים שבבית , או גם למתנה לחברות וכו .'\nאזכיר על הציון לכל הנ \" ל ."],[9200230034,"34\nמענות קודש – ה ' תשד \" מ\nמח\nיום הבהיר י \" ד כסלו ][\nמענה לר ' משה יהודה קאטלארסקי שכתב ע \" ד שמחת נישואין העומדת\nלהתקיים בי \" ד כסלו אלי ' הוזמן לסדר קידושין – אשר הכלה היא\nממשפחת מקורבים , והחתן הוא קרוב - משפחה של הרב צבי יחזקאל\nמיכלזאהן הי \" ד מווארשא פולין – וביקש ברכה עבור החתן והכלה\nוהמחותנים ( תשורה קאטלארסקי ג ' מרחשון תשע \" ד :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את שמו של הרב צבי יחזקאל\nמיכלזאהן הי \" ד , וכתב :\nכמדומני שהשתתף בחתונתי , וכן נתן לי מתנה – דרשה געשאנק –\nספרו .\nמונח בארגז הספרים בחדרי בסמיכות להתנחומא אצל החשמל )(\nאלווה אותו לאוחזו בעת הסידור קידושין ואמירת הברכות , ונראה מזה\nהשגח \" פ לאחר 55 שנה .\nמט\nט \" ו כסלו ][\nמענה לר ' אפרים וואלף ( ס ' \" ימי תמימים \" ח \" ח ע ' 212 :)\n[1 ] במכתבו ( להמזכיר רחמ \" א חדקוב ) כתב ע \" ד שני מענות שקיבלו בענין\nאישיות מסויימת .\nמענה כ \" ק אדמו \" ר שליט \" א :\nלענות בשמי ישאל אדם שאינו \" עסקן \" שיש ב ' מענות – עפ \" י איזו מהן\nלעשות ויעשה כהוראתו . ( ובלי סברות משלו ). ( דרך אגב , ואם יראהו\nהמענה הא ' יסבירו שבו מפורש שאינו מענה .)\n[2 במכתבו כתב : \" לפענ \" ד אין לפרסם ברבים .\"]\nמענה כ \" ק אדמו \" ר שליט \" א :\nכפשוט ."],[9200230035,"35\nמענות קודש – ה ' תשד \" מ\nנ\nכסלו ][\nמענה להנהלת בית הספר \" בית רבקה \" על מכתבם בקשר לעריכת מסיבת\nבת מצוה \" ( ס ' יומן \" רישומה של שנה \" ע '\" 113 \" התקשרות \" גליון קצ :).\nלעשות רק בתור מסיבת שבת או מלוה מלכה\nוהוראה בעתו שבמכתבי עת דימים אלו ממש מפליגים בפעולות ק .\nשהוא שהנהיג זה וכו '\nנא\nכסלו ][\nמענה לר ' חיים שטרן בקשר לחנוכת - הבית דבנין ישיבת \" תורת אמת \"\nבירושלים עיה \" ק ( ס ' יומן \" רישומה של שנה \" ע ' 113 :)\nויהא כהנ \" ל בהצלחה רבה , והימים זכאין בין יט \" כ לחנוכה , תוס ' צדקה\nבאה \" ק ( עשר ש ,)'\nועיקר – למגביות הנ \" ל צרור ( החיים ) שטרות ,\nאזכיר עה \" צ .\nנב\nכסלו ][\nמענה לא ' מאנ \" ש שכתב : \" בתי . . תחי ' מעצמה אינה רוצה לברך . .\nוכיו \" ב , והנני שואל מה לעשות ?\" ( ס ' \" היכל מנחם \" ח \" ג ע ' קצב - ג :)\nכהרמב \" ם לתת פרס ."],[9200230036,"36\nמענות קודש – ה ' תשד \" מ\nנג\nכסלו ][\nממענה להשליח הרב יוסף העכט על מכתבו בקשר לרעיון פתיחת ישיבה\nבעיר אילת (\" בית חיינו \" תשד \" מ גליון 7 \" התקשרות \" גליון א ' עג :).\nמעולם לא אמרתי שתו \" ת באה \" ק לא תייסד סניפים חדשים , כ \" א :\nשהנהלת תומכי - תמימים בארץ הקודש – הלואי שבמרץ ויזמה הנוכחי\nשלה תחזיק מעמד דמוסדות שכבר קיימים ( עכ \" פ בנס ) ולכן לא\nיתעסקו בסניפים חדשים ( ובפרט שאם לא יכריחום – כנראה\nמהתנהגותם במשך עשרים ויותר שנים האחרונים אין מעוניינים בזה .)\nבאם יש עצה לזה וכו ' – עליו לברר על אתר .\nוהרי כנראה גם בעירו באם לא ישתדל באווארענען עתה ככל הדרוש\nולפי עצת עסקנים באה \" ק ) גם הכולל אינו בטוח .(\nמכאן אי אפשר לשנות טבע הנ \" ל . ויעשה מה שביכולתו בצירוף עוד\nמאנ \" ש ב .[ ]. ואולי יצליחו לשנות וכו '. אזכיר עה \" צ .,\n[ וראה גם לקמן מענה עו .]\nנד\nכסלו ][\nמענה לר ' משה וילהלם שכתב ע \" ד הצעת שליחות בעיר פארטלאנד\nארעגאן , וביקש את הסכמתו וברכתו הק ' (\" א חסידישער דערהער \" טבת\nתשע \" ט :)\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת מה שכתב שזהו בהסכמת ה \" כולל \"\nבמלבורן ובהסכמת זוגתו , וכתב :\nבטח אין בזה השגת גבול ?"],[9200230037,"37\nמענות קודש – ה ' תשד \" מ\nנ ה\nועש \" ק וישב , י \" ט כסלו ][\n\" צעטל \" בכתי \" ק בו ציין כ \" ק אדמו \" ר שליט \" א את הפרש \" י שיתבאר\nבעת ההתועדות דש \" פ וישב ( מצילום כתי \" ק – ס ' \" מבית המלכות \" ח \" א\nע ' 50 :)\nבהנזכר אמש וישב ביקש לישב בשלוה וא \" ל כו ' – הרי הבטיחו היטב\nגו '\nואפילו אגדה צ \" ל שבפרש \" י צ \" ל בשייכות לפשט ועוד\nנ ו\nשלהי כסלו ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) ל \" ועד המחנכים \" בקשר\nלערב הרצאות בנושא חינוך שארגנו (\" בית חיינו \" תשד \" מ גליון 6 ;) ( 2 )\nלהנהלת \" צעירי אגודת חב \" ד \" המרכזית על דו \" ח – מפעולות\nהטנקיסטים ( ימי ועש \" ק ויצא , וישלח , וישב ), מביקורים בבתי - אסורים\nבמשך ימי חנוכה , ה \" בראשור \" שהו \" ל לחנוכה , פעולות מבצע חנוכה ,\nוהתועדות חסידים ב \" זאת חנוכה \" ( מהעתקה , באדיבות מערכת הספר\nועבדי דוד :])\"\"\nנת ' ות \" ח ,\nודבר בעתו –\nבסמיכות לימי חנוכה דענינם מוסיף והולך ואור ולהמשיך זה בכל ימות\nהשנה\nאזכיר עה \" צ .\nנ ז\nער \" ח טבת , ה ' דחנוכה ][\nמענה בקשר לנוסח מצבה ( לקו \" ש חל \" ה ע ' 330 :)\nבאם אין ידוע מקום מנוחת האם , כדאי להזכיר גם שמה ( באם הח \" ק\nת סכים ) ומסיימים בטוב ."],[9200230038,"38\nמענות קודש – ה ' תשד \" מ\nנח\nב ' טבת , זאת חנוכה ][\nמענה לר ' יוסף יצחק הכהן גוטניק ששאל האם כדאי לבנות מקוה בצפת\nעיה \" ק ( מהעתקה :)\nצ \" ע כוונת השאלה ,\nובכל אופן – יעשה כהוראת רב מכירו – מצבו הכספי .\nנט\nג ' טבת ][\nמענה לאחת מנשות אנ \" ש שכתבה שלמרות שעבר כמה זמן מאז שעברה\nללונדון עם בעלה , המשרת שם בקודש בא ' ממוסדות חינוך חב \" ד , הנה\nעדיין אינה מוצאת מנוח לנפשה כיון שמרגישה שמקומה \" כאן \" בשכונת\nקראונהייטס . וכתבה : \" גם ברצוני לגדל ולחנך את בנינו שיחי ' בסביבת\nכ \" ק אדמו \" ר שליט \" א \" ( קונטרס ועד הנחות בלה \" ק חג השבועות\nתשע \" ג :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את התיבות \" בסביבת כ \" ק אדמו \" ר\nשליט \" א \", וכתב :\nבודאי כוונתה לרוחניות שבזה ( ולא לעצים ואבנים שב ה שכונה ) וזה\nתמצא במוסד שלי בלונדון .\nס\n[ תחלת טבת ]\nכמה מענות שכתב כ \" ק אדמו \" ר שליט \" א בתקופה זו – הוגהו עוה \" פ\nיחדיו ע \" י כ \" ק אדמו \" ר שליט \" א ע \" מ לפרסם ( מצילום כתי \" ק – תשורה\nאראנאוו י \" ב סיון תשס \" ד :)\nבמענה על שאלות רבים :\nא ) האם בעת כינוס וכיו \" ב של אנשים , נשים וטף – כדאי לומר אתם\n\" הריני מקבל עלי מצות עשה של ואהבת לרעך \" ( בכדי לזכות את אלו\nשאולי עוד לא אמרו זה ) –\nהואיל כ \" ק אדמו \" ר שליט \" א להשיב :\n\" מובן שנכון במאד .\""],[9200230039,"39\nמענות קודש – ה ' תשד \" מ\nב ) למה אין אומרים הריני מקבל וכו ' גם לפני תפלת מנחה וערבית ( ע \" ד\nשאומרים אך צדיקים וגו ' אחרי כל תפלה :)\nתשובת כ \" ק אדמו \" ר שליט \" א :\nאמירת הריני מקבל עלי כו ' לרעך אינו חלק מהתפלה או שייך לענין\nתפלה דוקא , אלא ענין בפ \" ע , ומפני כמה טעם ( שנתבאר במק \" א ), סמכו\nאמירתו לתפלה ( הראשונה היינו שחרית ) ופירושה כפשוטה סתם\nמקבלה על כל היום כולו .\nהפסוק אך צדיקים גו ' שייך להתפלה \" יודו לשמך \" – ראה ברכות . .\nהובא בשו \" ע אדה \" ז . . – ולכן אמירתה אחר כל תפלה\nומכיון ששייך בכל היום כולו פשוט שכדאי להקדים אמירתו .\nג ) ע \" ד הדפסת התניא באותם המקומות שע \" ע לא נדפס – האם הכוונה\nלמדינות או לערים ,\nהמענה :\nהרי מודפסת רשימת דפוסי התניא ( בתניא הוצאת קהת ) ושם בכו \" כ\nערים במדינה אחת .\nבקשר לאמירת \" הריני מקבל ו \" אך צדיקים \"[ – ראה גם לקמן מענות :\nדס , ס ה , קס ד .\nבקשר להדפסת ס ' התניא בכל מקום ומקום – ראה גם לקמן מענות : ע ,\nחע , ע ט פ ,, פ ב , פ ג , פ ד , פ ה , פ ו , צ א , צ ב , צ ג , צ ד , ק ו , ק ט , קט ז , קכ ג , קכ ד ,\nקמ א , קמ ד , קמ ז , קס ב , ר ז , רל ד , רס ג , רס ז , רעו , רצ ה , רצ ט , ש י , שי א ,\nשכ א , שכ ב , שכ ג .]\nס א\nאור לו ' טבת ][\nמענה לא ' מאנ \" ש שכתב ע \" ד הצעה שקיבל מא ' השלוחים לעבור למקומו\nלשמש כמלמד בה \" חדר \" אשר שם לשנת הלימודים הבעל \" ט , יחד עם\nפעילות בהפצת היהדות והמעינות עם הסטודנטים בקמפוס שם . ושאל\nעצת כ \" ק אדמו \" ר שליט \" א אם לקבל ההצעה ( מהעתקת המזכיר . המענה\nמתפרסם בזה לראשונה באדיבו ת הנמען שי ' וזכות הרבים תלוי ' בו :)\nכעצת ידידים מבינים\nאזכיר עה \" צ\n[ וראה לקמן מענות סט , קע ז , קפ ג .]"],[9200230040,"40\nמענות קודש – ה ' תשד \" מ\nסב\nו ' טבת ][\nמענה על הדו \" ח מהתועדות חסידים ש \" פ ויגש ב - 770 – שנערכה בהמשך\nלהוראת כ \" ק אדמו \" ר שליט \" א בשיחת אדר \" ח טבת ( ס ' יומן \" רישומה\nשל שנה \" ע ' 119 :)\nנת ' ות \" ח ויה \" ר שתהא פעולה נמשכת כו .'\nסג\nז ' טבת ][\nמענה להת ' מנחם מענדל ראסקין על ההודעה שנוסע ביום זה – יחד עם\nהת ' שלום שריקי והת ' מנחם מענדל מטוסוב – להדריך את מחנה - החורף\nבמרוקו ( תשורה ראסקין כ \" ט טבת תשנ \" ט :)\nדו \" ח ופנ \" נ ות \" ח ת \" ח . המצו \" ב יחליפו בממון מרוקו ויתנו דמי חנוכה\nלהחונים בהמחנה חורף שי ' שבהדרכתם ( שהרי פעולת חנוכה נמשכת )\nאזכיר עה \" צ .\n[ כ \" ק אדמו \" ר שליט \" א צירף 360 פראנק .]\nסד\nי \" ג טבת ][\nמענה לר ' יוסף הלוי וויינברג על דו \" ח משידור ברדיו במוצש \" ק ויחי ע \" ד\nהוספת \" הריני מקבל \" ו \" אך צדיקים \" לפני ולאחרי התפלה – בהמשך\nלהוראת כ \" ק אדמו \" ר שליט \" א בהתועדות אור לי \" ט כסלו ( לקו \" ש חכ \" ה\nע ' 373 ואילך ) – בקשר למצב העולם ( ס ' יומן \" רישומה של שנה \" ע ' 25 ,\n127 :)\nבטח ימשיך בהנ \" ל ובפרט באם קורא המכ \" ע שבעמוד הא ' דימים\nשע \" ע – החדשות שכמו הישנות בימים שעברו )(\nההתדרדרות בהעולם וההתגרות דמלכיות וכו ' נתחדשו ביתר וכו '\nומסיימים בטוב הנראה והנגלה"],[9200230041,"41\nמענות קודש – ה ' תשד \" מ\nסה\nטבת ][\nמענה לר ' יוסף הלוי וויינברג על דו \" ח משידור מיוחד נוסף – בהמשך\nלהמענה שקיבל – ביום ד ' ט \" ו טבת בקשר לאמירת \" הריני מקבל \" ו \" אך\nצדיקים \" ( ס ' יומן \" רישומה של שנה \" ע ' 25 , 127 :)\nובפרט שבטח קרא גם המכ \" ע דהיום והלואי שלא יהי ' עד \" ז מחר וכו .'\nומסיימים בטוב .\nסו\nטבת ][\nמענה לא ' השלוחים – בעיר בו נמצא שליח נוסף – שכתב דו \" ח ממבצע\nחנוכה ( ס ' \" מקדש מלך \" ח \" ג ע ' קמח :)\nהרי מכבר ההר \" י שיחי ' ועניתיו .\nהאומנם א \" א שיתדברו ביניהם ?\nסז\nטבת ][\nמענה להמתעסקים בהכנה לדפוס דספר המאמרים תרנ \" ה - תרנ \" ו\nשהכניסו את עלי - ההגהה (\" בית משיח \" גליון 35 :)\nנת ' ות \" ח ת \" ח\nעל הבשו \" ט שהתחילו בזריזות וכו '\nובודאי גם ימשיכו כן"],[9200230042,"42\nמענות קודש – ה ' תשד \" מ\nס ח\nטבת ][\nמענה להמתעסקים בהכנה לדפוס דספר המאמרים תרנ \" ה - תרנ \" ו\nשכתבו : \" מצו \" ב מפתח ענינים לסה \" מ תרנ \" ה - תרנ \" ו שנערך ע \" י הרה \" ת\nר ' מיכאל אהרן שי ' זעליגזאן . האם להכניסו בהסה \" מ \" ( מצילום כתי \" ק\n– \" כפר חב \" ד \" גליון 1459 :)\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" האם \" וסימן בקו ובשני חיצים את\nהתיבות \" להכניסו בהסה \" מ \", וכתב :\nמהיר\nסט\nט \" ו טבת ][\nמענה לא ' מאנ \" ש שכתב : \" עפ \" י הוראת כ \" ק אדמו \" ר שליט \" א ( אודות\nקבלת ההצעה – לשנה הבעל \" ט – ב . .) \" כעצת ידידים מבינים \" [ לעיל\nמענה אס התדברנו עם כמה ( שלפי השערתנו הם ידידים מבינים )],\nוהתוצאות היו בחיוב – שנקבל ההצעה . ובכן הננו בזה לבקש את ברכת\nכ \" ק אדמו \" ר שליט \" א שקבלתנו ההצעה תהי ' בהצלחה רבה , ושנמלא\nשליחותנו – אויספירן כוונה העליונה , ולגרום נח \" ר אמיתית לאבינו כ \" ק\nאדמו \" ר שליט \" א \" ( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות\nהנמען שי ' וזכות הרבים תלוי ' בו :)\nאזכיר עה \" צ\nשבעים\nכ \" ב טבת ][\nמענה לה \" ועד להפצת שיחות \" על מכתבם – בהמשך להוראת כ \" ק\nאדמו \" ר שליט \" א בשיחת אדר \" ח טבת להדפיס את ס ' התניא בכל עיר\nועיירה שיש בה יהודים ( מצילום כתי \" ק – תשורה שטרן ט \" ו אד \" ר\nתשס \" ה . קובץ ועד חיילי בית דוד י \" ג תשרי תשע \" ד :)\n[1 ] במכתבם כתבו : \" ישנם ששאלו אם אפשר להדפיס תניא מוגדלת\n( בגודל של ספר רגיל 6 x 9 אינטש ) ומצו \" ב דוגמא איך הע ' המוגדל נראה .\nהאם נכון להדפיס בגודל כזה .\"?"],[9200230043,"43\nמענות קודש – ה ' תשד \" מ\nעל מה שכתבו : \" אם אפשר להדפיס תניא מוגדלת \" – מחק את התיבות\nאם אפשר \", וכתב :\"\nאין צורך להדפיס תניא מוגדלת ][\nעל מה שכתבו \" בגודל של ספר רגיל \", כתב :\nאין התניא ספר רגיל ][\nומחק את התיבות \" האם נכון להדפיס בגודל כזה .\"?\n[2 וכתב כמה הוראות בקשר לספרי תניא הנדפסים :]\n1 ) עכ \" פ 100 עותקים 2 ) מספר טופסים צ \" ל לתושבי המקום\nוביהכנ \" ס )( 3 ) ללמוד בו בפו \" מ בהמקום\nעא\nלאחר ש \" פ וארא , כ \" ה טבת ][\nמענה ל \" ועד הנחות התמימים \" על שאלתם במאמר ד \" ה הוא אהרן ומשה\nדש \" פ וארא :\nמצורף בזה המאמר ד \" ה הוא אהרן ומשה דש \" פ וארא .\"\nבע ' 7 ואילך – הענין דהקדמת אב לאם בכיבוד ולהיפך במורא , שהובא\nפרש \" י שזהו ענין של שינוי הטבע ונתבאר בארוכה שזהו ענין החסידות ,\nוהובא גם פירוש הבעש \" ט בשם הרס \" ג וכו ' – אולי הכוונה בזה היתה לא\nרק ( כפי שנרשם ) בתור דוגמא צדדית לענין משה ואהרן ( דאף ששניהם\nשקולים , מ \" מ זה שא ' הוקדם יש לו טעם ), אלא שזהו ביאור שני בטעם\nהקדמת משה לאהרן בדיבור לפרעה ( שהוא \" כעין \" \" היפך הטבע \", שהרי\nאהרן דיבר למשה ), והקדמת אהרן למשה ביצי \" מ ( אף שעיקר יצי \" מ הי '\nע \" י משה .\")\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה שטרן ט \" ו אד \" ר\nתשס \" ה :)\n[1 ] על מה שכתבו : \" אולי הכוונה בזה היתה . . שזהו ביאור שני בהקדמת\nמשה לאהרן \" – סימן בעיגול את התיבות \" שזהו ביאור שני וכתב :\",\nמהקושיא בפשטות – ולא נרמז אפילו שאפ \" ל כנ \" ל – מוכח דבנדו \" ד\nאין לזה מקום\nואולי י \" ל א ' הבי ' בזה – היפך הטבע כו ' הוא לתמיד . וראה )*("],[9200230044,"44\nמענות קודש – ה ' תשד \" מ\n[ הציון \"(*)\" מתייחס להנכתב לקמן מספר 2 .]\n[2 על מה שכתבו : \" והקדמת אהרן למשה ביצי \" מ ( אף שעיקר יצי \" מ הי ']\nע \" י משה )\", כתב :\nז \" א חד פעמי והל ' הוא משה גו ' מתחלתו ועד סופו )*(\nעב\nכ \" ו טבת ][\nמענה להשליח בניו זילנד ( ס ' יומן \" רישומה של שנה \" ע ' 127 :)\nעשו גדולות ונפלאות במקומם ( וכל המדינה ) עתה , ובודאי ימשיכו שם\n( עכ \" פ לע \" ע ) ויצליחו עוד יותר , ובפרט שבאו עתה בנ \" י מאחורי מסך\nהברזל , שגדול הזכות והאחריות עוד יותר , אזכיר עה \" צ .\nעג\nכ \" ו טבת ][\nמענה לר ' לוי אלתר רייטער על מכתבו ( מהעתקה . המענה מתפרסם בזה\nלראשונה באדיבות הת ' מנחם מענדל שי ' הכהן העכט וזכות הרבים תלוי '\nבו :)\nאזכיר על הציון\nעד\nשלהי טבת ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) ל \" ועד המחנכים \" בקשר\nלערב הרצאות בנושא חינוך שארגנו (\" בית חיינו \" תשד \" מ גליון 6 ;) ( 2 )\nלהשליח ר ' אהרן גאלדשטיין ( מהעתקת המזכיר , באדיבות הנמען שי :])'\nנת ' ות \" ח .\nודבר בעתו\nבכ \" ד טבת יום הילולא אדה \" ז\nאזכיר עה \" צ"],[9200230045,"45\nמענות קודש – ה ' תשד \" מ\nעה\nער \" ח שבט ][\nמענה לר ' שלום דובער לוין על מכתבו – בקשר לספר על שו \" ע אדה \" ז\nבעריכת ר ' יהושע מונדשיין : \" בקשר לדפוסי שו \" ע אדה \" ז כותב לי הר \" י\nשי ' מונדשיין במכתב מיום א ' \" מסרתי היום בשעטומו \" צ כ - 70 דפים\nלסידור בכפר חב \" ד \"\" ( מצילום כתי \" ק – תשורה מונדשיין י \" ז כסלו\nתשס \" ח :)\nעל התיבות \" כ - 70 דפים \", כתב :\nמתוך . . דפים\nעו\nער \" ח שבט ][\nמענה לר ' אפרים וואלף על מכתבו בקשר לרעיון פתיחת ישיבה בעיר\nאילת ( ס ' \" ימי תמימים \" ח \" ח ע ' 217 , 251 :)\nכפשוט הענין פתיחת ישיבה שייך אך ורק לעסקני אנ \" ש שי ' באה \" ק\n( ואפילו – לא לרבני אנ \" ש שי ' באה \" ק ) ועל אחריותם – ואין בזה כלל\nגילוי דעת או שבטל – באם הי .)'\nעז\nער \" ח שבט ][\nמענה לר ' אפרים וואלף על מכתבו בקשר להדפסת 1000 עותקים מספר\nליקוט חידושי הצמח צדק על הש \" ס ( ס ' \" ימי תמימים \" ח \" ח ע ' 217 ,\n251 :)\nהמאזן ע \" ד הוצאות בענין הספרים באה \" ק ( דבהו \" ל , משכורת ,\nפרסומת , וכו ' וכו ' וההכנסות .)"],[9200230046,"46\nמענות קודש – ה ' תשד \" מ\nעח\nועש \" ק בא , ב ' שבט ][\nמענה לר ' מנחם מענדל וואלף שהכניס 17 מהדורות דס ' התניא שנדפסו\nבמקומות שונים באה \" ק ( ס ' יומן \" רישומה של שנה \" ע ' 146 :)\nבטח למדו בכל הנ \" ל – בפועל בתניא ' ס אלה וזכותם לעד ובגו \" ר .\nמס ' טופסים בכל מקום ?\nאזכיר עה \" צ .\nעט\nלפני ש \" פ בא , ג ' שבט ][\nמענה להשליח ר ' שבתי אלפערין בקשר לההחלטה ע \" ד הדפסת ס ' התניא\nברחבי ברזיל וההודעה ע \" ד קניית מכונת דפוס למטרה זו ( ס ' יומן\nרישומה של שנה \" ע '\" 147 :)\nכמובן נכון , מצו \" ב השתתפות קנית המכונה 100 דולר מקרן קופת כ \" ק\nמו \" ח , אזכיר עה \" צ .\n[ וראה לקמן מענות פ , פ ב , פ ד , וק .]\nפ\nמוצש \" ק בא , ג ' שבט ][\nמענה להשליח ר ' שבתי אלפערין שכתב ע \" ד בחור שנפגע ל \" ע בתאונת\nדרכים במהלך ההתעסקות בהדפסת ספרי התניא ברחבי ברזיל ( ס ' יומן\nרישומה של שנה \" ע '\" 147 :)\nהזכות הכי גדול להדפיס התניא ' ס בעיירות בבראזיל תעמוד בהנ \" ל\nובכלל . אעה \" צ ."],[9200230047,"47\nמענות קודש – ה ' תשד \" מ\nפ א\nד ' שבט ][\nמענה למערכת קובץ הערות וביאורים אהלי תורה – שהכניסו להגהה את\nהשאלות ששאל כ \" ק אדמו \" ר שליט \" א בהתועדות ש \" פ בא בפרש \" י\nוהשאירם לעיון המשתתפים בהתועדות , וכתבו : \" מצו \" ב השאלות דכ \" ק\nאדמו \" ר שליט \" א מההתוועדות דאתמול וברצוננו לפרסמו ברבים וכן\nלהדפיסו בהקובץ ( לשבת הבא ) בעז \" ה . האם נרשם נכון ?\" ( מצילום\nכתי \" ק – ס ' היובל הערות וביאורים ע ' רנח :)\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" האם \" וסימן - השאלה , וסימן בחץ את\nהתיבות \" נרשם נכון \", וכתב :\nכפי שנאמר – בהשמטת הפי ' ( החידוש ) דפרש \" י – שזוהי הקלאץ\nקשיא – כיון שלא אמרתי ' בפירוש !\nוכן כל השאר כנ \" ל – אף שזהו היסוד וכו !!'\nפב\nד ' שבט ][\nמענה להשליח ר ' שבתי אלפערין בקשר למאה מהדורות ספר התניא\nההולכות ונדפסות ברחבי ברזיל (\" בית חיינו \" תשד \" מ גליון 3 :)\nמצו \" ב השתתפות מקרני כ \" ק מו \" ח אדמו \" ר – בהוצאות ההו \" ל –\nדכאו \" א מהנ \" ל . כשיוסיפו בעוד ישובי בנ \" י יודיע , ויוסיפו בהנ \" ל .\n[ כ \" ק אדמו \" ר שליט \" א צירף 2000 דולר .]\nפג\nד ' שבט ][\nמענה להשליח ר ' ישראל ברוך בוטמאן ( תשורה בוטמאן ב ' מרחשון\nתשע \" ח :)\n[1 ] בקשר לס ' התניא שנדפס בעירו נהרי ' אה \" ק שהכניס , בצירוף\nמכתבים ושמות אנשים וכו ', כתב :\nדו \" ח ופ \" נ נתקבל\nמצו \" ב השתתפות מקרן וכו ' כמפורסם"],[9200230048,"48\nמענות קודש – ה ' תשד \" מ\n[2 במכתבו כתב ע \" ד מצבו הכספי , וכתב : \" ד ' יהי ' בעזרי .\"]\nמענה כ \" ק אדמו \" ר שליט \" א :\nהצליח במקומו עתה גדולות וכו ' וזהו התחלה לבד . ומהו העג \" נ והמצב\nרוח !?\nפד\nתחלת שבט ][\nמענה להשליח ר ' שבתי אלפערין על דו \" ח שכתב במהלך הדפסת ס '\nהתניא במקומות נידחים ברחבי ברזיל ( ס ' יומן \" רישומה של שנה \" ע '\n147 :)\nת \" ח לכאו \" א , לכ \" א מהמשתתפים שיחיו על הבשורות הטובות ביותר .\nכן ימשיכו ויוסיפו לבשר טוב . אזכיר עה \" צ .\nפה\nתחלת שבט ][\nמענה לה \" ועד להפצת שיחות \" בקשר ליוזמתם להדפסת ס ' התניא\nבשכונת קראונהייטס , בהשתתפות תושבי השכונה דולר לנפש ( ס ' יומן\nרישומה של שנה \" ע '\" 133 :)\nמצו \" ב השתתפות אזכיר עה \" צ להצלחה רבה בכל .\nכ \" ק אדמו \" ר שליט \" א צירף שני דולר .][\nפו\nתחלת שבט ][\nמענה להשליח ר ' ישראל ברוך בוטמאן שהכניס את ס ' התניא שנדפס\nבעירו נהרי ' אה \" ק ( ראה לעיל מענה פג ) – כרוך ( תשורה בוטמאן ב '\nמרחשון תשע \" ח :)\nת \" ח ות \" ח אזכיר עה \" צ ."],[9200230049,"49\nמענות קודש – ה ' תשד \" מ\nפז\nי \" א שבט ][\nמענה לא ' השלוחים על מכתבו בקשר לדו \" ד שיש לו עם שליח אחר בעירו\nמהעתקה . המענה מתפרסם בזה לראשונה באדיבות א ' מאנ \" ש שי '(\nוזכות הרבים תלוי ' בו :)\nכמפורסם – שייך לב \" ד רבני אנ \" ש שי '\nאזכיר עה \" צ\nפ ח\nי \" ד שבט ][\nמענה לר ' יהושע יוזביץ מנהל ישיבת \" תורת אמת \" בירושלים עיה \" ק\nשכתב ע \" ד א ' מאנ \" ש המביע נכונות לעזור לישיבה , אבל : \" הוא אמר\nשהתחיל כמה פעמים בדברים , וכשנוכח לראות , שיש פוליטיקה וכדומה ,\nיצא מזה \" ( ס ' \" תורת אמת \" ע ' 456 :)\nכ \" ק אדמו \" ר שליט \" א מחק את התיבות \" יצא מזה \", וכתב :\nלפלא הכי גדול כתבו אלי – כשהוא בעצמו השתתף בדיון אצל הרבנים\nשי ' וקבלו הוראות וכו ' וכו ' ( וגם במכ ' זה מעתיק [ משנוכח לראות , שיש\nפוליטיקה וכדומה ] – וד \" ל\nאזכיר עה \" צ\nפ ט\nט \" ו בשבט ][\nמענה להרב דוד ראסקין שכתב : \" בכ \" ד שבט הבעל \" ט שחל בש \" ק פ '\nמשפטים שבת מברכין חודש אדר א ' היא \" צ הא ' של אמי דרויזא בת\nהרה \" ח ר ' מ \" מ ע \" ה . והנני שואל אם נכון לנסוע לאה \" ק בקשר היא \" צ .\nובאם נכון התכנית לנסוע במוצש \" ק פ ' משפטים אור לכ \" ה שבט ובא\nלאה \" ק ביום א ' ערב , ולנסו ע חזרה בליל ה ' פ ' תרומה ולבוא כאן ביום ו '\nבקר א ' דר \" ח אדר א ' היינו להיות באה \" ק ד ' ימים , כי מצד הענינים\nהפרטיים והכלליים קשה לנסוע על זמן רב , ובזמן הנ \" ל מוכרח מצד\nהכרטיסים שיכולים כעת להשיג יותר בזול \" ( מהעתקה . המענה מתפרסם\nבזה לראשונה באדיבות מערכת הספר \" וע בדי דוד \" וזכות הרבים תלוי '\nבהם :)"],[9200230050,"50\nמענות קודש – ה ' תשד \" מ\nכעצת רב מאנ \" ש\n[ וראה לקמן מענות אק , ק ד .]\nצ\nשבט ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) להנהלת \" צעירי אגודת\nחב \" ד \" המרכזית בקשר לפעולותיהם האחרונות (\" בית חיינו \" תשד \" מ\nגליון 6 ;) ( 2 ) להנהלות \" שמי \" ר \" ו \" עזרת אחים \" שהכניסו את ההזמנה\nל \" מלוה מלכה \" שעורכים (\" בית חיינו \" שם גליון 7)] :\nנת ' ות \" ח . ודבר בעתו – בסמיכות לש \" ק שבת שירה יו \" ד שבט , העשירי\nיהי ' קדש הילולא דכ \" ק מו \" ח אדמו \" ר .\nאזכיר עה \" צ .\nצא\nשבט ][\nמענה כללי - פרטי לאלו שהכניסו ספרי תניא שנדפסו במקומות שונים ( ס '\nיומן \" רישומה של שנה \" ע ' 146 :)\nמצו \" ב $20 מקרן כ \" ק מו \" ח אדמו \" ר . אזעה \" צ .\nצב\nשבט ][\nמענה כללי - פרטי ( בימים שלאחרי המענה דלעיל ) לאלו שהכניסו ספרי\nתניא שנדפסו במקומות שונים ( ס ' יומן \" רישומה של שנה \" ע ' 146 :)\nמצו \" ב כמפורסם $20 מקרן כ \" ק מו \" ח אדמו \" ר . אזעה \" צ ."],[9200230051,"51\nמענות קודש – ה ' תשד \" מ\nצג\nשבט ][\nמענה להשליח ר ' יצחק גאלדשטיין ששאל האם כדאי להדפיס את ס '\nהתניא בערים העתיקות במדינתו ספרד – ברצלונא , טולדו , וקורדובה\n(\" בית חיינו \" תשד \" מ גליון 6 :)\nיברר אצל הררחמ \" א שי ' ( כמדומה כבר נדברו עד \" ז ) אזכיר עה \" צ .\nצד\nשבט ][\nמענה לא ' מאנ \" ש – אשר כ \" ק אדמו \" ר שליט \" א הפנה אותו לרבנים\nבשאלה האם מותר להדפיס על שער ס ' התניא תיבה הראשונה דשם עיר\nס . אואן וכיו \" ב ואפילו בר \" ת – שמסר את דברי הרבנים בנידון ( לקו \" ש\nחכ \" ו ע ' 429 :)\nכנראה לא שאלו ( עיקר ) השאלה ! שהייתה ע \" ד האות סמ \" ך ( שפי ' כו )'\nובפרט שכשידפיסו האות – הקורא השער יקרא התיבה במילואה וכו '\nויש לברר איך נוהגים בגט בעיר דזאיאנץ שי ' וכ ו .'\nצה\nשבט ][\nמענה להרב זלמן שמעון דווארקין על מכתבו בהמשך להמענה בקשר\nלכתיבת שם העיר ס . אואן וכיו \" ב ( לקו \" ש חכ \" ו ע ' 429 :)\nהשאלה ע \" ד כתיבת האות ס . כמובן שלא היתה משום לא תזכירו גו '\nשהרי אין זה שם בכלל כ \" א אמירה על כומר – שכיון שעוע \" ז , ה \" ז\n\" קדוש \" ( מפורסם ברוסיא – שבנ \" י קראו לעיר בעֶלא צעֶרקאָוו\nשוואַרצע ולא \" לבן \" טומאה – )\nובמכש \" כ הענין דקדושה .\n– שאלתי בנוגע לגיטין – כמובן , הייתה רק לצד אחד : באם בגט לא היו\nכותבים הס . הרי פשיטא שאין לכותבו בנדו \" ד , אבל – לא להיפך שבאם\nבגט כותבים ס . – מפני שאין ברירה , כיון שכך נקראת העיר ואין לה\nשם אחר – הרי גם בנדו \" ד צ \" ל כך , או עכ \" פ מותר לעשות כן .\nולהעיר מ \" פעטערבורג \" ( אגה \" ק דאדנ \" ע ) אבל שם גם בפי כמה א \" י\nנקראה בלי הוספת הס ' בראשה ."],[9200230052,"52\nמענות קודש – ה ' תשד \" מ\nצו\nשבט ][\nמענה לא ' העסקנים באה \" ק שכתב ע \" ד המצב הכספי הקשה של\nהמוסדות ( ס ' \" מיידנצ ' יק – הקטר של חב \" ד \" ע ' 208-9 והעתקה :),\nבהקדם – להפתעתי הגדולה ולטובה – הר \" ש שי ' מיידנצ ' יק בחזרתו\nמכאן לאחרי החגים לאה \" ק הרי למע ' מגדר אנושי – מילא בקשתי\nלאנ \" ש שי ' באה \" ק ע \" ד שלום ואהבת ישראל אמיתיים וכו ' ובהכנעה\nובזריזות וביקר ביחד עם הנלחמים בו בכו \" כ מוסדות וכו ' להודיע\nשמכאן ולהבא הם הבע \" ב וכו .'\nלעומת זה כו \" כ מהנלחמים בו החליטו – למטה מגדר אנושי – שכדאי\nלסכן היחס למוסדות חב \" ד , להתקציבים , \" היחס \" לחב \" ד בכלל וכו '\nובלבד לגמור הנצחון \" שלהם \" במלחמה שלהם נגדו וגם לאחרי שראו\nבפועל ההיזק הכספי , ההיזק לשם חב \" ד וכו ' – ממשיכים בשיטה זו\nובעוה \" ר דוקא הם המכריעים בנוגע לפועל , וכטבע כל מנצח ( מלבד\nשמנצח לש \" ש כמובן ) מוסיף בנצחנות ובנקמה \" ובאהבת ישראל .\"\nטובת הישיבה ובי \" ס למלאכה וכיו \" ב דורשת שבכל הנ \" ל ובכו \" כ\nמהמשרדים תהי ' ההשתדלות בראשות הר \" ש שי ' מיידנצ ' יק , וההקדם\nבזה משובח .\nצז\nשבט ][\nמענה להשליח ר ' יוסף דוד ווייטמאן שהכניס את מכתבי חברי הקבוצה\nשהגיעו מברזיל לחצרות קדשנו ליום הבהיר יו \" ד שבט ( תשורה ווייטמאן\nי \" א אלול תשס \" ו :)\nאזכיר בל \" נ עה \" צ להמצטרך לכאו \" א שי ' הנהגה יומית עפ \" י רצון השם\n( כבשו \" ע ), שהוא מקור כל הברכות . להשואלים ע \" ד 1 ) בריאות – כעצת\nרופא ידיד . 2 ) פרנסה – כעצת ידידים מבינים שעל אתר ."],[9200230053,"53\nמענות קודש – ה ' תשד \" מ\nצח\nשבט ][\nמענה להשליח ר ' יוסף דוד ווייטמאן ( תשורה ווייטמאן י \" א אלול\nתשס \" ו :)\n[1 ] במכתבו כתב ע \" ד תכניתו לפתוח יותר שיעורי לימוד יומיים\nלסטודנטים ומקורבים .\nמענה כ \" ק אדמו \" ר שליט \" א :\nנכון הדבר , הימים ושעות באופן דנסיון ולקבוע סופית לאחר חגה \" פ\n[2 במכתבו שאל האם לקרוא לזה בשם \" כולל לסטודנטים .\"]\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" לסטודנטים \", וכתב :\nתפארת בחורים\nצט\nועש \" ק יתרו , ט \" ז שבט ][\nמענה להילד מנחם מענדל קפלן שכתב את תירוציו לשאלות ששאל כ \" ק\nאדמו \" ר שליט \" א בהתועדות ש \" פ בשלח בפרש \" י והשאירם לעיון\nהמשתתפים בהתועדות ( ס ' יומן \" רישומה של שנה \" ע ' 147 . ס ' היובל\nהערות וביאורים ע ' לב , רסד :)\nנהנתי במאד מקריאתו , ובפרט מהדיוק בהפרטים וכו ' – ויציעו להדפיס\nבא ' הקובצים בצירוף הסברתו שלא יקשה מפרש \" י טו , א : כל השירה\nתמצא כפולה .\nק\nלאחר ש \" פ יתרו , י \" ז שבט ][\nמענה להילד מנחם מענדל קפלן שכתב את תירוציו לשאלות ששאל כ \" ק\nאדמו \" ר שליט \" א בהתועדות ש \" פ יתרו בפרש \" י והשאירם לעיון\nהמשתתפים בהתועדות ( ס ' יומן \" רישומה של שנה \" ע ' 147 . ס ' היובל\nהערות וביאורים ע ' לב - ג :)\nשיימסר לא ' הקובצים ."],[9200230054,"54\nמענות קודש – ה ' תשד \" מ\nקא\nי \" ט שבט ][\nמענה להרב דוד ראסקין שכתב :\n\" אודות נסיעתי לאה \" ק בקשר היא \" צ של אמי ע \" ה , התיעצתי עם הרה \" ג\nוכו ' ר ' ז \" ש שי ' דווארקין , ויעץ שנכון לנסוע .\nוכבר הזמנתי הכרטיס על מוצש \" ק הבעל \" ט לנסוע מכאן בשעה 10:45 על\nאל על ובא לאה \" ק ביום א ' בשעה 3 אחה \" צ , ולנסוע אי \" ה חזרה ביום ה '\nכ \" ט שבט ובא לכאן ביום ו ' א ' דר \" ח אדר א ' בשעה 6 בקר .\nוהנני מבקש לזכני בשליחות בהזמן בהיותי באה \" ק , ומבקש ברכה\nלהצלחה בכל הנ \" ל .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק . המענה מתפרסם בזה\nלראשונה באדיבות מערכת הספר \" ועבדי דוד \" וזכות הרבים תלוי '\nבהם :)\n[1 ] על מה שכתב : \" אודות נסיעתי לאה \" ק בקשר היא \" צ של אמי ע \" ה\nכו '\", כתב :\nהרי הנ \" ל בעצמו מצוה וכו '\n[2 על מה שכתב : \" והנני מבקש לזכני בשליחות בהזמן בהיותי באה \" ק ,\"]\nכתב :\nבשליחות ][ לצדקה\nוכן ע \" פ שידובר בל \" נ בההתועדות\n[ כ \" ק אדמו \" ר שליט \" א צירף שטר של 1000 שקל .\nוראה לקמן מענה קד .]\nקב\nכ \" ף שבט ][\nמענה לא ' שכתב שיש לו קשיים בפרנסה ( ס ' יומן \" רישומה של שנה \" ע '\n147 והעתקה :),\nוארז \" ל טראַכט גוט וועט זיין גוט ."],[9200230055,"55\nמענות קודש – ה ' תשד \" מ\nקג\nועש \" ק משפטים , כ \" ג שבט ][\n\" צעטל \" בכתי \" ק בו ציין כ \" ק אדמו \" ר שליט \" א את הפרש \" י שיתבאר\nבהתועדות ש \" פ משפטים ( ס ' יומן \" רישומה של שנה \" ע ' 142 והעתקה :),\nבל \" נ כג , כו ד \" ה לא : מנ \" ל כיון דלא כתיב ו לא ( ראה מפרשי רש \" י ) 2 )\nהול \" ל אם תעבדני ( ראה מפרשים ) 3 ) קלאץ עפ \" ז למה דווקא\nבארצך !?\"\"\nקד\nשלהי שבט ][\nמענה להרב דוד ראסקין על דו \" ח מביקורו באה \" ק , בו – ע \" פ המענה\nשקיבל ( לעיל מענה קא ) – חזר בכמה מקומות על נקודות מהתועדות ש \" פ\nמשפטים ( ס ' יומן \" רישומה של שנה \" ע ' 146 :)\nנת ' ות \" ח יה \" ר שיהא המשך טוב וכו .'\nקה\nער \" ח אד \" ר ][\nמענה לר ' יעקב יוסף ראסקין שכתב : \" הנני להודיע שבחסד עליון זכיתי\nלבשר לכ \" ק שביום ש \" ק כ \" ד שבט לפני הצהרים בשעת תפלת שחרית\nנולדה בת לנכדי התמים חיים בנציון וזוג ' בתי ' שי ', ובהעלות המנחה נתנו\nלה השם דרויזא , לאריכות ימים ושנים ע \" ש הסבתא ע \" ה ביום ההילולא\nהראשון , והיא תשא רינה ותפלה עבור כל יו \" ח שיחיו . ובתוכם עבור\nהנינה שתאריכי ימים ושנים מתוך בריאות בהתקשרות אמיתי ופנימי\nלבית חיינו שליט \" א , וכולנו תחזינה עינינו בשובך לציון ברחמים וברצון\nלאלתר ממש , משיח נאו \" ( מצילום כתי \" ק – נדפס לעיל . המענה מתפרסם\nבזה לראשונה באדיבות מערכת הספר \" ועבדי דוד \" וזכות הרבים תלוי '\nבהם :)\nויבש \" ט בטוב הנרוהנ \" ג לאויוש \" ט\nנת ' ות \" ח , הפ \" נ יקראו , בל \" נ , עה \" צ ."],[9200230056,"56\nמענות קודש – ה ' תשד \" מ\nק ו\nתחלת אד \" ר ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) בקשר להניגון החדש \" וידעו\nכי אתה גו '\" שהולחן לכבוד יום הבהיר י \" א ניסן – הולחן ע \" י ר ' פייטל\nלוין ומושר בפי ר ' משה טלישבסקי בעיבודו של ר ' אליהו ליפסקר ( ס '\nיומן \" רישומה של שנה \" ע ' 163 ;) ( 2 לתלמידי ישיבת \" אהלי תורה \")\nשהכניסו את הקובץ אהלי תורה \"\" שהו \" ל ( ס ' יומן \" רישומה של שנה \"\nשם ;) (3 ) להנהלת \" צעירי אגודת חב \" ד \" המרכזית על דו \" ח מפעולותיהם\nהאחרונות (\" בית חיינו \" תשד \" מ גליון 8 ;) ( 4 ) לר ' שלום דובער לוין בקשר\nלכרך הכולל את חוברות \" יגדיל תורה \" דשנת תשמ \" ג (\" בית חיינו \" שם ;)\n(5 ) בקשר להדפסת ס ' התניא ברחבי ברזיל (\" בית חיינו \" שם גליון 9 ;) ( 6 )\nל הנהלת \" צעירי אגודת חב \" ד \" במגדל העמק בקשר לכינוס צבאות השם\nשמארגנים ביום פורים קטן (\" כפר חב \" ד \" גליון 136 :])\nנת ' ות \" ח .\nודבר בעתו –\nבחדש אד \" ר – חדש העיבור המשלים שנה זו –\nובסמיכות לפורים קטן , ומפורסם מאמר דא \" ח דפ \" ק שנת פרז \" ת\nוהמעשה הוא העיקר\nאזכיר עה \" צ .\nק ז\nתחלת אד \" ר ][\nמענה לתלמידי ישיבת \" אהלי תורה \" בקשר לקובץ \" אהלי תורה \" שמו \" ל\nלקראת פורים קטן – בהמשך לדברי כ \" ק אדמו \" ר שליט \" א בהתועדויות\nהאחרונות ע \" ד הוצאת קובצי חידושי תורה ( ריש קובץ \" אהלי תורה \"\nחוברת יב . ס ' יומן \" רישומה של שנה \" ע ' 163 :)\n[1 על ההודעה ע \" ד הוצאת הקובץ , כתב :]\nויהא בשטומו \" צ ות \" ח על הבשו \" ט .\n[2 ] במכתבם שאלו האם להדפיס בקובץ את ההדרן על ספר הרמב \" ם\nמשיחת י \" ט כסלו תשל \" ה ( שנדפס בשעתו בקובץ \" הפרדס \" ( תשרי\nתשל \" ו .))"],[9200230057,"57\nמענות קודש – ה ' תשד \" מ\nמענה כ \" ק אדמו \" ר שליט \" א :\nהרי \" ז מתאים בקובץ כללי ולא דמוסד א .'\nקח\nט ' אד \" ר ][\nמענה לא ' ממנהלי מוסדות חב \" ד בארצה \" ב על דו \" ח מנסיעתו לאה \" ק ,\nבו כתב בין השאר : \" דיבר גם עם . . על ענין חברון כי שמע פעם ש . .\nמעוניין בענין חברון , לא אמר לו שום פרטים כ \" א שאולי תהי ' אפשריות\nלעשות משהוא בחברון \" ( מהעתקה . המענה מתפרסם בזה לראשונה\nבאדיבות מערכת ה ספר \" שליחות כהלכתה \" וזכות הרבים תלוי ' בהם :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול קטע זה , וכתב :\nע \" ד חברון – לא לדבר עם הנ \" ל ולא עם אחרים כלל\nח\nקט\nיו \" ד אד \" ר ][\nמענה להמזכיר רחמ \" א חדקוב שכתב : \" נפוצה שמועה אשר כ \" ק אד \" ש\nתומך ברעיון של הדפסת תניא גם בשכונות מיוחדות , כל אחת לעצמה ,\nאף שהעיר בכללותה הדפיסה כבר תניא , ועל סמך הנ \" ל הגיעו כבר\nבקשות - אשור מבארא פארק ומאיסט פלעטבוש , ואיך להתיחס להנ \" ל \"?\n( מצילום כתי \" ק – קונטרס ועד הנחות בלה \" ק ש \" פ וישב תש \" פ :)\nבחיוב –\nבאם באה ההתעוררות מתושבי השכונה שי ' עצמם\nובאם השכונה – נפרדת מהעיר כולה רשמית ( ב ָרא ָא בפ \" ע )"],[9200230058,"58\nמענות קודש – ה ' תשד \" מ\nק י\nיו \" ד אד \" ר ][\nמענה לר ' יונה אבצן שהכניס כרך של שיחות באנגלית , וכתב : \" כרך זה\nשל שיחות באנגליש , כרך י \" ד , הוא כרך ד ' של שנת תשמ \" ב ( כרכים יא -\nיד ). כרך ח ' של שיחות באנגליש , כרך ב ' משנת תשמ \" א , הוא מוכן לדפוס\nוכמו \" כ מוכנים לדפוס ב ' כרכים משנה זו \" \"( English In Sichos\nClassics \" גליון 6 :)\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת התיבות \" מוכן לדפוס \", וכתב :\nעפ \" ז בודאי לפורים\nקי א\nי \" ב אד \" ר ][\nמענה למערכת קובץ הערות התמימים ואנ \" ש מאריסטאון שכתבו :\n\" מצו \" ב התשובות מה שכ \" ק אדמו \" ר שליט \" א הואיל להשיב ( ולתקן ) על\nכמה מהשאלות ששאלו והעירו בגליוננו דש \" פ תצוה ( כא ( שמט .))\nוהננו מתכוננים אי \" ה להדפיסם ולפרסמם בגליון שי \" ל לש \" ק הבעל \" ט .\nובהזדמנות זו , אנו מבקשים את ברכת כ \" ק אדמו \" ר שליט \" א להצלחה\nרבה בעבוה \" ק .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – ס ' \" והאר עינינו בתורתך \"\nע ' קצג :)\nמערכת . . משונה !\nחסר ההמשך הפשוט !! ולא עוד אלא שהקדים כו ' ולא עוד אלא שעיקרו\nכו ' ולא עוד אלא שאין העולם ראוי ' כו '"],[9200230059,"59\nמענות קודש – ה ' תשד \" מ\nקי ב\nי \" ג אד \" ר ][\nמענה למערכת קובץ הערות התמימים ואנ \" ש מאריסטאון שכתבו –\nבהמשך להמענה שקיבלו :\nבנוגע להחילוק דמראות הצובאות וזהב , שכ \" ק אדמו \" ר שליט \" א כתב :\"\n\" חסר ההמשך הפשוט !! ולא עוד אלא שהקדים כו ' ולא עוד אלא שעיקרו\nכו ' ולא עוד אלא שאין העולם ראוי ' כו .\"'\nוכפי שתפסנו כוונת כ \" ק אדמו \" ר שליט \" א היתה שהיינו צריכים לפרש\nהענין יותר , ולכן חושבים אנו להדפיס הענין כזה :\nבגליון הקודם ( כא ( שמט )) אות ד ', העירו על משנ \" ת בענין ה \" ראדיא \"\n[ שיחת ש \" פ משפטים – לקו \" ש חכ \" ו ע ' 381 ] שאף שיכולים לנצלו באופן\nהפכי מרצון ה ', מ \" מ , אין זה מונע מלהשתמש בו לתכלית ומטרת\nבריאתו , עבור עניני קדושה – מפרש \" י ויקהל לח , ח בענין \" מראות\nהצובאות \", שהי ' מואס משה בהן מפני שעשויים ליצה \" ר , וא \" ל הקב \" ה\nקבל כו .'\nוכתב ע \" ז כ \" ק אדמו \" ר שליט \" א : \" היפך דזהב העשוי למשכן ומקדש \"\n[ ראה צילום כתי \" ק – ס ' \" והאר עינינו בתורתך \" שם ע ' קצב .]\nולכאורה הכוונה בזה , דענין \" מראות הצובאות \" ו \" זהב \" – הם שני ענינים\nשונים : מראות הצובאות – עשויים ליצה \" ר ( אלא שאעפ \" כ \" חביבין עלי\nכו ' שעל ידיהם העמידו הנשים צבאות רבות \"); משא \" כ הזהב אינו עשוי\nליצה \" ר \" אלא אדרבה ,\" עיקר בריאתו הוא בשביל המשכן , ולא עוד אלא\nשאין העולם ראוי להשתמש בו כו ' ( שמו \" ר פל \" ה , א ), ומה שהשתמשו בו\nלע \" ז – הוא היפך תכלית בריאתו .\nואותו הדבר הוא בנוגע לה \" ראדיא \" ( כח נעלה בהבריאה ), שעיקרו הוא\nבשביל עניני קדושה , וזהו תכלית בריאתו . ורק שמצד ענין הבחירה אפשר\nלהשתמש בו גם לעניני חול , ואפילו לענינים דהיפך הקדושה – היפך\nתכלית בריאתו , כמבואר בארוכה בהשיחה .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – ס ' \" והאר עינינו בתורתך \"\nע ' קצג :)\n[1 ] על מה שכתבו ( מהמענה דלעיל ): \" חסר ההמשך הפשוט כתב :!!\",\nחסר ההמשך ][ שעניתי כבר לא ' ובפרטים הנ \" ל – אבל גם בלאה \" כ הוא\nפשוט ]!![\n[2 ותיקן את ביאורם בהמענה :]"],[9200230060,"60\nמענות קודש – ה ' תשד \" מ\nולכאורה הכוונה בזה , דענין \" מראות הצובאות \" ו \" זהב \"[ – הם שני\nענינים שונים : מראות הצובאות – עשויים ליצה \" ר ( אלא שאעפ \" כ\n\" חביבין עלי כו ' שעל ידיהם העמידו הנשים צבאות רבות \"); משא \" כ\nהזהב ] שעשייתו – היפך עשיית דמראות הצ אינו עשוי \" ליצה \" ר ]\"[ ולא\nעוד אלא ][ ש אדרבה ,[ עיקר בריאתו הוא בשביל המשכן , ולא עוד אלא\nשאין העולם ראוי להשתמש בו כו ' ( שמו \" ר פל \" ה , א ]) . [ ומה שהשתמשו\nבו לע \" ז – הוא היפך תכלית בריאתו .\nואותו הדבר הוא ] ועד \" ז י \" ל [ בנוגע לה \" ראדיא \" ( כח נעלה בהבריאה ,)\nשעיקרו הוא בשביל עניני קדושה , וזהו תכלית בריאתו . ורק שמצד ענין\nהבחירה אפשר להשתמש בו גם לעניני חול , ואפילו לענינים דהיפך\nהקדושה – היפך תכלית בריאתו , כמבואר בארוכה בהשיחה ].\nקי ג\nלאחר ש \" פ תשא , שושן פורים קטן ][\nמענה למערכת קובץ הערות וביאורים אהלי תורה שכתבו :\n\" הננו רוצים להכניס קטע דלהלן מהתועדות דש \" פ תשא , שושן פורים\nקטן בענין \" עד מתי \" ( דכתבו עד \" ז בהערות וביאורים דשבוע העבר )\nבגליון דש \" פ ויקהל .\nבהשיחה נאמר פתגם כ \" ק אדמו \" ר מהוריי \" צ דמ \" ש \" אנו אין לנו להשען\nאלא על אבינו שבשמים \" זה גופא הוא מהסימנים דעקבתא דמשיחא .\nוהודגש הענין \" אין . . אלא .\"\nאבל במשנה שלפנינו : \" על מה יש לנו להשען על אבינו שבשמים .\"\nובעין יעקב : \" על מי [ יש ] לנו להשען ( אלא ) על אבינו שבשמים \". ובס '\nהשיחות תש \" ב ע ' 17 ששם הובאה פתגם הנ \" ל : \" אנו אין לנו להשען אלא\nעל אבינו שבשמים .\"\nבהשיחה דלהלן מועתק כמ \" ש בע \" י .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – ס ' היובל הערות\nוביאורים ע ' רעז :)\nסימן בעיגול את מה שכתבו : \" בהשיחה נאמר . . אבל במשנה שלפנינו\nכו '\", וכתב :\nכמדובר כבר שקו \" ט בזה\nובטח גם נרשם"],[9200230061,"61\nמענות קודש – ה ' תשד \" מ\nקי ד\nלאחר ש \" פ תשא , שושן פורים קטן ][\nמענה לר ' אהרן חיטריק שכתב – בהמשך להמדובר בהתועדות ש \" פ תשא\nבקשר להוצאה החדשה של ה \" לקוטי תורה \" בתוס ' ציונים ומ \" מ ; ובין\nהשאר דובר ע \" ד המ \" מ הראשון : \" ראו כי : נאמרה בשנת תקס \" ה – ראה\nאוה \" ת משפטים ע ' ג ' טז : ביאור ע \" פ ראו . . בשלח תקס \" ה . היום יום ע '\nכ \"; ובהתועדות נאמר על זה , אשר : \" בענין הראשון שמציינים למקומות\nנוספים בדא \" ח שבהם מבואר ענין זה – עיינתי במקום המצויין , ולא\nמצאתי דבר ! ובודאי נפלה טעות כו :\"'\n\" בעת ההתועדות הזכיר כ \" ק שיש ט \" ס בהערה הראשונה בהמראי\nמקומות בלקו \" ת . עברתי על המראה מקום ולא הבנתי מה הטעות .\nהכוונה שם הוא שבאוה \" ת משפטים ע ' ג ' טז נזכר שמאמר זה הוא מש \" פ\nבשלח תקס \" ה . וכן בהיום יום .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה גראס ט \" ז אלול\nתש \" ס :)\nסימן בעיגול את התיבות \" ולא הבנתי מה הטעות \", וכתב :\n!!?? ( 1 ) כשכותבים \" ראה אוה \" ת \" ( ולא סתם – אוה \" ת \") פי '\" שאין\nזה מ \" מ ( לחוד .)\n2 ) : . . ביאור ע \" פ . . ( ולא במירכאות – ) היינו שיש שם ד \" ה ביאור . .\n3 ) תיבה הא ' – נאמרה – במקום נאמר\n( כנראה – כוונתו לתיבת \". . תורה \"! היפך דהשער : ליקוטי . . ליקוטי\nאמרים . . והיפך דל ' \" היום יום .\" ועוד .\n– והשם לקו \" ת ( שצ \" ל תורות – לשיטת ו זו ) הוא כבל \" ת להאריז \" ל –\nלקוטי פי ' בתורה ( ולאח \" ז – בנ \" ך בדהאריז \" ל וכאן \" ועל ג ' רגלים )\"\nק טו\nמוצש \" ק תשא , שושן פורים קטן ][\nמענה לא ' התמימים על בקשת ברכה לרפואה שלימה עבור מישהו\n( מהעתקה . המענה מתפרסם בזה לראשונה באדיבות הנמען שי ' וזכות\nהרבים תלוי ' בו :)\nאזכיר על הציון"],[9200230062,"62\nמענות קודש – ה ' תשד \" מ\nקט ז\nאד \" ר ][\nמענה לר ' מנחם וואלף על מכתבו ( להמזכיר ריב \" ק ) בו כתב : \" טוביה פלס\nהעובד בתנועה הקיבוצית של השומר הצעיר – בניהול חשבונות , העלה\nרעיון ( שמקוה הוא בקשריו שיוכל גם לבצע ) להציע להנהלה שיסכימו\nלהדפיס בקבוצים תניא ' ס . מאחר ובאם זה יוכל להתבצע בע \" ה , הוא\nשואל בעקרון אם מסכימים לזה . ובאם כן האם צריך אשור לכל קבוץ\nבנפרד – או הסכמה כללית לכל הקבוצים שהם יאפשרו . באם יהי ' מענה\nנא תודיע \" ( מצילום כתי \" ק – ס ' \" ימי תמימים \" ח \" ח ע ' 252 :)\nמקה \" ת\nבכלל – להשתדל באופן המתאים )(\nבאם גם ילמדו בהתניא ( כמדובר בהשיחה ) עכ \" פ יתחילו – כדאי ביותר\nק יז\nאד \" ר ][\nמענה ליהודי מרוסיא ששאל האם להניח תפלין , וכתב שמה שיורה לו\nכ \" ק אדמו \" ר שליט \" א יעשה ( ס ' יומן \" רישומה של שנה \" ע ' 163-4 :)\nכפשוט , וה ' יצליחו .\nקי ח\nאד \" ר ][\nמענה לר ' ישראל דוד נחשון שהכניס את המפתח ל \" טנק \" הששי של\nניידות חב \" ד באה \" ק \" ( ס ' \" רישומה של שנה \" ע '\" 164 :)\nת \" ח ות \" ח ."],[9200230063,"63\nמענות קודש – ה ' תשד \" מ\nקי ט\nאד \" ר ][\nמענה ליהודי תושב תל - אביב שכתב שפתח בית - כנסת חדש ( ס ' יומן\nרישומה של שנה \" ע '\" 164 :)\nנת ' ות \" ח בסמיכות לפורים קטן , מצורף השתתפות בעניני ביהכנ \" ס\n100 דולאר אזכיר עה \" צ לכל הנ \" ל .\nקכ\nאד \" ר ][\nמענה להרב אברהם יצחק נרי ' שהכניס חידושי תורה שלו במהלך ביקורו\nבחצרות קדשנו ( ס ' יומן \" רישומה של שנה \" ע ' 164 :)\nנת ' ות \" ח ויישר חילו לאורייתא . מצו \" ב לצדקה באה \" ק . אזכיר עה \" צ .\n[ כ \" ק אדמו \" ר שליט \" א צירף 500 שקל עבורו ו - 500 שקל עבור זוגתו .]\nקכ א\nאד \" ר ][\nמענה לר ' שמואל הלוי הורביץ על מכתבו בקשר לקיצור דיני פסח שמו \" ל ,\nבו ציין שעברו על החומר מספר רבנים ( ריש ס ' \" שבח המועדים \". ס ' יומן\nרישומה של שנה \" ע '\" 165 :)\nבכלל – נכון וטוב וכו ,' בפרט – שייך לדעת הרבנים שליט \" א הנ \" ל .\nאזכיר עה \" צ .\n[ כן סימן בקו ובחץ כמה תיבות במכתבו ע \" ד ( חשיבות ) ההו \" ל בהקדם\nהאפשרי .]"],[9200230064,"64\nמענות קודש – ה ' תשד \" מ\nקכ ב\nאד \" ר ][\nמענה להנהלת \" צבאות השם \" ששאלו האם לערוך את תוכנית \" Pesach\nExperience \" (\" חוויות הפסח \") פה בשכונת קראונהייטס או במקום\nאחר ( ס ' יומן \" רישומה של שנה \" ע ' 165 :)\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת תיבת \" פה \", וכתב :\nכמפורסמת דעתי בזה ולפלא הכי גדול הספק\nאזכיר עה \" צ\nקכ ג\nאד \" ר ][\nמענה לר ' ישראל גאלדשטיין מנהל פעילות \" צבאות השם \" בלונג איילנד\nשכתב ע \" ד רעיון הדפסת ס ' התניא בלונג איילנד לזכות אחת המשתתפות\nבפעילות שאינה בקו הבריאות (\" כפר חב \" ד \" גליון 134 :)\nכ \" ק אדמו \" ר שליט \" א סימן קו תחת מה שכתב ע \" ד הדפסת ס ' התניא ,\nוכתב :\nאעה \" צ .\nקכ ד\nאד \" ר ][\nמענה לר ' ישראל גאלדשטיין על דו \" ח מהדפסת ס ' התניא בלונג איילנד\n(\" כפר חב \" ד \" גליון 134 :)\nכן יבשר בשורות טובות כל הימים . אעה \" צ ."],[9200230065,"65\nמענות קודש – ה ' תשד \" מ\nקכ ה\nאד \" ר ][\nמענה לא ' מאנ \" ש על מכתבו – בהמשך להשאלות ששאל כ \" ק אדמו \" ר\nשליט \" א בהתועדות ש \" פ בא , עה \" פ \" ולכל בנ \" י לא יחרץ כלב גו '\" דכלבים\nמאן דכר שמי ', והשאיר את השאלות לעיון המשתתפים בהתועדות –\nדי \" ל שהוא כיון שבנ \" י שחטו הפסח ובמילא הי ' אצלם בשר בשופי , ולא\nיכלו לתת להכלבים הנותר מפני הציווי \" והנותר ממנו עד בוקר באש\nתשרופו \" ( ס ' \" והאר עינינו בתורתך \" ע ' רמח :)\nאודות המדובר בלא יחרץ כלב גו ' –\nאבל בפשוטו של מקרא – החידוש ( גם ) הוא אע \" פ שהייתה מכת בכורות\n( ולא – שחיטת הפסח .)\nוזהו מובן – כי לא יחרץ גו ' מדובר מחצות הלילה ואילך , ושחיטה\nהאמורה הייתה בין הערביים .\nולהעיר אשר ע \" י קרבן הפסח – סיבה שלא יחרץ כלב ע \" פ טבע , כי\nלאחרי אכילתו ( היינו – באמצע הלילה ) ועצם לא תשברו בו , ומושלכים\n( גם ) לכלבים ומתעסקים בעצמות , ופשיטא שלא יחרוץ לשונו . וראה\nזח \" ב מא , ב .\nקכ ו\nאור לכ \" ף אד \" ר ][\nמענה לר ' צבי מאיר שטיינמעץ על דו \" ח מהתפתחות הענינים בהנהלת\nתנועת \" פועלי אגודת ישראל \" ( תשורה זלמנוב כ \" ד סיון תשע \" א :)\n[1 על כללות הדו \" ח , כתב :]\nנת ' ות \" ח ת \" ח\n[2 ] במכתבו כתב : \" והנה אחרי כל הנאמר נפשי בשאלתי , בתנאים\nהחדשים , מהי חוו \" ד כ \" ק אד \" ש אם יש עוד תועלת בהמשך השתתפותי\nבווה \" פ של פא \" י .\"\nכ \" ק אדמו \" ר שליט \" א מחק תיבת \" אם \" וסימן קו תחת התיבות \" יש\nעוד \", וכתב :\nכמובן ופשוט"],[9200230066,"66\nמענות קודש – ה ' תשד \" מ\nנת ' ות \" ח\nאזכיר על הציון\nקכ ז\nכ \" ף אד \" ר ][\nמענה לא ' השלוחים ששאל האם להתעניין לעבור למקום אחר , או\nלהמשיך במקומו בעניני עיסוקיו השונים ( מהעתקה . המענה מתפרסם\nבזה לראשונה באדיבות א ' מאנ \" ש שי ' וזכות הרבים תלוי ' בו :)\n[1 מחק את הצעת המקום האחר , וכתב :]\nלהמשיך ב .[ ]. כפשוט\n[2 בקשר לפרטי עיסוקיו במקומו , כתב :]\nבהתייעצות עם ידידים מאנ \" ש יחיו\nקכ ח\nכ \" ג אד \" ר ][\nמענה להרב ארי ' אלברט מזכיר מערכת עיתון \" שערים \" היו \" ל באה \" ק\nס ' \" רישומה של שנה \" ע '( 164 :)\nבקשר לתיבת \" מזכיר \" שבמכתבו , כתב :\nכדאי להחזיר פי ' תואר ( תפקיד ) זה ליושנה – להזכיר את כל המערכת\nע \" ד תפקידם הכללי – לשמש עוד יותר את קונם ,\nוהפרטי – שה \" שערים \" יהיו הכשרה ל \" שער השמים .\"\nאזכיר עה \" צ .\nלצדקה שם ."],[9200230067,"67\nמענות קודש – ה ' תשד \" מ\nקכ ט\nכ \" ה אד \" ר ][\nמענה למערכת קובץ הערות התמימים ואנ \" ש מאריסטאון שכתבו :\n\" בגליוננו ( הערות הת ' ואנ \" ש דמאריסטאון ) שי \" ל לש \" פ תצוה ( כא\n( שמט )) נדפס בדעת הזהר דעשיית המשכן הי ' לפני חטא העגל , והואיל\nכ \" ק אדמו \" ר שליט \" א להגיה שם \" נדבת \" במקום \" עשיית \" [ ראה צילום\nכתי \" ק – ס ' \" והאר עינינו בתורתך \" שם ע ' קצו .]\nמצו \" ב העתק מלקו \" ש ח \" ג שיחה לפ ' פקודי , ושם בהערה 13 וז \" ל : \" ובזה\nיתורץ מה שהפסיק בפ ' תשא בין פ ' תרומה ותצוה לפ ' ויקהל פקודי\nלהדיעה ( זוהר פ ' פקודי רכד , א ) שמעשה העגל הי ' אחרי עשיית המשכן .\"\nעכ \" ל .\nועפ \" י הגהת כ \" ק אדמו \" ר שליט \" א הי ' לכאורה צריך להגיה גם שם\nנדבת \" במקום \" עשיית .\"\"\nאמנם עפ \" י הגהה זו יוקשה עצם הענין שם , דהביאור שבהשיחה שם הוא ,\nדלאחרי שיצא הציווי לפועל למטה א \" א לשום ענין ליכנס ולמנוע בינו\nלבין הבאתו לפועל – כמבואר שם בהוראת החיבור דפ ' ויקה \" פ – . דלפי\nההגהה שעשיית העגל הי ' לאחרי ( ציווי משה ו ) נדבת המשכן וקודם\nעשייתו , הרי נמצא דלא כנ \" ל .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – ס ' \" והאר עינינו בתורתך \"\nע ' קצז :)\n[1 ] על מה שכתבו : \" והואיל כ \" ק אדמו \" ר שליט \" א להגיה שם \" נדבת \"\nבמקום \" עשיית \"\", כתב :\n\" וחדשתי \" שכן מפורש בס \" פ פקודי ( 1)\n[2 ] על מה שכתבו : \" הי ' לכאורה צריך להגיה גם שם \" נדבת \" במקום\nעשיית \"\" – מחק תיבת \" לכאורה \", וכתב :\nמזה תוס ' ראי ' להנאמר ע \" ד \" גודל ההתענינות \" בהלקו \" ש – שבמשך\n20 שנה – לא הי ' אף א ' שראה הנ \" ל ( 2 )\n[3 ] על מה שכתבו : \" דלפי ההגהה שעשיית העגל הי ' לאחרי ( ציווי משה\nו ) נדבת המשכן וקודם עשייתו \" – אחר התיבות \" ציווי משה \", כתב :\nשבו נאמר ושכנתי בתוכם ( – היינו וכבוד ה ' מלא אה \" מ ) –"],[9200230068,"68\nמענות קודש – ה ' תשד \" מ\n[4 סימן בעיגול את מה שכתבו : \" הרי נמצא דלא כנ \" ל \", וכתב :]\n!!?? ( 4)\nלהחזיר המצו \" ב\nקל\nלפני חודש אד \" ש ][\nמענה ל מ ערכת עיתון \" משיח טיימס \" היו \" ל ע \" י \" צבאות השם \" שהכניסו\nאת שער העיתון ד חודש אד \" ש שעליו ציור בו נראים ילדים מחופשים\nמקיימים את מצות משלוח מנות ( תשורה התועדות חסידים אור לועש \" ק\nשמיני תשנ \" ה :)\nלהוסיף כפשוט כו \" כ המן טאַש גראַגער\nקל א\nבדר \" ח אד \" ש ][\nמענה להנהלת \" נשי ובנות חב \" ד \" על ההודעה ע \" ד הכינוס שלהן ( ס ' יומן\nרישומה של שנה \" ע '\" 183. תשורה וויינפעלד כ \" ח סיון תשע \" ח .\nוהעתקה :)\nבטח נוהגין בכל פגישה כיו \" ב – שכאו \" א יקבל ( סמוך להגמר ) משהוא\nלמזכרת לקחת לביתו ולמקומו . וק \" ל .\nת \" ח על הבשו \" ט הנ \" ל כן תבש \" ט ע \" ד כהנ \" ל מההצלחה עוד יותר\nמהמשוער , וכפס \" ד רז \" ל דמרבין בשמחה ( ובמילא – בסביבותי )'\nאזכיר עה \" צ"],[9200230069,"69\nמענות קודש – ה ' תשד \" מ\nקל ב\nתחלת אד \" ש ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) להנהלת \" צעירי אגודת\nחב \" ד \" המרכזית על דו \" ח פעולותיהם ( ס ' יומן \" רישומה של שנה \" ע '\n183 ;) ( 2 ) ל \" ועד המחנכים \" על דו \" ח פעולותיהם ( ס ' יומן \" רישומה של\nשנה \" שם ;) (3 ) לר ' שמואל הלוי הורביץ שהכניס את קובץ קיצור דיני\nפסח שהו \" ל ( ריש ס ' \" שבח המועדים :])\nנת ' ות \" ח .\nודבר בעתו –\nבסמיכות לר \" ח אד \" ש ונקודתו פורים אשר ליהודים הייתה אורה\nושמחה וששון ויקר – כפשוטו , וככל דחז \" ל בזה –\nכן תהי ' לנו .\nאזכיר עה \" צ .\nקל ג\nתחלת אד \" ש ][\nמענה לר ' מנחם מענדל הכהן פלדמן על ההודעה ע \" ד עריכת התועדות\nחסידים ביום ט ' אד \" ש ב - 770 ס ' יומן \" רישומה של שנה \" ע '( 169 :)\nויה \" ר שיהא בהצלחה רבה . אזכיר עה \" צ .\nקל ד\nז ' אד \" ש ][\nמענה להשליח ר ' שמואל פרומר ( תשורה הלפרין כ \" ד סיון תשע \" ח :)\nימסרו לו בשמי שקודם נסיעתי להציון הקדוש ,\nהנני מוסר לו שליחות לחלק לצדקה בשליחותי בימי הפורים ח \" י אלף\nשקלים לח \" י אביונים באה \" ק .\nסכום זה יקבל אצל הרב אפרים וולף שיחי .'"],[9200230070,"70\nמענות קודש – ה ' תשד \" מ\nקל ה\nלאחר ש \" פ צו , י \" ג אד \" ש ][\nמענה ל \" ועד הנחות בלה \" ק \" על שאלתם בשיחת ש \" פ צו ( מצילום כתי \" ק\n– תשורה נאגל ל \" ג בעומר תשנ \" ז :)\nא . במכתבם כתבו : \" בפירש \" י צו ז , טו : מכיון שכל המקור ל \" אמרו עד\nחצות \" הוא מפסוק זה גופא – הוה לי ' לרש \" י לכתוב \" מיכן אמרו \"\n( וכיו \" ב ), ולמה כותב \" למה אמרו כו '\" שמלשון זה משמע לכאורה\nד \" אמרו עד חצות \" הוא דבר ידוע ( שהרי כשמקשים \" למה אמרו \" משמע\nשהבן חמש למקרא יודע ש \" אמרו \", והקושיא היא \" למה אמרו .\")\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n[1 ] סימן בעיגול את מה שכתבו : \" שכל המקור ל \" אמרו עד חצות \" הוא\nמפסוק זה גופא \", וכתב :\nלא זה אמרתי – כ \" א מה מכריח רש \" י לפרש זה כאן\n[2 ] על מה שכתבו : \" שהרי כשמקשים \" למה אמרו \" משמע שהבן חמש\nלמקרא יודע ש \" אמרו \", והקושיא היא \" למה אמרו \"\", כתב :\nהזכרתי \" בדא \" פ מהנהגת לילה בהסדר \"\nב . במכתבם כתבו : \" במה שנתבאר בהשיחה בענין \" חכמים \" ו \" סופרים \"\n– גם בפירש \" י בשלח ( טז , כט ד \" ה שבו איש תחתיו ) \" מכאן סמכו חכמים\nד ' אמות ליוצא חוץ לתחום \". ואולי יש לומר , דענין תחומין ( בכלל ) –\nמכיון שאינו מצד סייג ( שנוגע לחכמה , לשער תכונות האדם ), לכן שייך\nל \" סופרים \" ולא ל \" חכמים \", כמשנ \" ת בהשיחה . משא \" כ השיעור ד ' אמות\n– מכיון שהטעם הוא \" ג ' לגופו וא ' לפישוט ידים ורגלים \" ( פירש \" י שם ,)\nלכן שייך זה ל \" חכמים \" שהם יודעים לשער מדת גוף האדם . וגם : הענין\nשהאמה שצריך לפישוט ידים ורגלים נכלל ב \" תחתיו \", גם זה ענין ששייך\nלידיעת תכונת האדם ( שכאשר אינו יכול לפשוט כו ' הוה זה חסרון כו ,'\nולכן גם האמה היתירה נכלל ב \" תחתיו \"), חכמה . אם נכון .\"?\nמענה כ \" ק אדמו \" ר שליט \" א :\n[3 ] סימן בעיגול את התיבות : \"\" חכמים \" שהם יודעים לשער מדת גוף\nהאדם \", וכתב :\nמהי החכמה בזה !?"],[9200230071,"71\nמענות קודש – ה ' תשד \" מ\n[4 על כללות הקטע , כתב :]\nהרי הזכרתי בפי ' בפירש \" י בשלח ( טז , כט ])[ – כי היתר [ ד ' אמות ליוצא\nחוץ לתחום ] תלוי בהשערת טבע האדם כי אא \" פ להתצמצם ולהתעכב\nעל עמדו ממש\nג . במכתבם כתבו : \" הלשון \" מדברי סופרים \" כותב רש \" י גם בפ ' תשא\n( לד , כו ) בענין בשר עוף בחלב , והנה בנוגע לעצם הענין ( בשביל מה כותב\nזה רש \" י בפירושו עה \" ת ) – נתבאר כבר בלקו \" ש ח \" ו ע ' 208 שיש הכרח\nעל זה מלשון הפסוק . אבל לכאורה צריך ביאור : הרי האיסור דבשר עוף\nבחלב הוא לכאורה מצד סייג – וא \" כ , למה אומר \" סופרים \" ולא\nחכמים .\"?\"\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n[5 ] על מה שכתבו : \" הרי האיסור דבשר עוף בחלב הוא לכאורה מצד\nסייג \", כתב :\nא \" כ הי ' צ \" ל אסור בודאי ולא פי ' רש \" י ( בפ ' ראה !!)\n[6 על מה שכתבו : \" וא \" כ , למה אומר \" סופרים \" ולא \" חכמים \"?\", כתב :]\nאולי קשור עם קלאָץ ענין מבהיל – שלא מצאתי לע \" ע איש משים לב\nלזה ( והם בכלל , כרגילותם :) בהג \" פ מדשתק רש \" י משמע דס \" ל דרק\nבחלב אמו אסור !! ובפרט שפעמיים פי ' שגדי לאו דוקא\nקל ו\nט \" ו אד \" ש , שושן פורים ][\nמענה לר ' שלום דובער לוין שכתב : \" מצו \" ב עלי ההגהה של ההערות\nלאגרות - קודש [ אדמו \" ר מהריי \" ץ ] חלק תשיעי . חלק שמיני כבר מוכן\nלדפוס , ועדיין לא נתקבל האישור . כיון שאיני יודע הטעם לזה , האם\nלהמשיך בעריכת ח \" ט וח \" י כרגיל ?\" ( מצילום כתי \" ק – תשורה מונדשיין\nי \" ז כסלו תשס \" ח :)\n[1] מחק תיבת \" האם \" וסימן - השאלה , וסימן בעיגול ובחץ את התיבות\nלהמשיך בעריכת ח \" ט וח \" י כרגיל .\"\"\n[2 וכתב :]\nהמזרז כדרוש ע \" ד הס ' דשו \" ע אדה \" ז –\nוכבר למחר ל ' יום דלפני החג כו '\nמהיר"],[9200230072,"72\nמענות קודש – ה ' תשד \" מ\nקל ז\nאד \" ש ][\nמענה לר ' שלום דובער לוין שכתב – בהמשך להמענה שקיבל ע \" ד זירוז\nהו \" ל הספר על שו \" ע אדה \" ז – שדיבר על כך עם ר ' יהושע מונדשיין שאמר\nשעוסק עתה בה \" מבוא \", ועם הסידור בדפוס מתרחבת היריעה בהוספות\nוהערות ( מצילום כתי \" ק – תשורה מונדשיין י \" ז כסלו תשס \" ח :)\nפשוט שכתבי ש ( חשש ) כן יהי ' לפני כו \" כ חדשים , לא הייתה כדי\nלהגיד העת \" ל \"\"\nכ \" א בשביל לעשות – שלא יהי ' כן לעת \" ל\nמהיר\nקל ח\nאד \" ש ][\nמענה לר ' שלום דובער לוין שכתב – בהמשך להמענות ע \" ד זירוז הו \" ל\nהספר על שו \" ע אדה \" ז – אשר ר ' יהושע מונדשיין מציע שאולי כדאי\nלהדפיס את הספר לקראת יום הבהיר י \" א ניסן בלי ה \" מבוא \", ואח \" כ\nלהשלים ( מצילום כתי \" ק – תשורה מונדשיין י \" ז כסלו תשס \" ח :)\nתלוי ב \" גדרו \" של קהת – הַאם חל על קה \" ת מחז \" ל דחבר אינו מוציא\nמתח \" י דבר שאינו מתוקן\nקל ט\nאד \" ש ][\nמענה לר ' שלום דובער לוין שכתב – בהמשך להמענות ע \" ד זירוז הו \" ל\nהספר על שו \" ע אדה \" ז :\n\" טלפנתי עתה להר \" י שי ' מונדשיין ואמרתי לו , שיהי ' מה צריך להיות\nהספר כרוך לפני י \" א ניסן , ובאם אי אפשרי הדבר , אזי נאלץ לקחת אחת\nמהרשימות הקיימות כבר – בהוספות לשו \" ע אדה \" ז , ס ' הק \" ן וס '\nהתולדות אדה \" ז ( אף שרשימות אלו משובשות ובלתי מושלמות ), להוסיף\nעליהן צילומי השערים ולהדפיסן בקונ ' בפ \" ע ."],[9200230073,"73\nמענות קודש – ה ' תשד \" מ\nוע \" ז השיב , שהאפשרות היחידה שיהי ' הס ' כרוך לפני י \" א ניסן הוא : א )\nשלא יכנס בו מבוא , שעדיין לא סיים . ב ) לא יכנסו בו המחקרים בקשר\nלשינויי הצנזור , שעדיין לא סיים . ג ) לא יכנסו בו המחקרים בקשר\nלמחברי המ \" מ שעה \" ג , שעדיין לא סיים . ד ) שיקח חופש לשבוע מעבודתו\nבספריה ( שיקבל תשלום מקה \" ת ) ויסיים עריכה סופית וההגהה . וישאר\nשבוע להדפסה וכריכה – לאחר שיצא לגמרי מידיו .\"\nמענה כ \" ק אדמו \" ר שליט \" א ( מצילום כתי \" ק – תשורה מונדשיין י \" ז\nכסלו תשס \" ח :)\nבאם עכ \" פ בחודש ניסן יהי ' כהנ \" ל בשלימות – בלית ברירה להסכים\nעל ההארכה הזו\nמהיר\nקמ\nאד \" ש ][\nמענה להמתעסקים בהכנה לדפוס דמאמרים הבודדים דאדמו \" ר\nמהרש \" ב שהגיעו לאחר הדפסת ספרי המאמרים אליו שייכים ( מצילום\nכתי \" ק – \" בית משיח \" גליון 35 :)\nכ \" ק אדמו \" ר שליט \" א אישר את השם \" ספר המאמרים ליקוט \", וכתב :\nלחכות אולי יתוסף עוד עד כהאפשרי שיוכלו ללמוד בזה אור לב ' ניסן\nקמ א\nאד \" ש ][\nמענה כללי - פרטי דימים אלו [ בין השאר : ( 1 ) להשליח ר ' יהודה ליב\nראסקין שהכניס את ס ' התניא שנדפס במקנס מרוקו ( ס ' יומן \" רישומה\nשל שנה \" ע ' 185 . וראה לקמן מענה קמ ז ;) ( 2 ) להשליח ר ' שלום יעקב חזן\nעל דו \" ח מפעולות בית חב \" ד רסיפה ברזיל בחג הפורים , וכן ע \" ד התחלת\nבניית המקוה (\" בית משיח \" גליון 920 ;) ( 3 ) לר ' שלום דובער פרידמן\nשהכניס ספרי תניא שנדפסו ב ערים וונציא , בולוניא , פ י רנצא (\" בית\nחיינו \" תשד \" מ גליון 11 ;) ( 4 להרב דוד ראסקין על דו \" ח מ \" מבצע פורים \")\nכולל בבתי - אסורים (\" בית חיינו \" שם ;) ( 5 ) להשליח ר ' אברהם קארף על\nמכתבו ( מהעתקה , באדיבות א ' מאנ \" ש שי :])'"],[9200230074,"74\nמענות קודש – ה ' תשד \" מ\nנת ' ות \" ח .\nודבר בעתו –\nבסמיכות לימי הפורים אשר ליהודים הייתה אורה ושמחה וששון ויקר\n– כפשוטו , וככל דחז \" ל בזה –\nכן תהי ' לנו .\nאזכיר עה \" צ .\nקמ ב\nאד \" ש ][\nמענה לא ' שכתב שסובל מדי - פעם בפתאומיות מפחדים ובכיות ( ס ' יומן\nרישומה של שנה \" ע '\" 184 :)\nבאם לא נבדקו במשך י \" ב חדש האחרונים , לבדוק התפילין והמזוזות .\nוכעצת רב מורה הוראה דעדתו .\nאזכיר עה \" צ .\nקמ ג\nאד \" ש ][\nמענה למשפחה שביקשו ברכה בקשר להעתקת מקום מגוריהם מניו\nיארק לפלארידא ( ס ' יומן \" רישומה של שנה \" ע ' 184 :)\nהעתקת מקום בשמירת שבת ויום טוב , יהי משנה מקום משנה מזל\nלטובה ולברכה .\nקמ ד\nאד \" ש ][\nמענה להרב יצחק דוד גרוסמן על מכתבו בקשר ל \" דינר \" שעורך בקרוב\nלטובת רשת המוסדות \" מגדל אור \" שבניהולו . זמן קצר לפני כן הודפס\nס ' התניא בעיר מגדל - העמק בסיועו של הנמען מרא דאתרא ( ס ' יומן\nרישומה של שנה \" ע '\" 184 :)\nיהא בשעטומו \" צ וזכות הדפסת ס ' התניא וכו ' יעמוד , אזכיר עה \" צ ."],[9200230075,"75\nמענות קודש – ה ' תשד \" מ\nקמ ה\nאד \" ש ][\nמענה להשליח ר ' לוי וילימובסקי מנהל בית חב \" ד חולון אה \" ק על דו \" ח\nמפעולותיו ותכניותיו ( ס ' יומן \" רישומה של שנה \" ע ' 185 :)\n1 ) כמובן כעצת עסקני אנ \" ש שיחי ' באה \" ק\n2 דו \" ח ופ \" נ נת ' ות \" ח ת \" ח והמצו \" ב ודבר בעתו וכו .')\nמצו \" ב לצדקה שם .\nכן יבקש משקה בהתוועדות .\n[ כ \" ק אדמו \" ר שליט \" א צירף 118 שקל לצדקה באה \" ק , ו - 200 דולר\nכהשתתפות בחובות בית חב \" ד ]\nקמ ו\nאד \" ש ][\nמענה ליהודי תושב צרפת שביקש ברכה עבור זוגתו החולה במחלה בדם\nס ' יומן \" רישומה של שנה \" ע '( 185 :)\nדיוק בכשרות האכילה ושתי .'\nאעה \" צ .\n[ כ \" ק אדמו \" ר שליט \" א צירף 11 דולר .]\nקמ ז\nאד \" ש ][\nמענה להשליח ר ' יהודה ליב ראסקין שהכניס את ס ' התניא שנדפס\nבמקנס מרוקו ( ס ' יומן \" רישומה של שנה \" ע ' 185 :)\nמצורף 20 דולאר\nוצירף את המענה כללי - פרטי דימים אלו ( לעיל מענה קמ א .)"],[9200230076,"76\nמענות קודש – ה ' תשד \" מ\nקמ ח\nאד \" ש ][\nמענה להשליח ר ' יהודה ליב ראסקין על דו \" ח ואלבום תמונות ממחנה -\nהחורף במרוקו , ומהפעולות בעניני כ \" ק אדמו \" ר שליט \" א בעיר מקנס ( ס '\nיומן \" רישומה של שנה \" ע ' 185 תשורה ראסקין כ \" ט טבת תשנ \" ט :).\nהדו \" ח וכל המצו \" ב והאלבום נת ' ות \" ח כן יבש \" ט תכה \" י .\nקמ ט\nאד \" ש ][\nמענה להשליח ר ' יהודה ליב ראסקין שהכניס תמונות משיעור התניא\nבעיר מקנס מרוקו שנכחו בו מאות אנשים ( ס ' יומן \" רישומה של שנה \"\nע ' 185 :)\nנת ' ות \" ח ת \" ח אזכיר עה \" צ . ויבש \" ט .\nק נ\nאד \" ש ][\nמענה לא ' שביקש ברכה עבור אחד החולה במחלה נדירה ומאושפז בבית\nהרופאים ( ס ' יומן \" רישומה של שנה \" ע ' 186 :)\nבדיקת התפילין ( בפרט של יד ) והמז '. דיוק בכשרות האכו \" ש , אזכיר\nעה \" צ .\nקנ א\nאד \" ש ][\nמענה לא ' מאנ \" ש ( ס ' יומן \" רישומה של שנה \" ע ' 186 :)\nהוספה בבטחון ובמילא בשמחה , אעה \" צ ."],[9200230077,"77\nמענות קודש – ה ' תשד \" מ\nקנ ב\nאד \" ש ][\nמענה לאיש - תקשורת מאה \" ק שכתב מספר שאלות , ובין השאר שאל\nמדוע אין כ \" ק אדמו \" ר שליט \" א עולה לאה \" ק . בתוך הדברים ציין גם\nשהוא רואה עצמו כיהודי חילוני ( ס ' יומן \" רישומה של שנה \" ע ' 186 :)\n.[ ]. כל איש ישר הולך ושנראה לו שיכול לעשות משהו לזולתו – עליו\nהחובה להיות נמצא במקום שיכול למלאות הנ \" ל ובמידה הכי גדולה\nולא במקום שנוח לו יותר .\nבעת מ \" ת גזר בורא העולם וכל אשר בו – ואתם תהיו לי ממלכת כהנים\nוגוי קדוש ומאז בטלה מציאות דיהודי חילוני , אלא שנתן השם הבחירה\nלאדם : המתנהג יומית ו \" אוכל \" רק \" מאכלים \" בריאים המחזקים אותו\nבגו \" ר , או ש \" אוכל \" גם \" מאכלים \" מזיקים בכל – כיון שמכוסים\nב \" שכבת סוכר \", וד \" ל .\nקנ ג\nאד \" ש ][\nמענה ליהודי תושב מאנטרעאל קנדה (\" בית חיינו \" תשד \" מ גליון 14 :)\nילמוד ס ' חוה \" ל ש ' הבטחון , ועוד וג \" ז טוב ונכון ילַמדו לאחרים . ( הספר\nמועתק לאנגלית .)\nקנ ד\nאד \" ש ][\nמענה למרת טעמא גורארי ' בקשר לספר \" אורה \" שמו \" ל בקשר לנשי\nישראל ( תשורה וויינפעלד כ \" ח סיון תשע \" ח והעתקה :),\nעל מה שכתבה : \" מה שמשפיע עלי קשה הוא הלחץ בזמן \", כתב :\n!? – כשהענין \" אורה \" והזמן \" אדר \" – ה \" ז עפ \" י פס \" ד תורתנו , השפעה\nשל אורה ודריבוי בשמחה וזירוז והקשה שבדבר הוא ( כמדובר לאחרונה\nכמה פעמים ) – קושי המשא של כפליים דאב \" ט ומרגליות . ואשרי\nחלקן .\nאזכיר עוה \" פ עה \" צ ."],[9200230078,"78\nמענות קודש – ה ' תשד \" מ\nמצו \" ב השתתפות סמלית .\nלהחזיר\n[ כ \" ק אדמו \" ר שליט \" א צירף 18 דולר .]\nקנ ה\nי \" ז אד \" ש ][\nממענה להרב יעקב עמנואל שוחט בקשר לתרגום ה \" הגדה של פסח \"\nלאנגלית שערך , ובתרגום שם השם כתב \" Hashem \" ( ס ' יומן \" רישומה\nשל שנה \" ע ' 184 לקו \" ש חכ \" ד ע '. 410 :)\n.[ ]. אין שמים לב לענין עקרי במצב ההוה המציאות היא שכו \" כ אומרים\nרק התירגום .\nבאמירת תיבת \" השם \" אין בזה שם כלל , באמירת תיבת \" לאָרד \"\nעאכו \" כ D - G פס \" ד אדה \" ז שיש בזה קדושה ויותר מזה .\nקנ ו\nח \" י אד \" ש ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" המרכזית שכתבו : \" מצו \" ב מכ '\nשבדעתינו לשלוח ל . . וכ \" ז לאחר הדיבור עמו כמה פעמים . המכ ' הי '\nלמראי עיניו של הרב ח . מ . א . שי ' חדוקוב \" ( מצילום כתי \" ק – נדפס לעיל .\nהמענה מתפרסם בזה לראשונה באדיבות מערכת הספר \" שליחות\nכהלכתה \" וזכות הרבים תלוי ' בהם :)\nכפשוט שייך להנהלת צעירי אגודת חב \" ד ][\nלהחזיר המצו \" ב"],[9200230079,"79\nמענות קודש – ה ' תשד \" מ\nקנ ז\nכ \" ד אד \" ש ][\nמענה להשליח ר ' יהודה ליב ראסקין ( ס ' יומן \" רישומה של שנה \" ע ' 185-\n6 תשורה ווייטמאן י \" א אלול תשס \" ו :).\n[1 ] במכתבו כתב : \" בהמשך להדפסת התניא בשפה הערבית הבאתי כעת\nהפרווס ( עלי ההגהה ) מהתחלה ועד סוף פרק כ \" ה בחלק א ' בתניא ,\nשלמדתי ביחד עם הרב דוד בוסקילה בעזרת התרגום בצרפתית ובעזרת\nהביאורים בתניא של הר \" י שי ' ווינברג שמתורגם ללה \" ק . והנני מוסר\nכאן בנ . י . לבית דפוס א ופזעצן כי שם במרוקו א \" א לעשות זה , ואח \" כ\nאי \" ה לסדר שם באופסעט כמו שסדרתי אגרת התשובה . והנני לשאול\nמכ \" ק שליט \" א : א ) אם אפשר בשער - בלאט לכתוב שנת הארבעים\nלהילולא והסתלקות הרב המקובל ר ' לוי יצחק נ \" ע , כי בכל פעם שהנני\nמדפיס משהו במרוקו הנני מזכיר את ההורים של כ \" ק שליט \" א – ככה\nהדפסנו כעת בסוף התניא של מקנס ככה נדפיס אי \" ה בשארי התניא\nהעומדים להדפיס – בהיות שזכיתי לראותם .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n1 ) באפשר , אבל רק בהשער הראשון – דמוזכר רק אוצה \" ח – ולא בזה\nשהוא העתק השער דאדה \" ז .\n2 ) הרה \" ג והרה \" ח [ המקובל ] .\n[2 ] במכתבו כתב : \" אם אפשר . . ב ) להוסיף בהתחלה קטע משיחת כ \" ק\nשליט \" א מש \" פ שמות מבה \" ח שבט תשל \" ז שהי ' מדובר אודות התניא\nבשפה הערבית , סידר ועיבד וכו ' ר ' דוד שי ' פלדמן מהנחות בלה \" ק וג \" כ\nהוסיף מראי מקומות . אבקש ברכת כ \" ק אדמו \" ר שליט \" א שאזכה\nלהדפיס בלי שום מניעות ו עיכובים מבית ובחוץ , ושאזכה להביאו ליום\nההילולא הארבעים כ ' מנ \" א ה ' תשד \" מ .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\n3 בהוספה בסופו .)\nמצורף בזה לצדקה ( החילוף ) במדינתם .\n[ כ \" ק אדמו \" ר שליט \" א צירף שלשה מטבעות של חצי דולר מכסף טהור .]"],[9200230080,"80\nמענות קודש – ה ' תשד \" מ\nקנ ח\nכ \" ה אד \" ש ][\nמענה לר ' צבי מאיר שטיינמעץ ( מצילום כתי \" ק – תשורה ווילענסקי י \" ד\nכסלו תש \" פ :)\n[1 ] במכתבו כתב : \" אע \" פ שיום הולדתי הששים ותשעה לאויוש \" ט יחול\nאי \" ה רק בעוד עשרה ימים בש \" ק ה ' ניסן , אקדים לבא לפני כסא כ \" ק\nאד \" ש לפני שבת מברכין ניסן .\"\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול ובחץ את התיבות \" שיום הולדתי ,\"\nוכתב :\nמנהגי\n[2 ] במכתבו כתב : \" והנה חלפה כצל עובר השנה שעברה וה \" מאזן \" השנתי\nשל כותב השורות האלה לדאבון נפשי אין בו לשמוח ולשמח בנוגע לתורה\nועבודה .\"\nמענה כ \" ק אדמו \" ר שליט \" א :\nדו \" ח ופנ \" נ ות \" ח על הבשו \" ט כן יוסיף לעת \" ל .\nכמובן תמהתי ביותר על כתבו והנה חלפה כצל עובר השנה שעברה ][\nאלא שנפל ברעיוני שמובן ע \" פ דברי אדה \" ז ( תו \" א ד \" ה שה \" מ גו '\nכחולמים ) דקאי על זמן הגלות ואמחז \" ל דאין חלום בלא דב \" ט ( אפילו\nדיוסף ); והצל – הוא צילא דמהימנותא הפצת התומ \" צ ועד לחוצה )(\nו \" עובר \" – דב \" ט . ואתו הסליחה .\nלהחזיר המצו \" ב ( שג \" ז מאשר הנ \" ל .)\nקנ ט\nכ \" ה אד \" ש ][\nמענה למארגני \" מלוה מלכה \" במוצש \" ק תזריע לטובת בנין \" הכנסת\nאורחים \" ומקוה - טהרה המרכזית של שכונת קראונהייטס ( ס ' יומן\nרישומה של שנה \" ע '\" 180 :)\nהזכרתי היום כ \" ה אד \" ש על הציון ויה \" ר שיהא בהצלחה ."],[9200230081,"81\nמענות קודש – ה ' תשד \" מ\nקס\nכ \" ח אד \" ש ][\nמענה לר ' דוד דייטש שהכניס מכתב א ' העסקנים שבו כותב ע \" ד בנין\nמסויים שנקנה בשכונת קראונהייטס ומלכתחילה הייתה הסברא לעשות\nשם מלון , אך לאחמ \" כ החליטו שהמקום מוכשר למוסד חינוך ; ועתה\nעומדים בדברים עם מוסד חינוך \" אהלי תורה \" שהם יעברו לבנין האמור ,\nובנין 667 איסטערן פארקוויי ששם שוכן חלק מהמוסד , יוסב למלון\nמהעתקת המזכיר . המענה מתפרסם בזה לראשונה באדיבות ר ' פסח שי '(\nלאופער וזכות הרבים תלוי ' בו :)\nכ \" ק אדמו \" ר שליט \" א סימן בעיגול את הקטע : \" ומובן שאנו נעשה את\nתכניותינו בבנין 667 א . פ . כנ \" ל לעשות מלון חוץ מהאולמות שישנם שם\nכבר \", וכתב :\nאינו מסוגל לזה כלל וכלל כפשוט\nקס א\nחורף ][\nמענה לא ' שצייר לפי דמיונו ציור של אדמו \" ר האמצעי – בדמיון מסויים\nלאדמו \" ר הזקן , וציור של אדמו \" ר מהר \" ש – בדמיון מסויים לאדמו \" ר\nמהריי \" ץ (\" בית חיינו \" תשד \" מ גליון 24 :)\nחס וחלילה וח \" ו לצייר תמונות ע \" פ הדמיון ולייחסם לרבותינו נשיאינו .\nקס ב\nער \" ח ניסן ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" המרכזית שכתבו ע \" ד סידור \" 83\nימי חינוך \" ע \" י בית הנבחרים באלבאני נ . י . בקשר עם יום הבהיר י \" א\nניסן , ובמשך המעמד ידפיסו שם את ס ' התניא בארגונו של השליח דשם\nר ' ישראל אליעזר רובין , והכניסו את מה שהכין להדפיס בסוף ס ' התניא\n( מצילום כת י \" ק – קובץ \" Day Education \" שי \" ל ע \" י מערכת הספר\nועבדי דוד :)\"\"\n[1 על מה שכתבו : \" ומצו \" ב מה שרוצה לדפוס בסוף התניא \", כתב :]\n– בטח יוגה ע \" י היודע אנגלית צחה כו '"],[9200230082,"82\nמענות קודש – ה ' תשד \" מ\n[2 על מה שכתבו : \" והננו מבקשים ברכה להצלחה וכו ' בכהנ \" ל \", כתב :]\nאזכיר עה \" צ [ להצלחה רבה וכו ' בכהנ \" ל ]\nקס ג\nער \" ח ניסן ][\nמענה לר ' אהרן דוב הלפרין שהכניס את ביאור כ \" ק אדמו \" ר שליט \" א\nבסיפור הגמרא \" קם רבה ושחטי ' לרב זירא \" שמתכונן להדפיס בעיתון\n\" כפר חב \" ד \" שבעריכתו , לאחר שקיבל הסכמת כ \" ק אדמו \" ר שליט \" א\nוהוראתו שידפיס זאת בצירוף ההוספות שידוברו בהתועדות הבעל \" ט ,\nדש \" פ תזריע ( ס ' יומן \" ר ישומה של שנה \" ע ' 184 :)\nנת ' ות \" ח ( על ההשתדלות וכו '. ברישום על הסדר דהענינים וכו ' .)\nבע ' ג ( דהמצו \" ב ) שו \" ה זירא – צ \" ל רבה .\nחבל שלא הכניסו שגם ר \" ז הי ' כהן . – ירושלמי ברכות פ \" ז ה \" ג . פ \" ח\nה \" ה . ועוד .\nקס ד\nד ' ניסן ][\nמענה להנהלת \" צעירי אגודת חב \" ד \" המרכזית שכתבו : \" ר ' . . וזוגתו . .\nמוויליאמסבורג שנתקרבו לליובאוויטש , נדבו $500 על הדפסת\nהסטיקערס שיוכלו להדביק בסידור וכו ' אודות הריני מקבל . . אך\nצדיקים . . ומצו \" ב מה שכבר הדפיסו 6,000 ועוד אי \" ה ידפיסו 18,000 .\nובקשו לכתוב או דותם לכ \" ק אדמו \" ר שליט \" א ולבקש ברכה שיפקדו\nבזחו \" ק בקרוב ממש \" ( מצילום כתי \" ק – נדפס לעיל . המענה מתפרסם\nבזה לראשונה באדיבות מערכת הספר \" ועבדי דוד \" וזכות הרבים תלוי '\nבהם :)\nוגדול הזכות וכו '"]]});
